export default "ait _aresolve_read_policy(\\n        current_user,\\n        purpose,\\n        default=ModelProviderPolicyPurpose.CONFIGURE,\\n        attributes=provider_policy_attributes,\\n    )\\n    return await _get_enabled_providers_result(\\n        session=session,\\n        current_user=current_user,\\n        provider_policy=provider_policy,\\n        providers=providers,\\n    )\\n\\n\\n@router.post(\\\"/validate-provider\\\", status_code=200, response_model=ValidateProviderResponse)\\nasync def validate_provider(\\n    request: ValidateProviderRequest,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n) -> ValidateProviderResponse:\\n    \\\"\\\"\\\"Validate provider credentials before saving.\\n\\n    This endpoint checks if the provided credentials are valid by attempting\\n    to connect to the provider. Use this for real-time validation in the UI.\\n    \\\"\\\"\\\"\\n    await _require_provider(\\n        current_user,\\n        request.provider,\\n        ModelProviderPolicyPurpose.CONFIGURE,\\n        provider_policy_attributes,\\n    )\\n\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    try:\\n        # Validate the credentials\\n        validate_model_provider_key(request.provider, request.variables)\\n        return ValidateProviderResponse(valid=True, error=None)\\n    except ValueError as e:\\n        return ValidateProviderResponse(valid=False, error=str(e))\\n    except (ConnectionError, TimeoutError, RuntimeError, KeyError, AttributeError, TypeError) as e:\\n        logger.exception(\\\"Unexpected error validating provider %s\\\", request.provider)\\n        return ValidateProviderResponse(valid=False, error=f\\\"Validation failed: {e}\\\")\\n\\n\\nasync def _get_disabled_models(session: DbSession, current_user: CurrentActiveUser) -> set[str]:\\n    \\\"\\\"\\\"Helper function to get the set of disabled model IDs.\\\"\\\"\\\"\\n    variable_service = get_variable_service()\\n    if not isinstance(variable_service, DatabaseVariableService):\\n        return set()\\n\\n    try:\\n        var = await variable_service.get_variable_object(\\n            user_id=current_user.id, name=DISABLED_MODELS_VAR, session=session\\n        )\\n        if var.value:  # This checks for both None and empty string\\n            try:\\n                parsed_value = json.loads(var.value)\\n                # Validate it's a list of strings\\n                if not isinstance(parsed_value, list):\\n                    logger.warning(\\\"Invalid disabled models format for user %s: not a list\\\", current_user.id)\\n                    return set()\\n                # Ensure all items are strings\\n                return {str(item) for item in parsed_value if isinstance(item, str)}\\n            except (json.JSONDecodeError, TypeError):\\n                logger.warning(\\\"Failed to parse disabled models for user %s\\\", current_user.id, exc_info=True)\\n                return set()\\n    except ValueError:\\n        # Variable not found, return empty set\\n        pass\\n    return set()\\n\\n\\nasync def _get_enabled_models(session: DbSession, current_user: CurrentActiveUser) -> set[str]:\\n    \\\"\\\"\\\"Helper function to get the set of explicitly enabled model IDs.\\n\\n    These are models that were NOT default but were explicitly enabled by the user.\\n    \\\"\\\"\\\"\\n    variable_service = get_variable_service()\\n    if not isinstance(variable_service, DatabaseVariableService):\\n        return set()\\n\\n    try:\\n        var = await variable_service.get_variable_object(\\n            user_id=current_user.id, name=ENABLED_MODELS_VAR, session=session\\n        )\\n        # Strip whitespace and check if value is non-empty\\n        if var.value and (value_stripped := var.value.strip()):\\n            try:\\n                parsed_value = json.loads(value_stripped)\\n                # Validate it's a list of strings\\n                if not isinstance(parsed_value, list):\\n                    logger.warning(\\\"Invalid enabled models format for user %s: not a list\\\", current_user.id)\\n                    return set()\\n                # Ensure all items are strings\\n                return {str(item) for item in parsed_value if isinstance(item, str)}\\n            except (json.JSONDecodeError, TypeError):\\n                # Log at debug level to avoid flooding logs with expected edge cases\\n                logger.debug(\\\"Failed to parse enabled models for user %s: %s\\\", current_user.id, var.value)\\n                return set()\\n    except ValueError:\\n        # Variable not found, return empty set\\n        pass\\n    return set()\\n\\n\\ndef build_model_providers_by_name(\\n    all_models_by_provider: list[dict] | None = None,\\n) -> dict[str, set[str]]:\\n    \\\"\\\"\\\"Build a catalog index used to migrate legacy bare-name status entries.\\\"\\\"\\\"\\n    if all_models_by_provider is None:\\n        all_models_by_provider = get_unified_models_detailed(\\n            include_unsupported=True,\\n            include_deprecated=True,\\n        )\\n\\n    providers_by_name: dict[str, set[str]] = {}\\n    for provider_dict in all_models_by_provider:\\n        provider = provider_dict.get(\\\"provider\\\")\\n        if not isinstance(provider, str):\\n            continue\\n        for model in provider_dict.get(\\\"models\\\", []):\\n            model_name = model.get(\\\"model_name\\\")\\n            if isinstance(model_name, str):\\n                providers_by_name.setdefault(model_name, set()).add(provider)\\n    return providers_by_name\\n\\n\\ndef normalize_model_status_entries(\\n    entries: set[str],\\n    providers_by_name: dict[str, set[str]],\\n) -> set[str]:\\n    \\\"\\\"\\\"Expand known legacy bare names to every matching provider identity.\\n\\n    Bare entries historically applied globally. Expanding all matching catalog\\n    providers preserves that state while allowing the current write to change a\\n    single provider. Unknown bare names remain intact for read compatibility.\\n    \\\"\\\"\\\"\\n    normalized: set[str] = set()\\n    for entry in entries:\\n        providers = providers_by_name.get(entry)\\n        if providers:\\n            normalized.update(model_status_key(provider, entry) for provider in providers)\\n        else:\\n            normalized.add(entry)\\n    return normalized\\n\\n\\ndef _build_model_default_flags(\\n    all_models_by_provider: list[dict] | None = None,\\n) -> dict[str, bool]:\\n    \\\"\\\"\\\"Build a map of typed and legacy model identities to default status.\\n\\n    Returns:\\n        Dictionary mapping model-status identities to default status\\n    \\\"\\\"\\\"\\n    if all_models_by_provider is None:\\n        all_models_by_provider = get_unified_models_detailed(\\n            include_unsupported=True,\\n            include_deprecated=True,\\n        )\\n\\n    is_default_model: dict[str, bool] = {}\\n    for provider_dict in all_models_by_provider:\\n        provider = provider_dict.get(\\\"provider\\\")\\n        if not isinstance(provider, str):\\n            continue\\n        for model in provider_dict.get(\\\"models\\\", []):\\n            model_name = model.get(\\\"model_name\\\")\\n            if not isinstance(model_name, str):\\n                continue\\n            metadata = model.get(\\\"metadata\\\", {})\\n            is_default = metadata.get(\\\"default\\\", False)\\n            model_type = metadata.get(\\\"model_type\\\", \\\"llm\\\")\\n            legacy_key = model_status_key(provider, model_name)\\n            # OR defaults across typed rows sharing a provider/name identity.\\n            is_default_model[legacy_key] = is_default_model.get(legacy_key, False) or is_default\\n            if model_type in {\\\"llm\\\", \\\"embeddings\\\"}:\\n                is_default_model[model_status_key(provider, model_name, model_type)] = is_default\\n\\n    return is_default_model\\n\\n\\ndef _build_model_types_by_identity(\\n    all_models_by_provider: list[dict] | None = None,\\n) -> dict[str, set[str]]:\\n    \\\"\\\"\\\"Build a map of provider-qualified model identities to catalog model types.\\\"\\\"\\\"\\n    if all_models_by_provider is None:\\n        all_models_by_provider = get_unified_models_detailed(\\n            include_unsupported=True,\\n            include_deprecated=True,\\n        )\\n\\n    model_types_by_identity: dict[str, set[str]] = {}\\n    for provider_dict in all_models_by_provider:\\n        provider = provider_dict.get(\\\"provider\\\")\\n        if not isinstance(provider, str):\\n            continue\\n        for model in provider_dict.get(\\\"models\\\", []):\\n            model_name = model.get(\\\"model_name\\\")\\n            if not isinstance(model_name, str):\\n                continue\\n            model_type = model.get(\\\"metadata\\\", {}).get(\\\"model_type\\\", \\\"llm\\\")\\n            if model_type not in {\\\"llm\\\", \\\"embeddings\\\"}:\\n                continue\\n            identity = model_status_key(provider, model_name)\\n            model_types_by_identity.setdefault(identity, set()).add(model_type)\\n\\n    return model_types_by_identity\\n\\n\\ndef _discard_typed_status_variants(entries: set[str], provider: str, model_name: str) -> None:\\n    \\\"\\\"\\\"Remove typed statuses for one provider/name while leaving legacy identities intact.\\\"\\\"\\\"\\n    for entry in tuple(entries):\\n        entry_provider, entry_model_name, entry_model_type = parse_model_status_key(entry)\\n        if entry_provider == provider and entry_model_name == model_name and entry_model_type is not None:\\n            entries.discard(entry)\\n\\n\\ndef _expand_matching_legacy_status(\\n    entries: set[str],\\n    provider: str,\\n    model_name: str,\\n    model_types: set[str],\\n) -> None:\\n    \\\"\\\"\\\"Replace one legacy provider/name status with its typed equivalents.\\\"\\\"\\\"\\n    legacy_key = model_status_key(provider, model_name)\\n    if legacy_key not in entries:\\n        return\\n\\n    entries.discard(legacy_key)\\n    entries.update(model_status_key(provider, model_name, model_type) for model_type in model_types)\\n\\n\\ndef _update_model_sets(\\n    updates: list[ModelStatusUpdate],\\n    disabled_models: set[str],\\n    explicitly_enabled_models: set[str],\\n    is_default_model: dict[str, bool],\\n    model_types_by_identity: dict[str, set[str]] | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Update disabled and enabled model sets based on user requests.\\n\\n    Args:\\n        updates: List of model status updates from user\\n        disabled_models: Set of disabled model IDs (modified in place)\\n        explicitly_enabled_models: Set of explicitly enabled model IDs (modified in place)\\n        is_default_model: Map of provider-qualified model identities to default status\\n        model_types_by_identity: Catalog model types keyed by provider-qualified identity\\n    \\\"\\\"\\\"\\n    model_types_by_identity = model_types_by_identity or {}\\n\\n    for update in updates:\\n        legacy_key = model_status_key(update.provider, update.model_id)\\n\\n        if update.model_type is not None:\\n            # Expand legacy name-level status to typed keys before a typed update.\\n            legacy_types = model_types_by_identity.get(legacy_key) or {\\\"llm\\\"}\\n            _expand_matching_legacy_status(\\n                disabled_models,\\n                update.provider,\\n                update.model_id,\\n                legacy_types,\\n            )\\n            _expand_matching_legacy_status(\\n                explicitly_enabled_models,\\n                update.provider,\\n                update.model_id,\\n                legacy_types,\\n            )\\n            status_key = model_status_key(update.provider, update.model_id, update.model_type)\\n        else:\\n            # Clear typed variants before writing legacy name-level state.\\n            _discard_typed_status_variants(disabled_models, update.provider, update.model_id)\\n            _discard_typed_status_variants(explicitly_enabled_models, update.provider, update.model_id)\\n            status_key = legacy_key\\n\\n        model_is_default = is_default_model.get(status_key, is_default_model.get(legacy_key, False))\\n\\n        if update.enabled:\\n            # User wants to enable the model\\n            disabled_models.discard(status_key)\\n            # Foundry seed defaults are suggestions; keep them explicitly enabled.\\n            if update.provider in EXPLICIT_ENABLE_ONLY_PROVIDERS or not model_is_default:\\n                explicitly_enabled_models.add(status_key)\\n            else:\\n                explicitly_enabled_models.discard(status_key)\\n        else:\\n            # User wants to disable the model\\n            disabled_models.add(status_key)\\n            explicitly_enabled_models.discard(status_key)\\n\\n\\nasync def _save_model_list_variable(\\n    variable_service: DatabaseVariableService,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    var_name: str,\\n    model_set: set[str],\\n) -> None:\\n    \\\"\\\"\\\"Save or update a model list variable.\\n\\n    Args:\\n        variable_service: The database variable service\\n        session: Database session\\n        current_user: Current active user\\n        var_name: Name of the variable to save\\n        model_set: Set of model names to save\\n\\n    Raises:\\n        HTTPException: If there's an error saving the variable\\n    \\\"\\\"\\\"\\n    from langflow.services.database.models.variable.model import VariableUpdate\\n\\n    models_json = json.dumps(list(model_set))\\n\\n    try:\\n        existing_var = await variable_service.get_variable_object(\\n            user_id=current_user.id, name=var_name, session=session\\n        )\\n        if existing_var is None or existing_var.id is None:\\n            msg = f\\\"Variable {var_name} not found\\\"\\n            raise ValueError(msg)\\n\\n        # Update or delete based on whether there are models\\n        if model_set or var_name == DISABLED_MODELS_VAR:\\n            # Always update disabled models, even if empty\\n            # Only update enabled models if non-empty\\n            await variable_service.update_variable_fields(\\n                user_id=current_user.id,\\n                variable_id=existing_var.id,\\n                variable=VariableUpdate(id=existing_var.id, name=var_name, value=models_json, type=GENERIC_TYPE),\\n                session=session,\\n            )\\n        else:\\n            # No explicitly enabled models, delete the variable\\n            await variable_service.delete_variable(user_id=current_user.id, name=var_name, session=session)\\n    except ValueError:\\n        # Variable not found, create new one if there are models\\n        if model_set:\\n            await variable_service.create_variable(\\n                user_id=current_user.id,\\n                name=var_name,\\n                value=models_json,\\n                type_=GENERIC_TYPE,\\n                session=session,\\n            )\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        logger.exception(\\n            \\\"Failed to save model list variable %s for user %s\\\",\\n            var_name,\\n            current_user.id,\\n        )\\n        raise HTTPException(\\n            status_code=500,\\n            detail=\\\"Failed to save model configuration. Please try again later.\\\",\\n        ) from e\\n\\n\\nasync def _get_enabled_models_result(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy: ModelProviderPolicySnapshot,\\n    model_names: list[str] | None = None,\\n    provider_status: dict[str, bool] | None = None,\\n):\\n    \\\"\\\"\\\"Get enabled models for the current user.\\\"\\\"\\\"\\n    all_models_by_provider = get_unified_models_detailed(\\n        include_unsupported=True,\\n        include_deprecated=True,\\n    )\\n\\n    if provider_status is None:\\n        enabled_providers_result = await _get_enabled_providers_result(\\n            session=session,\\n            current_user=current_user,\\n            provider_policy=provider_policy,\\n        )\\n        provider_status = enabled_providers_result.get(\\\"provider_status\\\", {})\\n\\n    all_models_by_provider = [\\n        provider_data\\n        for provider_data in all_models_by_provider\\n        if provider_policy.allows(provider_data.get(\\\"provider\\\", \\\"\\\"))\\n    ]\\n    configured_providers = {\\n        provider for provider, configured in provider_status.items() if configured and provider_policy.allows(provider)\\n    }\\n    replace_with_live_models(all_models_by_provider, current_user.id, configured_providers)\\n\\n    # Get disabled and explicitly enabled models lists\\n    disabled_models = await _get_disabled_models(session=session, current_user=current_user)\\n    explicitly_enabled_models = await _get_enabled_models(session=session, current_user=current_user)\\n    inject_custom_enabled_models(all_models_by_provider, explicitly_enabled_models)\\n    all_models_by_provider = [\\n        provider_data\\n        for provider_data in all_models_by_provider\\n        if provider_policy.allows(provider_data.get(\\\"provider\\\", \\\"\\\"))\\n    ]\\n\\n    enabled_models: dict[str, dict[str, bool]] = {}\\n    enabled_models_by_type: dict[str, dict[str, dict[str, bool]]] = {}\\n\\n    for provider_dict in all_models_by_provider:\\n        provider = provider_dict.get(\\\"provider\\\")\\n        models = provider_dict.get(\\\"models\\\", [])\\n\\n        # Initialize provider dict if not exists\\n        if provider not in enabled_models:\\n            enabled_models[provider] = {}\\n            enabled_models_by_type[provider] = {}\\n\\n        for model in models:\\n            model_name = model.get(\\\"model_name\\\")\\n            metadata = model.get(\\\"metadata\\\", {})\\n\\n            # Check if model is deprecated or not supported\\n            is_deprecated = metadata.get(\\\"deprecated\\\", False)\\n            is_not_supported = metadata.get(\\\"not_supported\\\", False)\\n            is_default = metadata.get(\\\"default\\\", False)\\n            model_type = metadata.get(\\\"model_type\\\", \\\"llm\\\")\\n            if model_type not in {\\\"llm\\\", \\\"embeddings\\\"}:\\n                model_type = \\\"llm\\\"\\n\\n            # Foundry requires explicit enable; seed defaults are not auto-on.\\n            requires_explicit = provider in EXPLICIT_ENABLE_ONLY_PROVIDERS\\n            explicitly_on = model_status_contains(\\n                explicitly_enabled_models,\\n                provider,\\n                model_name,\\n                model_type=model_type,\\n            )\\n            explicitly_off = model_status_contains(\\n                disabled_models,\\n                provider,\\n                model_name,\\n                model_type=model_type,\\n            )\\n            is_enabled = (\\n                provider_status.get(provider, False)\\n                and not is_deprecated\\n                and not is_not_supported\\n                and (explicitly_on if requires_explicit else (is_default or explicitly_on))\\n                and not explicitly_off\\n            )\\n            # Per-type map is exact; flat map ORs rows that share provider/name.\\n            models_for_type = enabled_models_by_type[provider].setdefault(model_type, {})\\n            models_for_type[model_name] = models_for_type.get(model_name, False) or is_enabled\\n            enabled_models[provider][model_name] = enabled_models[provider].get(model_name, False) or is_enabled\\n\\n    result = {\\n        \\\"enabled_models\\\": enabled_models,\\n        \\\"enabled_models_by_type\\\": enabled_models_by_type,\\n    }\\n\\n    if model_names:\\n        # Filter enabled_models by requested models\\n        filtered_enabled: dict[str, dict[str, bool]] = {}\\n        for provider, models_dict in enabled_models.items():\\n            filtered_models = {m: v for m, v in models_dict.items() if m in model_names}\\n            if filtered_models:\\n                filtered_enabled[provider] = filtered_models\\n\\n        filtered_enabled_by_type: dict[str, dict[str, dict[str, bool]]] = {}\\n        for provider, models_by_type in enabled_models_by_type.items():\\n            filtered_models_by_type: dict[str, dict[str, bool]] = {}\\n            for model_type, models_dict in models_by_type.items():\\n                filtered_models = {m: v for m, v in models_dict.items() if m in model_names}\\n                if filtered_models:\\n                    filtered_models_by_type[model_type] = filtered_models\\n            if filtered_models_by_type:\\n                filtered_enabled_by_type[provider] = filtered_models_by_type\\n\\n        return {\\n            \\\"enabled_models\\\": filtered_enabled,\\n            \\\"enabled_models_by_type\\\": filtered_enabled_by_type,\\n        }\\n\\n    return result\\n\\n\\n@router.get(\\\"/enabled_models\\\", status_code=200)\\nasync def get_enabled_models(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    model_names: Annotated[list[str] | None, Query()] = None,\\n    purpose: Annotated[ProviderReadPurpose | None, Query()] = None,\\n):\\n    \\\"\\\"\\\"Get policy-visible enabled models for the current user.\\\"\\\"\\\"\\n    provider_policy = await _aresolve_read_policy(\\n        current_user,\\n        purpose,\\n        default=ModelProviderPolicyPurpose.CONFIGURE,\\n        attributes=provider_policy_attributes,\\n    )\\n    return await _get_enabled_models_result(\\n        session=session,\\n        current_user=current_user,\\n        provider_policy=provider_policy,\\n        model_names=model_names,\\n    )\\n\\n\\n@router.post(\\\"/enabled_models\\\", status_code=200)\\nasync def update_enabled_models(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    updates: list[ModelStatusUpdate],\\n):\\n    \\\"\\\"\\\"Update enabled status for specific models.\\n\\n    Accepts a list of model IDs with their desired enabled status.\\n    This only affects model-level enablement - provider credentials must still be configured.\\n    \\\"\\\"\\\"\\n    # Persists the enabled/disabled model lists as the user's own Variables: a\\n    # variable WRITE. Enforce so the external access ceiling caps a \\\"viewer\\\";\\n    # the owner with no ceiling fast-paths via owner-override.\\n    await ensure_variable_permission(\\n        current_user,\\n        VariableAction.WRITE,\\n        variable_user_id=current_user.id,\\n    )\\n    variable_service = get_variable_service()\\n    if not isinstance(variable_service, DatabaseVariableService):\\n        raise HTTPException(\\n            status_code=500,\\n            detail=\\\"Variable service is not an instance of DatabaseVariableService\\\",\\n        )\\n\\n    # Resolve the hierarchy once before reading credentials or mutating model\\n    # status. Reuse the snapshot throughout the request so authorization cannot\\n    # change between validation, persistence, and response filtering.\\n    provider_policy = await _aresolve_policy(\\n        current_user,\\n        ModelProviderPolicyPurpose.CONFIGURE,\\n        provider_policy_attributes,\\n    )\\n\\n    # Limit batch size to prevent abuse\\n    if len(updates) > MAX_BATCH_UPDATE_SIZE:\\n        raise HTTPException(\\n            status_code=400,\\n            detail=f\\\"Cannot update more than {MAX_BATCH_UPDATE_SIZE} models at once\\\",\\n        )\\n\\n    # Get current disabled and explicitly enabled models\\n    disabled_models = await _get_disabled_models(session=session, current_user=current_user)\\n    explicitly_enabled_models = await _get_enabled_models(session=session, current_user=current_user)\\n\\n    all_models_by_provider = get_unified_models_detailed(\\n        include_unsupported=True,\\n        include_deprecated=True,\\n    )\\n    is_default_model = _build_model_default_flags(all_models_by_provider)\\n    model_types_by_identity = _build_model_types_by_identity(all_models_by_provider)\\n    providers_by_name = build_model_providers_by_name(all_models_by_provider)\\n    # Live/custom models may not be in the static catalog. The provider in this\\n    # request still gives a known identity for migrating a matching bare entry.\\n    for update in updates:\\n        providers_by_name.setdefault(update.model_id, set()).add(update.provider)\\n\\n    disabled_models = normalize_model_status_entries(disabled_models, providers_by_name)\\n    explicitly_enabled_models = normalize_model_status_entries(explicitly_enabled_models, providers_by_name)\\n\\n    unavailable_models: dict[tuple[str, str], str] = {}\\n    for provider_dict in all_models_by_provider:\\n        provider = provider_dict.get(\\\"provider\\\")\\n        if not isinstance(provider, str):\\n            continue\\n        for model in provider_dict.get(\\\"models\\\", []):\\n            model_name = model.get(\\\"model_name\\\")\\n            if not isinstance(model_name, str):\\n                continue\\n            metadata = model.get(\\\"metadata\\\", {})\\n            if metadata.get(\\\"deprecated\\\", False):\\n                unavailable_models[(provider, model_name)] = \\\"deprecated\\\"\\n            elif metadata.get(\\\"not_supported\\\", False):\\n                unavailable_models[(provider, model_name)] = \\\"not supported\\\"\\n\\n    # Update model sets based on user requests\\n    # For any model being enabled, validate the provider credentials\\n    for update in updates:\\n        if update.enabled:\\n            _require_provider_from_policy(provider_policy, update.provider)\\n            unavailable_reason = unavailable_models.get((update.provider, update.model_id))\\n            if unavailable_reason:\\n                raise HTTPException(\\n                    status_code=400,\\n                    detail=f\\\"Cannot enable {unavailable_reason} model: {update.model_id}\\\",\\n                )\\n\\n            from lfx.base.models.unified_models import get_all_variables_for_provider, validate_model_provider_key\\n\\n            # Get variables from DB or environment\\n            variables = get_all_variables_for_provider(current_user.id, update.provider)\\n\\n            try:\\n                # Validate the credentials\\n                validate_model_provider_key(update.provider, variables, model_name=update.model_id)\\n            except ValueError as e:\\n                # Validation failed - return 400 with error message\\n                raise HTTPException(\\n                    status_code=400,\\n                    detail=f\\\"Validation failed for {update.provider}: {e}\\\",\\n                ) from e\\n            except Exception as e:\\n                logger.exception(\\\"Unexpected error validating provider %s\\\", update.provider)\\n                raise HTTPException(\\n                    status_code=400,\\n                    detail=f\\\"Validation failed for {update.provider}: {e}\\\",\\n                ) from e\\n\\n    _update_model_sets(\\n        updates,\\n        disabled_models,\\n        explicitly_enabled_models,\\n        is_default_model,\\n        model_types_by_identity=model_types_by_identity,\\n    )\\n\\n    # Log the operation for audit trail\\n    logger.info(\\n        \\\"User %s updated model status: %d models affected\\\",\\n        current_user.id,\\n        len(updates),\\n    )\\n\\n    # Save updated model lists\\n    await _save_model_list_variable(variable_service, session, current_user, DISABLED_MODELS_VAR, disabled_models)\\n    await _save_model_list_variable(\\n        variable_service, session, current_user, ENABLED_MODELS_VAR, explicitly_enabled_models\\n    )\\n\\n    # Cleanup of a now-hidden provider remains allowed, but the response must\\n    # not echo hidden provider identities from persisted legacy state.\\n    def _visible_status_entries(entries: set[str]) -> list[str]:\\n        visible = []\\n        for entry in entries:\\n            provider, _model_name, _model_type = parse_model_status_key(entry)\\n            if provider is None or provider_policy.allows(provider):\\n                visible.append(entry)\\n        return visible\\n\\n    return {\\n        \\\"disabled_models\\\": _visible_status_entries(disabled_models),\\n        \\\"enabled_models\\\": _visible_status_entries(explicitly_enabled_models),\\n    }\\n\\n\\nclass DefaultModelRequest(BaseModel):\\n    \\\"\\\"\\\"Request model for setting default model.\\\"\\\"\\\"\\n\\n    model_name: str\\n    provider: str\\n    model_type: str  # 'language' or 'embedding'\\n\\n    @field_validator(\\\"model_name\\\", \\\"provider\\\")\\n    @classmethod\\n    def validate_non_empty_string(cls, v: str) -> str:\\n        \\\"\\\"\\\"Ensure strings are non-empty and reasonable length.\\\"\\\"\\\"\\n        if not v or not v.strip():\\n            msg = \\\"Field cannot be empty\\\"\\n            raise ValueError(msg)\\n        if len(v) > MAX_STRING_LENGTH:\\n            msg = f\\\"Field exceeds maximum length of {MAX_STRING_LENGTH} characters\\\"\\n            raise ValueError(msg)\\n        return v.strip()\\n\\n    @field_validator(\\\"model_type\\\")\\n    @classmethod\\n    def validate_model_type(cls, v: str) -> str:\\n        \\\"\\\"\\\"Ensure model_type is valid.\\\"\\\"\\\"\\n        if v not in (\\\"language\\\", \\\"embedding\\\"):\\n            msg = \\\"model_type must be 'language' or 'embedding'\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n\\n@router.get(\\\"/default_model\\\", status_code=200)\\nasync def get_default_model(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    model_type: Annotated[str, Query(description=\\\"Type of model: 'language' or 'embedding'\\\")] = \\\"language\\\",\\n):\\n    \\\"\\\"\\\"Get the default model for the current user.\\\"\\\"\\\"\\n    provider_policy = await _aresolve_policy(\\n        current_user,\\n        ModelProviderPolicyPurpose.USE,\\n        provider_policy_attributes,\\n    )\\n    variable_service = get_variable_service()\\n    if not isinstance(variable_service, DatabaseVariableService):\\n        return {\\\"default_model\\\": None}\\n\\n    var_name = DEFAULT_LANGUAGE_MODEL_VAR if model_type == \\\"language\\\" else DEFAULT_EMBEDDING_MODEL_VAR\\n\\n    try:\\n        var = await variable_service.get_variable_object(user_id=current_user.id, name=var_name, session=session)\\n        if var.value:\\n            try:\\n                parsed_value = json.loads(var.value)\\n            except (json.JSONDecodeError, TypeError):\\n                logger.warning(\\\"Failed to parse default model for user %s\\\", current_user.id, exc_info=True)\\n                return {\\\"default_model\\\": None}\\n            else:\\n                # Validate structure\\n                if not isinstance(parsed_value, dict) or not all(\\n                    k in parsed_value for k in (\\\"model_name\\\", \\\"provider\\\", \\\"model_type\\\")\\n                ):\\n                    logger.warning(\\\"Invalid default model format for user %s\\\", current_user.id)\\n                    return {\\\"default_model\\\": None}\\n                if not provider_policy.allows(parsed_value[\\\"provider\\\"]):\\n                    return {\\\"default_model\\\": None}\\n                return {\\\"default_model\\\": parsed_value}\\n    except ValueError:\\n        # Variable not found\\n        pass\\n    return {\\\"default_model\\\": None}\\n\\n\\n@router.post(\\\"/default_model\\\", status_code=200)\\nasync def set_default_model(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    request: DefaultModelRequest,\\n):\\n    \\\"\\\"\\\"Set the default model for the current user.\\\"\\\"\\\"\\n    await _require_provider(\\n        current_user,\\n        request.provider,\\n        ModelProviderPolicyPurpose.USE,\\n        provider_policy_attributes,\\n    )\\n    # Creating/updating the default-model Variable is a variable WRITE. Enforce\\n    # so the external access ceiling caps a \\\"viewer\\\"; the owner with no ceiling\\n    # fast-paths via owner-override.\\n    await ensure_variable_permission(\\n        current_user,\\n        VariableAction.WRITE,\\n        variable_user_id=current_user.id,\\n    )\\n    variable_service = get_variable_service()\\n    if not isinstance(variable_service, DatabaseVariableService):\\n        raise HTTPException(\\n            status_code=500,\\n            detail=\\\"Variable service is not an instance of DatabaseVariableService\\\",\\n        )\\n\\n    var_name = DEFAULT_LANGUAGE_MODEL_VAR if request.model_type == \\\"language\\\" else DEFAULT_EMBEDDING_MODEL_VAR\\n\\n    # Log the operation for audit trail\\n    logger.info(\\n        \\\"User %s setting default %s model to %s (%s)\\\",\\n        current_user.id,\\n        request.model_type,\\n        request.model_name,\\n        request.provider,\\n    )\\n\\n    # Prepare the model data\\n    model_data = {\\n        \\\"model_name\\\": request.model_name,\\n        \\\"provider\\\": request.provider,\\n        \\\"model_type\\\": request.model_type,\\n    }\\n    model_json = json.dumps(model_data)\\n\\n    # Check if the variable already exists\\n    try:\\n        existing_var = await variable_service.get_variable_object(\\n            user_id=current_user.id, name=var_name, session=session\\n        )\\n        if existing_var is None or existing_var.id is None:\\n            msg = f\\\"Variable {DISABLED_MODELS_VAR} not found\\\"\\n            raise ValueError(msg)\\n        # Update existing variable\\n        from langflow.services.database.models.variable.model import VariableUpdate\\n\\n        await variable_service.update_variable_fields(\\n            user_id=current_user.id,\\n            variable_id=existing_var.id,\\n            variable=VariableUpdate(id=existing_var.id, name=var_name, value=model_json, type=GENERIC_TYPE),\\n            session=session,\\n        )\\n    except ValueError:\\n        # Variable not found, create new one\\n        await variable_service.create_variable(\\n            user_id=current_user.id,\\n            name=var_name,\\n            value=model_json,\\n            type_=GENERIC_TYPE,\\n            session=session,\\n        )\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        logger.exception(\\n            \\\"Failed to set default model for user %s\\\",\\n            current_user.id,\\n        )\\n        raise HTTPException(\\n            status_code=500,\\n            detail=\\\"Failed to set default model. Please try again later.\\\",\\n        ) from e\\n\\n    return {\\\"default_model\\\": model_data}\\n\\n\\n@router.delete(\\\"/default_model\\\", status_code=200)\\nasync def clear_default_model(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    _provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    model_type: Annotated[str, Query(description=\\\"Type of model: 'language' or 'embedding'\\\")] = \\\"language\\\",\\n):\\n    \\\"\\\"\\\"Clear the default model for the current user.\\\"\\\"\\\"\\n    # Deleting the default-model Variable is a variable DELETE. Enforce so the\\n    # external access ceiling caps a \\\"viewer\\\"; the owner with no ceiling\\n    # fast-paths via owner-override.\\n    await ensure_variable_permission(\\n        current_user,\\n        VariableAction.DELETE,\\n        variable_user_id=current_user.id,\\n    )\\n    variable_service = get_variable_service()\\n    if not isinstance(variable_service, DatabaseVariableService):\\n        raise HTTPException(\\n            status_code=500,\\n            detail=\\\"Variable service is not an instance of DatabaseVariableService\\\",\\n        )\\n\\n    var_name = DEFAULT_LANGUAGE_MODEL_VAR if model_type == \\\"language\\\" else DEFAULT_EMBEDDING_MODEL_VAR\\n\\n    # Log the operation for audit trail\\n    logger.info(\\n        \\\"User %s clearing default %s model\\\",\\n        current_user.id,\\n        model_type,\\n    )\\n\\n    # Check if the variable exists and delete it\\n    try:\\n        existing_var = await variable_service.get_variable_object(\\n            user_id=current_user.id, name=var_name, session=session\\n        )\\n        await variable_service.delete_variable(user_id=current_user.id, name=existing_var.name, session=session)\\n    except ValueError:\\n        # Variable not found, nothing to delete\\n        pass\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        logger.exception(\\n            \\\"Failed to clear default model for user %s\\\",\\n            current_user.id,\\n        )\\n        raise HTTPException(\\n            status_code=500,\\n            detail=\\\"Failed to clear default model. Please try again later.\\\",\\n        ) from e\\n\\n    return {\\\"default_model\\\": None}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/monitor.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8cc05698cc47549711fdd7b822b308e640aa77bcc844e283bca8115809232231\",\"content\":\"from typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, BackgroundTasks, Depends, HTTPException, Query\\nfrom fastapi_pagination import Page, Params\\nfrom fastapi_pagination.ext.sqlmodel import apaginate\\nfrom sqlalchemy.orm.exc import StaleDataError\\nfrom sqlmodel import col, delete, select\\n\\nfrom langflow.api.utils import DbSession, custom_params\\nfrom langflow.api.utils.flow_utils import compute_virtual_flow_id\\nfrom langflow.schema.message import MessageResponse\\nfrom langflow.services.auth.utils import get_current_active_superuser, get_current_active_user\\nfrom langflow.services.authorization import FlowAction, ensure_flow_permission\\nfrom langflow.services.authorization.fetch import authorized_or_owner_scoped\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.message.crud import (\\n    delete_messages_for_user,\\n    delete_messages_for_user_by_session,\\n    get_message_for_user,\\n    get_messages_for_user_by_session,\\n)\\nfrom langflow.services.database.models.message.model import (\\n    ALLOWED_MESSAGE_ORDER_FIELDS,\\n    MessageRead,\\n    MessageTable,\\n    MessageUpdate,\\n)\\nfrom langflow.services.database.models.transactions.crud import transform_transaction_table_for_logs\\nfrom langflow.services.database.models.transactions.model import TransactionLogsResponse, TransactionTable\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.database.models.vertex_builds.crud import (\\n    delete_vertex_builds_by_flow_id,\\n    get_vertex_builds_by_flow_id,\\n)\\nfrom langflow.services.database.models.vertex_builds.model import VertexBuildMapModel\\nfrom langflow.services.deps import get_memory_base_service, get_tracing_service\\nfrom langflow.services.tracing.langfuse import (\\n    delete_feedback_score,\\n    langfuse_is_configured,\\n    normalize_langfuse_trace_id,\\n    sync_feedback_score,\\n)\\n\\nrouter = APIRouter(prefix=\\\"/monitor\\\", tags=[\\\"Monitor\\\"])\\n\\nMESSAGE_UPDATE_FAILED = \\\"Could not update the message.\\\"\\n\\n# Message-history reads must never return an entire table: the editor polls\\n# this endpoint every few seconds, so an unbounded default serializes the full\\n# history on every request and freezes the UI on flows with large histories\\n# (issue #15023). Values match the list-endpoint defaults used by the authz\\n# routers (_LIST_DEFAULT_LIMIT / _LIST_MAX_LIMIT).\\n_MESSAGES_DEFAULT_LIMIT = 100\\n_MESSAGES_MAX_LIMIT = 200\\n\\n\\ndef _sorted_for_display(messages: list[MessageTable], *, order_by: str | None, descending: bool) -> list[MessageTable]:\\n    \\\"\\\"\\\"Re-order an already-bounded window into the caller's requested display order.\\\"\\\"\\\"\\n    if not order_by:\\n        return messages\\n    if order_by == \\\"timestamp\\\":\\n        return messages if descending else messages[::-1]\\n    # Text is nullable in storage; preserve stable ordering within equal values.\\n    return sorted(\\n        messages,\\n        key=lambda message: (getattr(message, order_by) is None, getattr(message, order_by) or \\\"\\\"),\\n        reverse=descending,\\n    )\\n\\n\\ndef _message_history_response(message: MessageTable) -> MessageResponse:\\n    \\\"\\\"\\\"Represent legacy NULL text as empty text in the existing response schema.\\\"\\\"\\\"\\n    if message.text is None:\\n        return MessageResponse.model_validate(message.model_dump() | {\\\"text\\\": \\\"\\\"})\\n    return MessageResponse.model_validate(message, from_attributes=True)\\n\\n\\nasync def _log_message_update_failure(error: Exception) -> None:\\n    from lfx.log.logger import logger\\n\\n    await logger.aerror(\\\"Message update failed\\\", error_type=type(error).__name__)\\n\\n\\n@router.get(\\\"/job_queue\\\", dependencies=[Depends(get_current_active_superuser)])\\nasync def job_queue_metrics() -> dict:\\n    \\\"\\\"\\\"Return a snapshot of job-queue observability metrics.\\n\\n    For the in-memory backend this exposes only ``backend`` and ``active_jobs``.\\n    For the Redis backend the snapshot also includes bridge counts, consumer\\n    wrappers, cancel-dispatcher liveness, and the cancel-stats counters\\n    (``published`` / ``marker_hit`` / ``dispatched_owned`` /\\n    ``dispatched_foreign`` / ``publish_errors`` / ``dispatcher_reconnects`` /\\n    ``polling_watchdog_kills`` / ``activity_touch_errors`` /\\n    ``activity_get_errors`` / ``activity_parse_errors`` /\\n    ``dispatcher_internal_errors``). ``dispatcher_reconnects`` tracks explicit\\n    dispatcher-loop retries and redis-py transparent pubsub reconnect callbacks.\\n\\n    Restricted to superusers because the snapshot exposes process-wide tenant\\n    activity (live job counts, cancel rates) \u2014 useful for ops, sensitive in\\n    multi-tenant deployments.\\n    \\\"\\\"\\\"\\n    from langflow.services.deps import get_queue_service\\n\\n    return get_queue_service().metrics_snapshot()\\n\\n\\ndef _get_positive_feedback_value(db_message: MessageTable) -> bool | None:\\n    properties = db_message.properties\\n    if hasattr(properties, \\\"positive_feedback\\\"):\\n        return properties.positive_feedback\\n    if isinstance(properties, dict):\\n        return properties.get(\\\"positive_feedback\\\")\\n    return None\\n\\n\\ndef _resolve_langfuse_trace_id(db_message: MessageTable) -> str | None:\\n    session_metadata = db_message.session_metadata or {}\\n    if isinstance(session_metadata, dict):\\n        return normalize_langfuse_trace_id(session_metadata.get(\\\"langfuse_trace_id\\\"))\\n    return None\\n\\n\\ndef _langfuse_feedback_sync_enabled() -> bool:\\n    \\\"\\\"\\\"Check both the global tracing kill switch and Langfuse credentials.\\n\\n    Used to gate background tasks so we don't enqueue work that would\\n    silently no-op when tracing is deactivated or Langfuse is unconfigured.\\n    \\\"\\\"\\\"\\n    tracing_service = get_tracing_service()\\n    if tracing_service.deactivated:\\n        return False\\n    return langfuse_is_configured()\\n\\n\\nasync def _ensure_flow_action_or_404(\\n    session: DbSession,\\n    *,\\n    flow_id: UUID,\\n    user: User,\\n    action: FlowAction,\\n) -> Flow | None:\\n    \\\"\\\"\\\"Load a flow (share-aware), enforce permission, return None if missing.\\\"\\\"\\\"\\n    flow = await authorized_or_owner_scoped(\\n        session,\\n        Flow,\\n        id_column=Flow.id,\\n        resource_id=flow_id,\\n        owner_column=Flow.user_id,\\n        owner_id=user.id,\\n    )\\n    if flow is None:\\n        return None\\n    await ensure_flow_permission(\\n        user,\\n        action,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=getattr(flow, \\\"workspace_id\\\", None),\\n        folder_id=getattr(flow, \\\"folder_id\\\", None),\\n    )\\n    return flow\\n\\n\\nasync def _purge_memory_base_session_data(user_id: UUID, session_ids: list[str]) -> None:\\n    \\\"\\\"\\\"Best-effort: drop ingested chunks for the deleted sessions from each MB.\\n\\n    Failures here are logged but never abort the message-delete response \u2014 the\\n    user expects \\\"delete this session\\\" to succeed even if KB cleanup hits an\\n    issue. The follow-up consequence (ghost chunks) is logged for ops to fix.\\n    \\\"\\\"\\\"\\n    if not session_ids:\\n        return\\n    try:\\n        await get_memory_base_service().purge_session_data(user_id=user_id, session_ids=session_ids)\\n    except Exception:  # noqa: BLE001\\n        # Lazy import to avoid pulling logger into the module-import path for\\n        # an endpoint that doesn't need it on the happy path.\\n        from lfx.log.logger import logger\\n\\n        await logger.aerror(\\n            \\\"Memory Base session purge failed for user=%s sessions=%d\\\",\\n            user_id,\\n            len(session_ids),\\n            exc_info=True,\\n        )\\n\\n\\n@router.get(\\\"/builds\\\", dependencies=[Depends(get_current_active_user)])\\nasync def get_vertex_builds(\\n    flow_id: Annotated[UUID, Query()],\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n) -> VertexBuildMapModel:\\n    try:\\n        # Ownership is enforced in the data access layer.\\n        # Foreign flow IDs intentionally resolve to an empty payload (200)\\n        # to avoid leaking whether the target flow exists.\\n        flow = await _ensure_flow_action_or_404(session, flow_id=flow_id, user=current_user, action=FlowAction.READ)\\n        if flow is None:\\n            return VertexBuildMapModel.from_list_of_dicts([])\\n        vertex_builds = await get_vertex_builds_by_flow_id(session, flow_id, user_id=flow.user_id)\\n        return VertexBuildMapModel.from_list_of_dicts(vertex_builds)\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.delete(\\\"/builds\\\", status_code=204, dependencies=[Depends(get_current_active_user)])\\nasync def delete_vertex_builds(\\n    flow_id: Annotated[UUID, Query()],\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n) -> None:\\n    try:\\n        # Keep endpoint idempotent while preventing cross-user deletion.\\n        flow = await _ensure_flow_action_or_404(session, flow_id=flow_id, user=current_user, action=FlowAction.WRITE)\\n        if flow is None:\\n            return\\n        await delete_vertex_builds_by_flow_id(session, flow_id, user_id=flow.user_id)\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.get(\\\"/messages/sessions\\\")\\nasync def get_message_sessions(\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n    flow_id: Annotated[UUID | None, Query()] = None,\\n) -> list[str]:\\n    try:\\n        # When a flow_id is provided, gate on flow READ permission so a viewer\\n        # without flow access cannot enumerate sessions. The bulk path\\n        # (flow_id is None) keeps the user-scoped JOIN \u2014 share-aware listing\\n        # across all visible flows is an plugin optimisation.\\n        if flow_id is not None:\\n            flow = await _ensure_flow_action_or_404(session, flow_id=flow_id, user=current_user, action=FlowAction.READ)\\n            if flow is None:\\n                return []\\n            stmt = select(MessageTable.session_id).distinct()\\n            stmt = stmt.where(MessageTable.flow_id == flow_id)\\n            stmt = stmt.where(col(MessageTable.session_id).isnot(None))\\n            stmt = stmt.where(~col(MessageTable.session_id).startswith(\\\"agentic_\\\"))\\n            session_ids = await session.exec(stmt)\\n            return list(session_ids)\\n\\n        stmt = select(MessageTable.session_id).distinct()\\n        stmt = stmt.join(Flow, MessageTable.flow_id == Flow.id)\\n        stmt = stmt.where(col(MessageTable.session_id).isnot(None))\\n        stmt = stmt.where(~col(MessageTable.session_id).startswith(\\\"agentic_\\\"))\\n        stmt = stmt.where(Flow.user_id == current_user.id)\\n\\n        session_ids = await session.exec(stmt)\\n        return list(session_ids)\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.get(\\\"/messages\\\")\\nasync def get_messages(\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n    flow_id: Annotated[UUID | None, Query()] = None,\\n    session_id: Annotated[str | None, Query()] = None,\\n    end_user_id: Annotated[str | None, Query()] = None,\\n    sender: Annotated[str | None, Query()] = None,\\n    sender_name: Annotated[str | None, Query()] = None,\\n    order_by: Annotated[str | None, Query()] = \\\"timestamp\\\",\\n    order: Annotated[str, Query()] = \\\"ASC\\\",\\n    limit: Annotated[int | None, Query(ge=0)] = None,\\n    offset: Annotated[int | None, Query(ge=0)] = None,\\n) -> list[MessageResponse]:\\n    try:\\n        # When a flow_id is provided, gate on flow READ permission first; the\\n        # share-aware path lets a non-owner with a read grant see the flow's\\n        # messages.\\n        if flow_id is not None:\\n            flow = await _ensure_flow_action_or_404(session, flow_id=flow_id, user=current_user, action=FlowAction.READ)\\n            if flow is None:\\n                return []\\n\\n        # Use JOIN instead of subquery for better performance\\n        stmt = select(MessageTable)\\n        stmt = stmt.join(Flow, MessageTable.flow_id == Flow.id)\\n        if flow_id is None:\\n            stmt = stmt.where(Flow.user_id == current_user.id)\\n\\n        if flow_id:\\n            stmt = stmt.where(MessageTable.flow_id == flow_id)\\n        if session_id:\\n            from urllib.parse import unquote\\n\\n            decoded_session_id = unquote(session_id)\\n            stmt = stmt.where(MessageTable.session_id == decoded_session_id)\\n        if end_user_id:\\n            # Serving-plane: pull one end user's messages by the indexed owner column. Derive the\\n            # raw id to the same UUID the write stamped (D6 / resolve_message_owner_id) so the\\n            # predicate matches. Optional + off by default -> existing callers are unchanged (BC).\\n            from lfx.memory.flow_context import derive_message_owner_uuid\\n\\n            stmt = stmt.where(MessageTable.user_id == derive_message_owner_uuid(end_user_id))\\n        if sender:\\n            stmt = stmt.where(MessageTable.sender == sender)\\n        if sender_name:\\n            stmt = stmt.where(MessageTable.sender_name == sender_name)\\n        normalized_order = order.upper()\\n        if normalized_order not in {\\\"ASC\\\", \\\"DESC\\\"}:\\n            raise HTTPException(status_code=400, detail=f\\\"Invalid order direction: {order}\\\")\\n        if order_by and order_by not in ALLOWED_MESSAGE_ORDER_FIELDS:\\n            raise HTTPException(status_code=400, detail=f\\\"Invalid order_by field: {order_by}\\\")\\n        # Always select the newest window by timestamp DESC (anchored at the most\\n        # recent row): the editor polls with flow_id only, and an unbounded default\\n        # serializes the whole history on every poll (issue #15023). Selecting by\\n        # timestamp keeps offset paging aligned with history age even when the\\n        # caller sorts by a non-timestamp field. A falsy limit (None/0) falls back\\n        # to the default, matching the previous `if limit:` behavior where 0 meant\\n        # \\\"no limit\\\".\\n        effective_limit = _MESSAGES_DEFAULT_LIMIT if not limit else min(limit, _MESSAGES_MAX_LIMIT)\\n        stmt = stmt.order_by(col(MessageTable.timestamp).desc(), col(MessageTable.id).desc())\\n        if offset:\\n            stmt = stmt.offset(offset)\\n        stmt = stmt.limit(effective_limit)\\n        window = list(await session.exec(stmt))\\n        window = _sorted_for_display(window, order_by=order_by, descending=normalized_order == \\\"DESC\\\")\\n        return [_message_history_response(message) for message in window]\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.delete(\\\"/messages\\\", status_code=204, dependencies=[Depends(get_current_active_user)])\\nasync def delete_messages(\\n    message_ids: list[UUID],\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n) -> None:\\n    try:\\n        # Ownership guard lives in the CRUD layer: only messages belonging to\\n        # current_user are selected and deleted; foreign IDs are ignored.\\n        #\\n        # Practical effect:\\n        # - Mixed lists (owned + foreign IDs) only delete owned rows.\\n        # - Pure foreign lists keep endpoint idempotent with 204 and no changes.\\n        await delete_messages_for_user(session, current_user.id, message_ids)\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.put(\\\"/messages/{message_id}\\\", dependencies=[Depends(get_current_active_user)], response_model=MessageRead)\\nasync def update_message(\\n    message_id: UUID,\\n    message: MessageUpdate,\\n    session: DbSession,\\n    background_tasks: BackgroundTasks,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n):\\n    # Rollback expires ORM state, so keep the ownership key as a stable scalar\\n    # for the post-race lookup.\\n    current_user_id = current_user.id\\n    try:\\n        # Fetch is scoped by user ownership. A foreign message ID resolves to\\n        # None so callers receive the same 404 as a non-existent message.\\n        # This avoids leaking whether another user's message exists.\\n        db_message = await get_message_for_user(session, current_user_id, message_id)\\n    except Exception as e:\\n        await _log_message_update_failure(e)\\n        raise HTTPException(status_code=500, detail=MESSAGE_UPDATE_FAILED) from e\\n\\n    if not db_message:\\n        # Intentionally return 404 for both \\\"not found\\\" and \\\"not owned\\\".\\n        raise HTTPException(status_code=404, detail=\\\"Message not found\\\")\\n\\n    # Bind the parent flow's authorization to message writes so a viewer-role\\n    # user cannot edit messages on a flow they only have READ on.\\n    if db_message.flow_id is not None:\\n        db_flow = await _ensure_flow_action_or_404(\\n            session, flow_id=db_message.flow_id, user=current_user, action=FlowAction.WRITE\\n        )\\n        if db_flow is None:\\n            raise HTTPException(status_code=404, detail=\\\"Message not found\\\")\\n\\n    try:\\n        previous_positive_feedback = _get_positive_feedback_value(db_message)\\n        message_dict = message.model_dump(exclude_unset=True, exclude_none=True)\\n        if \\\"text\\\" in message_dict and message_dict[\\\"text\\\"] != db_message.text:\\n            # Keep edit flag consistent for UI/audit consumers when content changes.\\n            message_dict[\\\"edit\\\"] = True\\n        db_message.sqlmodel_update(message_dict)\\n        session.add(db_message)\\n        await session.flush()\\n        await session.refresh(db_message)\\n    except StaleDataError as e:\\n        # A flow/session cleanup can delete the row after the ownership lookup.\\n        # Recover the failed transaction, then re-check through the same\\n        # owner-scoped query so missing and foreign IDs remain indistinguishable.\\n        try:\\n            await session.rollback()\\n            current_db_message = await get_message_for_user(session, current_user_id, message_id)\\n        except Exception as recheck_error:\\n            await _log_message_update_failure(recheck_error)\\n            raise HTTPException(status_code=500, detail=MESSAGE_UPDATE_FAILED) from recheck_error\\n        if current_db_message is None:\\n            raise HTTPException(status_code=404, detail=\\\"Message not found\\\") from e\\n        await _log_message_update_failure(e)\\n        raise HTTPException(status_code=500, detail=MESSAGE_UPDATE_FAILED) from e\\n    except Exception as e:\\n        await _log_message_update_failure(e)\\n        raise HTTPException(status_code=500, detail=MESSAGE_UPDATE_FAILED) from e\\n\\n    current_positive_feedback = _get_positive_feedback_value(db_message)\\n    langfuse_trace_id = _resolve_langfuse_trace_id(db_message)\\n    if (\\n        current_positive_feedback != previous_positive_feedback\\n        and langfuse_trace_id\\n        and _langfuse_feedback_sync_enabled()\\n    ):\\n        if current_positive_feedback is None:\\n            background_tasks.add_task(\\n                delete_feedback_score,\\n                message_id=db_message.id,\\n            )\\n        else:\\n            background_tasks.add_task(\\n                sync_feedback_score,\\n                message_id=db_message.id,\\n                trace_id=langfuse_trace_id,\\n                session_id=db_message.session_id,\\n                flow_id=db_message.flow_id,\\n                sender=db_message.sender,\\n                positive_feedback=current_positive_feedback,\\n            )\\n    return db_message\\n\\n\\n@router.patch(\\n    \\\"/messages/session/{old_session_id}\\\",\\n    dependencies=[Depends(get_current_active_user)],\\n)\\nasync def update_session_id(\\n    old_session_id: str,\\n    new_session_id: Annotated[str, Query(..., description=\\\"The new session ID to update to\\\")],\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n) -> list[MessageResponse]:\\n    try:\\n        # Session updates are ownership-scoped to prevent session hijacking\\n        # across users that might share or guess a session_id value.\\n        # This endpoint is sensitive because a single call can move many rows.\\n        messages = await get_messages_for_user_by_session(session, current_user.id, old_session_id)\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    if not messages:\\n        # Same response for \\\"session does not exist\\\" and \\\"session exists but is foreign\\\".\\n        raise HTTPException(status_code=404, detail=\\\"No messages found with the given session ID\\\")\\n\\n    try:\\n        # Update all messages with the new session ID\\n        for message in messages:\\n            message.session_id = new_session_id\\n\\n        session.add_all(messages)\\n\\n        await session.flush()\\n        message_responses = []\\n        for message in messages:\\n            await session.refresh(message)\\n            message_responses.append(MessageResponse.model_validate(message, from_attributes=True))\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    return message_responses\\n\\n\\n@router.delete(\\\"/messages/session/{session_id}\\\", status_code=204, dependencies=[Depends(get_current_active_user)])\\nasync def delete_messages_session(\\n    session_id: str,\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n):\\n    \\\"\\\"\\\"Delete messages for a single session.\\n\\n    Only deletes messages from sessions belonging to flows owned by the current user.\\n    \\\"\\\"\\\"\\n    try:\\n        # Keep endpoint idempotent (204) while enforcing ownership in CRUD.\\n        # If the session belongs to another user, this becomes a safe no-op.\\n        # This preserves existing client behavior while blocking cross-user deletes.\\n        await delete_messages_for_user_by_session(session, current_user.id, session_id)\\n        await session.commit()\\n    except Exception as e:\\n        await session.rollback()\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    # Purge ingested chunks AFTER the message rows are committed so a chunk-delete\\n    # failure can never roll back the user-visible message delete.\\n    await _purge_memory_base_session_data(current_user.id, [session_id])\\n\\n    return {\\\"message\\\": \\\"Messages deleted successfully\\\"}\\n\\n\\n@router.delete(\\\"/messages/sessions\\\", status_code=200, dependencies=[Depends(get_current_active_user)])\\nasync def delete_messages_sessions(\\n    session_ids: list[str],\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n):\\n    \\\"\\\"\\\"Bulk delete messages for multiple sessions at once.\\n\\n    Only deletes messages from sessions belonging to flows owned by the current user.\\n\\n    Args:\\n        session_ids: List of session IDs to delete (max 500)\\n        session: Database session\\n        current_user: Current authenticated user\\n\\n    Returns:\\n        Confirmation message with count of deleted sessions\\n\\n    Raises:\\n        HTTPException: 400 if session_ids list exceeds 500 items\\n        HTTPException: 500 if database operation fails\\n    \\\"\\\"\\\"\\n    # Validate input size to prevent massive SQL IN clauses\\n    max_sessions_per_request = 500\\n    if len(session_ids) > max_sessions_per_request:\\n        raise HTTPException(\\n            status_code=400,\\n            detail=f\\\"Cannot delete more than {max_sessions_per_request} sessions at once. Please batch your requests.\\\",\\n        )\\n\\n    if not session_ids:\\n        return {\\\"message\\\": \\\"No sessions to delete\\\", \\\"deleted_count\\\": 0}\\n\\n    try:\\n        # First, get distinct session IDs that have messages belonging to the user's flows\\n        session_stmt = select(MessageTable.session_id).distinct()\\n        session_stmt = session_stmt.join(Flow, MessageTable.flow_id == Flow.id)\\n        session_stmt = session_stmt.where(Flow.user_id == current_user.id)\\n        session_stmt = session_stmt.where(col(MessageTable.session_id).in_(session_ids))\\n\\n        result = await session.exec(session_stmt)\\n        affected_session_ids = list(result)\\n        affected_count = len(affected_session_ids)\\n\\n        if not affected_session_ids:\\n            # No messages found for this user's flows with these session_ids\\n            return {\\\"message\\\": \\\"No sessions to delete\\\", \\\"deleted_count\\\": 0}\\n\\n        # Get message IDs to delete\\n        msg_stmt = select(MessageTable.id)\\n        msg_stmt = msg_stmt.join(Flow, MessageTable.flow_id == Flow.id)\\n        msg_stmt = msg_stmt.where(Flow.user_id == current_user.id)\\n        msg_stmt = msg_stmt.where(col(MessageTable.session_id).in_(affected_session_ids))\\n\\n        msg_result = await session.exec(msg_stmt)\\n        message_ids = list(msg_result)\\n\\n        # Delete only the messages that belong to the user\\n        await session.exec(\\n            delete(MessageTable)\\n            .where(col(MessageTable.id).in_(message_ids))\\n            .execution_options(synchronize_session=\\\"fetch\\\")\\n        )\\n        await session.commit()\\n    except Exception as e:\\n        await session.rollback()\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    # Purge ingested chunks AFTER the messages are committed; same reasoning as above.\\n    await _purge_memory_base_session_data(current_user.id, list(affected_session_ids))\\n\\n    return {\\n        \\\"message\\\": f\\\"Messages deleted successfully for {affected_count} session{'s' if affected_count != 1 else ''}\\\",\\n        \\\"deleted_count\\\": affected_count,\\n    }\\n\\n\\ndef _compute_shared_message_flow_id(user_id: UUID, source_flow_id: UUID) -> UUID:\\n    \\\"\\\"\\\"Derive the authenticated user's virtual flow ID for shared-message storage.\\\"\\\"\\\"\\n    return compute_virtual_flow_id(user_id, source_flow_id, principal_type=\\\"user\\\")\\n\\n\\n@router.get(\\\"/messages/shared/sessions\\\")\\nasync def get_shared_message_sessions(\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n    source_flow_id: Annotated[UUID, Query(description=\\\"The original public flow ID\\\")],\\n) -> list[str]:\\n    \\\"\\\"\\\"Get session IDs for a shared/public flow, scoped to the authenticated user.\\n\\n    Uses a deterministic virtual flow_id derived from the user's ID and the\\n    original flow ID. Only messages stored under this virtual flow_id are returned.\\n    \\\"\\\"\\\"\\n    try:\\n        virtual_flow_id = _compute_shared_message_flow_id(current_user.id, source_flow_id)\\n        stmt = select(MessageTable.session_id).distinct()\\n        stmt = stmt.where(MessageTable.flow_id == virtual_flow_id)\\n        stmt = stmt.where(col(MessageTable.session_id).isnot(None))\\n\\n        session_ids = await session.exec(stmt)\\n        return list(session_ids)\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.get(\\\"/messages/shared\\\")\\nasync def get_shared_messages(\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n    source_flow_id: Annotated[UUID, Query(description=\\\"The original public flow ID\\\")],\\n    session_id: Annotated[str | None, Query()] = None,\\n    order_by: Annotated[str | None, Query()] = \\\"timestamp\\\",\\n    order: Annotated[str, Query()] = \\\"ASC\\\",\\n    limit: Annotated[int | None, Query(ge=0)] = None,\\n    offset: Annotated[int | None, Query(ge=0)] = None,\\n) -> list[MessageResponse]:\\n    \\\"\\\"\\\"Get messages for a shared/public flow, scoped to the authenticated user.\\n\\n    Uses a deterministic virtual flow_id derived from the user's ID and the\\n    original flow ID. Only messages stored under this virtual flow_id are returned.\\n    \\\"\\\"\\\"\\n    try:\\n        virtual_flow_id = _compute_shared_message_flow_id(current_user.id, source_flow_id)\\n        stmt = select(MessageTable)\\n        stmt = stmt.where(MessageTable.flow_id == virtual_flow_id)\\n\\n        if session_id:\\n            from urllib.parse import unquote\\n\\n            decoded_session_id = unquote(session_id)\\n            stmt = stmt.where(MessageTable.session_id == decoded_session_id)\\n        normalized_order = order.upper()\\n        if normalized_order not in {\\\"ASC\\\", \\\"DESC\\\"}:\\n            raise HTTPException(status_code=400, detail=f\\\"Invalid order direction: {order}\\\")\\n        if order_by and order_by not in ALLOWED_MESSAGE_ORDER_FIELDS:\\n            raise HTTPException(status_code=400, detail=f\\\"Invalid order_by field: {order_by}\\\")\\n        # Select the newest window by timestamp DESC, mirroring get_messages (issue #15023).\\n        effective_limit = _MESSAGES_DEFAULT_LIMIT if not limit else min(limit, _MESSAGES_MAX_LIMIT)\\n        stmt = stmt.order_by(col(MessageTable.timestamp).desc(), col(MessageTable.id).desc())\\n        if offset:\\n            stmt = stmt.offset(offset)\\n        stmt = stmt.limit(effective_limit)\\n        window = list(await session.exec(stmt))\\n        window = _sorted_for_display(window, order_by=order_by, descending=normalized_order == \\\"DESC\\\")\\n        return [_message_history_response(message) for message in window]\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.delete(\\\"/messages/shared/session/{session_id}\\\", status_code=204)\\nasync def delete_shared_messages_session(\\n    session_id: str,\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n    source_flow_id: Annotated[UUID, Query(description=\\\"The original public flow ID\\\")],\\n):\\n    \\\"\\\"\\\"Delete messages for a session on a shared/public flow, scoped to the authenticated user.\\\"\\\"\\\"\\n    try:\\n        virtual_flow_id = _compute_shared_message_flow_id(current_user.id, source_flow_id)\\n        stmt = (\\n            delete(MessageTable)\\n            .where(MessageTable.flow_id == virtual_flow_id)\\n            .where(MessageTable.session_id == session_id)\\n        )\\n        await session.exec(stmt)\\n    except Exception as e:\\n        await session.rollback()\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.put(\\\"/messages/shared/{message_id}\\\", response_model=MessageRead)\\nasync def update_shared_message(\\n    message_id: UUID,\\n    message: MessageUpdate,\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n    source_flow_id: Annotated[UUID, Query(description=\\\"The original public flow ID\\\")],\\n):\\n    \\\"\\\"\\\"Update a message on a shared/public flow, scoped to the authenticated user.\\\"\\\"\\\"\\n    try:\\n        virtual_flow_id = _compute_shared_message_flow_id(current_user.id, source_flow_id)\\n        db_message = (\\n            await session.exec(\\n                select(MessageTable).where(\\n                    MessageTable.id == message_id,\\n                    MessageTable.flow_id == virtual_flow_id,\\n                )\\n            )\\n        ).first()\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    if not db_message:\\n        raise HTTPException(status_code=404, detail=\\\"Message not found\\\")\\n\\n    try:\\n        message_dict = message.model_dump(exclude_unset=True, exclude_none=True)\\n        if \\\"text\\\" in message_dict and message_dict[\\\"text\\\"] != db_message.text:\\n            message_dict[\\\"edit\\\"] = True\\n        db_message.sqlmodel_update(message_dict)\\n        session.add(db_message)\\n        await session.flush()\\n        await session.refresh(db_message)\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n    return db_message\\n\\n\\n@router.patch(\\\"/messages/shared/session/{old_session_id}\\\")\\nasync def rename_shared_session(\\n    old_session_id: str,\\n    new_session_id: Annotated[str, Query(description=\\\"The new session ID\\\")],\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n    source_flow_id: Annotated[UUID, Query(description=\\\"The original public flow ID\\\")],\\n) -> list[MessageResponse]:\\n    \\\"\\\"\\\"Rename a session on a shared/public flow, scoped to the authenticated user.\\\"\\\"\\\"\\n    try:\\n        virtual_flow_id = _compute_shared_message_flow_id(current_user.id, source_flow_id)\\n        stmt = select(MessageTable).where(\\n            MessageTable.flow_id == virtual_flow_id,\\n            MessageTable.session_id == old_session_id,\\n        )\\n        messages = list(await session.exec(stmt))\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    if not messages:\\n        raise HTTPException(status_code=404, detail=\\\"No messages found with the given session ID\\\")\\n\\n    try:\\n        for message in messages:\\n            message.session_id = new_session_id\\n        session.add_all(messages)\\n        await session.flush()\\n\\n        result = []\\n        for message in messages:\\n            await session.refresh(message)\\n            result.append(MessageResponse.model_validate(message, from_attributes=True))\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    return result\\n\\n\\n@router.get(\\\"/transactions\\\", dependencies=[Depends(get_current_active_user)])\\nasync def get_transactions(\\n    flow_id: Annotated[UUID, Query()],\\n    session: DbSession,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n    params: Annotated[Params | None, Depends(custom_params)],\\n) -> Page[TransactionLogsResponse]:\\n    try:\\n        # Flow ownership / share-grant is verified via the parent flow guard.\\n        # For foreign flow IDs, the endpoint returns an empty page (200)\\n        # to preserve response shape and avoid existence leakage.\\n        flow = await _ensure_flow_action_or_404(session, flow_id=flow_id, user=current_user, action=FlowAction.READ)\\n        if flow is None:\\n            from fastapi_pagination import Page as _Page\\n\\n            return _Page(items=[], total=0, page=1, size=params.size if params else 50, pages=0)\\n        stmt = (\\n            select(TransactionTable)\\n            .join(Flow, TransactionTable.flow_id == Flow.id)\\n            .where(TransactionTable.flow_id == flow_id)\\n            .order_by(col(TransactionTable.timestamp).desc())\\n        )\\n        import warnings\\n\\n        with warnings.catch_warnings():\\n            warnings.filterwarnings(\\n                \\\"ignore\\\", category=DeprecationWarning, module=r\\\"fastapi_pagination\\\\.ext\\\\.sqlalchemy\\\"\\n            )\\n            return await apaginate(session, stmt, params=params, transformer=transform_transaction_table_for_logs)\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/openai_responses.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"df76a1b1ffcf60712fa30b3952ac5a6b02757bb4b5a0ac884cf1a96f48409364\",\"content\":\"import asyncio\\nimport json\\nimport time\\nimport uuid\\nfrom collections.abc import AsyncGenerator\\nfrom typing import Annotated, Any\\n\\nfrom fastapi import APIRouter, BackgroundTasks, Depends, HTTPException, Request, status\\nfrom fastapi.responses import StreamingResponse\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import execution_protocol\\nfrom lfx.schema.openai_responses_schemas import create_openai_error, create_openai_error_chunk\\nfrom lfx.utils.flow_validation import CustomComponentValidationError\\nfrom lfx.workflow.end_user_identity import (\\n    EndUserIdentityRequiredError,\\n    end_user_required_detail,\\n    resolve_serving_scope,\\n)\\n\\nfrom langflow.api.utils import extract_global_variables_from_headers\\nfrom langflow.api.utils.execution_errors import SAFE_TOOL_ERROR_MESSAGE, error_for_client\\nfrom langflow.api.v1.endpoints import _caller_owns_flow, consume_and_yield, run_flow_generator, simple_run_flow\\nfrom langflow.api.v1.schemas import SimplifiedAPIRequest\\nfrom langflow.events.event_manager import create_stream_tokens_event_manager\\nfrom langflow.helpers.flow import get_flow_by_id_or_endpoint_name\\nfrom langflow.schema import (\\n    OpenAIErrorResponse,\\n    OpenAIResponsesRequest,\\n    OpenAIResponsesResponse,\\n    OpenAIResponsesStreamChunk,\\n)\\nfrom langflow.services.auth.utils import api_key_security\\nfrom langflow.services.authorization import FlowAction, ensure_flow_permission\\nfrom langflow.services.database.models.flow.model import FlowRead\\nfrom langflow.services.database.models.user.model import UserRead\\nfrom langflow.services.deps import get_telemetry_service\\nfrom langflow.services.telemetry.schema import RunPayload\\nfrom langflow.services.telemetry.service import TelemetryService\\n\\nrouter = APIRouter(tags=[\\\"OpenAI Responses API\\\"])\\n\\n\\ndef _flow_not_found_response(model: str) -> OpenAIErrorResponse:\\n    error_response = create_openai_error(\\n        message=f\\\"Flow with id '{model}' not found\\\",\\n        type_=\\\"invalid_request_error\\\",\\n        code=\\\"flow_not_found\\\",\\n    )\\n    return OpenAIErrorResponse(error=error_response[\\\"error\\\"])\\n\\n\\ndef _is_tool_step(block: Any) -> bool:\\n    \\\"\\\"\\\"True for a ``tool_use`` content block, whichever content-types module built it.\\\"\\\"\\\"\\n    return getattr(block, \\\"type\\\", None) == \\\"tool_use\\\"\\n\\n\\ndef _tool_error_text(error: Any) -> str:\\n    \\\"\\\"\\\"Render a ``ToolContent.error`` payload as the ``error`` string of a tool-call item.\\\"\\\"\\\"\\n    if isinstance(error, str):\\n        return error\\n    try:\\n        return json.dumps(error, default=str)\\n    except (TypeError, ValueError):\\n        return str(error)\\n\\n\\ndef _client_tool_error(error: Any, *, expose_details: bool) -> str:\\n    \\\"\\\"\\\"Tool-error text that may cross the API boundary.\\n\\n    Same ownership policy as ``error_for_client``: the flow owner sees the tool's own\\n    message, a delegated or shared caller only learns that the tool failed.\\n    \\\"\\\"\\\"\\n    return _tool_error_text(error) if expose_details else SAFE_TOOL_ERROR_MESSAGE\\n\\n\\ndef _streamed_message_key(data: Any) -> str:\\n    \\\"\\\"\\\"Key a ``token`` or ``add_message`` event by the message it belongs to.\\n\\n    ``Component._send_message_event`` and both token emitters (``Component._process_chunk``,\\n    ``lfx.base.agents.events``) put the stored message id at ``data[\\\"id\\\"]``; a raw\\n    ``Message.model_dump()`` keeps it at ``data[\\\"data\\\"][\\\"id\\\"]``. Events carrying neither share\\n    the anonymous key, so the tokens and the complete message of a producer that streams\\n    outside ``send_message`` still pair up.\\n    \\\"\\\"\\\"\\n    if not isinstance(data, dict):\\n        return \\\"\\\"\\n    nested = data.get(\\\"data\\\")\\n    message_id = data.get(\\\"id\\\") or (nested.get(\\\"id\\\") if isinstance(nested, dict) else None)\\n    return str(message_id) if message_id else \\\"\\\"\\n\\n\\ndef _already_delivered(text: str, delivered: str) -> bool:\\n    \\\"\\\"\\\"Whether ``text`` carries nothing the client has not already received.\\n\\n    True when what the client has already ends with ``text``. Whitespace is ignored: token\\n    concatenation and the stored text of one answer can differ by it alone. A suffix rather\\n    than equality covers an agent whose final text is the last model round while its tokens\\n    spanned every round. Empty text is trivially delivered.\\n    \\\"\\\"\\\"\\n    return \\\"\\\".join(delivered.split()).endswith(\\\"\\\".join(text.split()))\\n\\n\\ndef _split_already_sent(chunk: str, already_sent: str) -> tuple[str, str]:\\n    \\\"\\\"\\\"Split a token ``chunk`` into what the client still needs and what it already has.\\n\\n    Chat Output publishes the first streamed chunk twice: as the text of a\\n    ``state=\\\"partial\\\"`` add_message and, right after, as the first ``token`` event\\n    of the same message. The partial text is forwarded the moment it arrives, so\\n    the token repeating it must not be forwarded again.\\n\\n    Returns ``(text_to_send, still_ahead)``: ``still_ahead`` is the part of\\n    ``already_sent`` that later tokens are still expected to repeat. A chunk that\\n    matches neither way means the token stream diverged from the partial text; it\\n    is then sent whole rather than risk dropping text.\\n    \\\"\\\"\\\"\\n    if not already_sent:\\n        return chunk, \\\"\\\"\\n    if already_sent.startswith(chunk):\\n        return \\\"\\\", already_sent[len(chunk) :]\\n    if chunk.startswith(already_sent):\\n        return chunk[len(already_sent) :], \\\"\\\"\\n    return chunk, \\\"\\\"\\n\\n\\ndef has_chat_input(flow_data: dict | None) -> bool:\\n    \\\"\\\"\\\"Check if the flow has a chat input component.\\\"\\\"\\\"\\n    if not flow_data or \\\"nodes\\\" not in flow_data:\\n        return False\\n\\n    return any(node.get(\\\"data\\\", {}).get(\\\"type\\\") in [\\\"ChatInput\\\", \\\"Chat Input\\\"] for node in flow_data[\\\"nodes\\\"])\\n\\n\\ndef has_chat_output(flow_data: dict | None) -> bool:\\n    \\\"\\\"\\\"Check if the flow has a chat input component.\\\"\\\"\\\"\\n    if not flow_data or \\\"nodes\\\" not in flow_data:\\n        return False\\n\\n    return any(node.get(\\\"data\\\", {}).get(\\\"type\\\") in [\\\"ChatOutput\\\", \\\"Chat Output\\\"] for node in flow_data[\\\"nodes\\\"])\\n\\n\\nasync def run_flow_for_openai_responses(\\n    flow: FlowRead,\\n    request: OpenAIResponsesRequest,\\n    api_key_user: UserRead,\\n    *,\\n    stream: bool = False,\\n    variables: dict[str, str] | None = None,\\n    http_request: Request | None = None,\\n) -> OpenAIResponsesResponse | StreamingResponse:\\n    \\\"\\\"\\\"Run a flow for OpenAI Responses API compatibility.\\\"\\\"\\\"\\n    expose_error_details = _caller_owns_flow(flow, api_key_user)\\n    # Check if flow has chat input\\n    if not has_chat_input(flow.data):\\n        msg = \\\"Flow must have a ChatInput component to be compatible with OpenAI Responses API\\\"\\n        raise ValueError(msg)\\n\\n    if not has_chat_output(flow.data):\\n        msg = \\\"Flow must have a ChatOutput component to be compatible with OpenAI Responses API\\\"\\n        raise ValueError(msg)\\n\\n    # Use previous_response_id as session_id for conversation continuity\\n    # If no previous_response_id, create a new session_id\\n    session_id = request.previous_response_id or str(uuid.uuid4())\\n\\n    # Store header variables in context for global variable override\\n    context = {}\\n    if variables:\\n        context[\\\"request_variables\\\"] = variables\\n        await logger.adebug(f\\\"Added request variables to context: {list(variables.keys())}\\\")\\n\\n    # Convert OpenAI request to SimplifiedAPIRequest\\n    # Note: We're moving away from tweaks to a context-based approach\\n    simplified_request = SimplifiedAPIRequest(\\n        input_value=request.input,\\n        input_type=\\\"chat\\\",  # Use chat input type for better compatibility\\n        output_type=\\\"chat\\\",  # Use chat output type for better compatibility\\n        tweaks={},  # Empty tweaks, using context instead\\n        session_id=session_id,\\n    )\\n\\n    # Context will be passed separately to simple_run_flow\\n\\n    await logger.adebug(f\\\"SimplifiedAPIRequest created with context keys: {list(context.keys())}\\\")\\n\\n    # Use session_id as response_id for OpenAI compatibility\\n    response_id = session_id\\n    created_timestamp = int(time.time())\\n\\n    if stream:\\n        # Handle streaming response\\n        asyncio_queue: asyncio.Queue = asyncio.Queue()\\n        asyncio_queue_client_consumed: asyncio.Queue = asyncio.Queue()\\n        event_manager = create_stream_tokens_event_manager(queue=asyncio_queue)\\n\\n        async def openai_stream_generator() -> AsyncGenerator[str, None]:\\n            \\\"\\\"\\\"Convert Langflow events to OpenAI Responses API streaming format.\\\"\\\"\\\"\\n            # Around the create_task only: the task copies the context at creation, and there is\\n            # no await inside the scope, so nothing straddles a suspension point of this generator.\\n            with execution_protocol(\\\"openai_responses\\\"):\\n                main_task = asyncio.create_task(\\n                    run_flow_generator(\\n                        flow=flow,\\n                        input_request=simplified_request,\\n                        api_key_user=api_key_user,\\n                        event_manager=event_manager,\\n                        client_consumed_queue=asyncio_queue_client_consumed,\\n                        context=context,\\n                        expose_error_details=expose_error_details,\\n                        http_request=http_request,\\n                    )\\n                )\\n\\n            try:\\n                await logger.adebug(\\n                    \\\"[OpenAIResponses][stream] start: response_id=%s model=%s session_id=%s\\\",\\n                    response_id,\\n                    request.model,\\n                    session_id,\\n                )\\n                # Send initial chunk to establish connection\\n                initial_chunk = OpenAIResponsesStreamChunk(\\n                    id=response_id,\\n                    created=created_timestamp,\\n                    model=request.model,\\n                    delta={\\\"content\\\": \\\"\\\"},\\n                )\\n                yield f\\\"data: {initial_chunk.model_dump_json()}\\\\n\\\\n\\\"\\n\\n                tool_call_counter = 0\\n                processed_tools = set()  # Track processed tool calls to avoid duplicates\\n                previous_content = \\\"\\\"  # Track content already sent to calculate deltas\\n                stream_usage_data = None  # Track usage from completed message\\n                # Keys (see _streamed_message_key) of the messages whose text went out as\\n                # non-empty ``token`` events. A ``state=\\\"complete\\\"`` add_message repeats\\n                # text the client already has only when its own id streamed. Every other\\n                # complete message is the sole carrier of its text: a producer that never\\n                # streamed (Stream toggle off, a Prompt feeding Chat Output), or a Chat\\n                # Output re-publishing a streamed agent answer through a Prompt under the\\n                # new id it stores it with.\\n                streamed_message_ids: set[str] = set()\\n                # Text already forwarded from an add_message that the token stream of the\\n                # same message is expected to repeat, keyed like streamed_message_ids. Chat\\n                # Output publishes the first streamed chunk as a partial add_message *before*\\n                # the token event for it; an agent's interim text is republished *after* its\\n                # tokens, so its delta is empty and nothing is recorded for it.\\n                partial_text_ahead: dict[str, str] = {}\\n                # A completion can repeat a partial answer or attach usage while other\\n                # branches emit text in between. Remember each message's latest text\\n                # independently of the response-wide delta baseline.\\n                previous_message_text: dict[str, str] = {}\\n\\n                async for event_data in consume_and_yield(asyncio_queue, asyncio_queue_client_consumed):\\n                    if event_data is None:\\n                        await logger.adebug(\\\"[OpenAIResponses][stream] received None event_data; breaking loop\\\")\\n                        break\\n\\n                    content = \\\"\\\"\\n                    token_data: str | dict[str, Any] = {}  # {} = no token in this event\\n\\n                    # Parse byte string events as JSON\\n                    if isinstance(event_data, bytes):\\n                        try:\\n                            import json\\n\\n                            event_str = event_data.decode(\\\"utf-8\\\")\\n                            parsed_event = json.loads(event_str)\\n\\n                            if isinstance(parsed_event, dict):\\n                                event_type = parsed_event.get(\\\"event\\\")\\n                                data = parsed_event.get(\\\"data\\\", {})\\n                                await logger.adebug(\\n                                    \\\"[OpenAIResponses][stream] event: %s keys=%s\\\",\\n                                    event_type,\\n                                    list(data.keys()) if isinstance(data, dict) else type(data),\\n                                )\\n\\n                                # Handle add_message events\\n                                if event_type == \\\"token\\\":\\n                                    token_data = data.get(\\\"chunk\\\", \\\"\\\")\\n                                    if isinstance(token_data, str) and token_data:\\n                                        message_key = _streamed_message_key(data)\\n                                        streamed_message_ids.add(message_key)\\n                                        token_data, still_ahead = _split_already_sent(\\n                                            token_data, partial_text_ahead.get(message_key, \\\"\\\")\\n                                        )\\n                                        if still_ahead:\\n                                            partial_text_ahead[message_key] = still_ahead\\n                                        else:\\n                                            partial_text_ahead.pop(message_key, None)\\n                                        previous_content += token_data\\n                                    await logger.adebug(\\n                                        \\\"[OpenAIResponses][stream] token: token_data=%s\\\",\\n                                        token_data,\\n                                    )\\n                                if event_type == \\\"error\\\":\\n                                    # Error message is in 'text' field, not 'error' field\\n                                    # The 'error' field is a boolean flag\\n                                    error_message = data.get(\\\"text\\\") or data.get(\\\"error\\\", \\\"Unknown error\\\")\\n                                    # Ensure error_message is a string\\n                                    if not isinstance(error_message, str):\\n                                        error_message = str(error_message)\\n                                    # Send error as content chunk with finish_reason=\\\"error\\\"\\n                                    # This ensures OpenAI SDK can parse and surface the error\\n                                    error_chunk = create_openai_error_chunk(\\n                                        response_id=response_id,\\n                                        created_timestamp=created_timestamp,\\n                                        model=request.model,\\n                                        error_message=error_message,\\n                                    )\\n                                    yield f\\\"data: {error_chunk.model_dump_json()}\\\\n\\\\n\\\"\\n                                    yield \\\"data: [DONE]\\\\n\\\\n\\\"\\n                                    # Exit early after error\\n                                    return\\n\\n                                if event_type == \\\"add_message\\\":\\n                                    sender_name = data.get(\\\"sender_name\\\", \\\"\\\")\\n                                    text = data.get(\\\"text\\\", \\\"\\\")\\n                                    sender = data.get(\\\"sender\\\", \\\"\\\")\\n                                    content_blocks = data.get(\\\"content_blocks\\\", [])\\n\\n                                    # Get message state from properties\\n                                    properties = data.get(\\\"properties\\\", {})\\n                                    message_state = properties.get(\\\"state\\\") if isinstance(properties, dict) else None\\n\\n                                    await logger.adebug(\\n                                        (\\n                                            \\\"[OpenAIResponses][stream] add_message: \\\"\\n                                            \\\"sender=%s sender_name=%s text_len=%d state=%s\\\"\\n                                        ),\\n                                        sender,\\n                                        sender_name,\\n                                        len(text) if isinstance(text, str) else -1,\\n                                        message_state,\\n                                    )\\n\\n                                    if message_state == \\\"complete\\\":\\n                                        # Extract usage from completed message properties\\n                                        if isinstance(properties, dict) and \\\"usage\\\" in properties:\\n                                            usage_obj = properties.get(\\\"usage\\\")\\n                                            if usage_obj and isinstance(usage_obj, dict):\\n                                                # Convert None values to 0 for compatibility\\n                                                stream_usage_data = {\\n                                                    \\\"input_tokens\\\": usage_obj.get(\\\"input_tokens\\\") or 0,\\n                                                    \\\"output_tokens\\\": usage_obj.get(\\\"output_tokens\\\") or 0,\\n                                                    \\\"total_tokens\\\": usage_obj.get(\\\"total_tokens\\\") or 0,\\n                                                }\\n                                                await logger.adebug(\\n                                                    \\\"[OpenAIResponses][stream] captured usage: %s\\\", stream_usage_data\\n                                                )\\n                                        # The text of a complete message is a repeat of what the client\\n                                        # already has only when this very message went out as token\\n                                        # events. Blanking every complete message dropped the answer of\\n                                        # runs that never streamed; blanking on any earlier token dropped\\n                                        # the Chat Output that re-publishes a streamed agent answer\\n                                        # through a Prompt under its own id. A complete message that did\\n                                        # not stream falls through to the delta logic below, which also\\n                                        # keeps a republished identical message (Chat Output re-sending\\n                                        # once usage is attached, or storing an unchanged upstream answer\\n                                        # under a new id) from being emitted twice.\\n                                        message_key = _streamed_message_key(data)\\n                                        if message_key in streamed_message_ids:\\n                                            await logger.adebug(\\n                                                \\\"[OpenAIResponses][stream] skipping text of add_message with \\\"\\n                                                \\\"state=complete: message %r already streamed as tokens\\\",\\n                                                message_key,\\n                                            )\\n                                            # Still process content_blocks for tool calls, but skip text content\\n                                            text = \\\"\\\"\\n\\n                                    # Look for Agent Steps in content_blocks\\n                                    for block in content_blocks:\\n                                        if block.get(\\\"title\\\") == \\\"Agent Steps\\\":\\n                                            contents = block.get(\\\"contents\\\", [])\\n                                            for step in contents:\\n                                                # Look for tool_use type items\\n                                                if step.get(\\\"type\\\") == \\\"tool_use\\\":\\n                                                    tool_name = step.get(\\\"name\\\", \\\"\\\")\\n                                                    tool_input = step.get(\\\"tool_input\\\", {})\\n                                                    tool_output = step.get(\\\"output\\\")\\n                                                    tool_error = step.get(\\\"error\\\")\\n                                                    # A step is terminal once it carries an output OR an\\n                                                    # error. A failed tool never gets an output, so gating\\n                                                    # on output alone dropped every failed call from the\\n                                                    # stream while the persisted message still showed it.\\n                                                    tool_finished = tool_output is not None or tool_error is not None\\n\\n                                                    # Only emit tool calls with explicit tool names and\\n                                                    # meaningful arguments, once the step has resolved\\n                                                    if tool_name and tool_input is not None and tool_finished:\\n                                                        # Create unique identifier for this tool call\\n                                                        tool_signature = (\\n                                                            f\\\"{tool_name}:{hash(str(sorted(tool_input.items())))}\\\"\\n                                                        )\\n\\n                                                        # Skip if we've already processed this tool call\\n                                                        if tool_signature in processed_tools:\\n                                                            continue\\n\\n                                                        processed_tools.add(tool_signature)\\n                                                        tool_call_counter += 1\\n                                                        call_id = f\\\"call_{tool_call_counter}\\\"\\n                                                        tool_id = f\\\"fc_{tool_call_counter}\\\"\\n                                                        tool_call_event = {\\n                                                            \\\"type\\\": \\\"response.output_item.added\\\",\\n                                                            \\\"item\\\": {\\n                                                                \\\"id\\\": tool_id,\\n                                                                \\\"type\\\": \\\"function_call\\\",  # OpenAI uses \\\"function_call\\\"\\n                                                                \\\"status\\\": \\\"in_progress\\\",  # OpenAI includes status\\n                                                                \\\"name\\\": tool_name,\\n                                                                \\\"arguments\\\": \\\"\\\",  # Start with empty, build via deltas\\n                                                                \\\"call_id\\\": call_id,\\n                                                            },\\n                                                        }\\n                                                        yield (\\n                                                            f\\\"event: response.output_item.added\\\\n\\\"\\n                                                            f\\\"data: {json.dumps(tool_call_event)}\\\\n\\\\n\\\"\\n                                                        )\\n\\n                                                        # Send function call arguments as delta events (like OpenAI)\\n                                                        arguments_str = json.dumps(tool_input)\\n                                                        arg_delta_event = {\\n                                                            \\\"type\\\": \\\"response.function_call_arguments.delta\\\",\\n                                                            \\\"delta\\\": arguments_str,\\n                                                            \\\"item_id\\\": tool_id,\\n                                                            \\\"output_index\\\": 0,\\n                                                        }\\n                                                        yield (\\n                                                            f\\\"event: response.function_call_arguments.delta\\\\n\\\"\\n                                                            f\\\"data: {json.dumps(arg_delta_event)}\\\\n\\\\n\\\"\\n                                                        )\\n\\n                                                        # Send function call arguments done event\\n                                                        arg_done_event = {\\n                                                            \\\"type\\\": \\\"response.function_call_arguments.done\\\",\\n                                                            \\\"arguments\\\": arguments_str,\\n                                                            \\\"item_id\\\": tool_id,\\n                                                            \\\"output_index\\\": 0,\\n                                                        }\\n                                                        yield (\\n                                                            f\\\"event: response.function_call_arguments.done\\\\n\\\"\\n                                                            f\\\"data: {json.dumps(arg_done_event)}\\\\n\\\\n\\\"\\n                                                        )\\n                                                        await logger.adebug(\\n                                                            \\\"[OpenAIResponses][stream] tool_call.args.done name=%s\\\",\\n                                                            tool_name,\\n                                                        )\\n\\n                                                        # The step resolved (output or error): send the completion\\n                                                        # event. A failed call carries status=\\\"failed\\\" plus the\\n                                                        # error text, mirroring OpenAI's server-executed call\\n                                                        # items (mcp_call / web_search_call), so consumers can\\n                                                        # render the failure instead of an in-flight call.\\n                                                        # The outcome follows ``output``: on_tool_end only fires\\n                                                        # when a run succeeds and the same block is rebound across\\n                                                        # retry attempts, so output + error together mean \\\"failed\\n                                                        # once, then succeeded\\\". Only an output-less error fails.\\n                                                        tool_failed = tool_output is None and tool_error is not None\\n                                                        tool_status = \\\"failed\\\" if tool_failed else \\\"completed\\\"\\n                                                        # Check if include parameter requests tool_call.results\\n                                                        include_results = (\\n                                                            request.include and \\\"tool_call.results\\\" in request.include\\n                                                        )\\n\\n                                                        if include_results:\\n                                                            # Format with detailed results\\n                                                            tool_done_event = {\\n                                                                \\\"type\\\": \\\"response.output_item.done\\\",\\n                                                                \\\"item\\\": {\\n                                                                    \\\"id\\\": f\\\"{tool_name}_{tool_id}\\\",\\n                                                                    \\\"inputs\\\": tool_input,  # Raw inputs as-is\\n                                                                    \\\"status\\\": tool_status,\\n                                                                    \\\"type\\\": \\\"tool_call\\\",\\n                                                                    \\\"tool_name\\\": f\\\"{tool_name}\\\",\\n                                                                    # Raw output as-is; a failed call has none\\n                                                                    \\\"results\\\": tool_output\\n                                                                    if tool_output is not None\\n                                                                    else [],\\n                                                                },\\n                                                                \\\"output_index\\\": 0,\\n                                                                \\\"sequence_number\\\": tool_call_counter + 5,\\n                                                            }\\n                                                        else:\\n                                                            # Regular function call format\\n                                                            tool_done_event = {\\n                                                                \\\"type\\\": \\\"response.output_item.done\\\",\\n                                                                \\\"item\\\": {\\n                                                                    \\\"id\\\": tool_id,\\n                                                                    \\\"type\\\": \\\"function_call\\\",  # Match OpenAI format\\n                                                                    \\\"status\\\": tool_status,\\n                                                                    \\\"arguments\\\": arguments_str,\\n                                                                    \\\"call_id\\\": call_id,\\n                                                                    \\\"name\\\": tool_name,\\n                                                                },\\n                                                            }\\n                                                        if tool_failed:\\n                                                            tool_done_event[\\\"item\\\"][\\\"error\\\"] = _client_tool_error(\\n                                                                tool_error, expose_details=expose_error_details\\n                                                            )\\n\\n                                                        yield (\\n                                                            f\\\"event: response.output_item.done\\\\n\\\"\\n                                                            f\\\"data: {json.dumps(tool_done_event)}\\\\n\\\\n\\\"\\n                                                        )\\n                                                        await logger.adebug(\\n                                                            \\\"[OpenAIResponses][stream] tool_call.done %s status=%s\\\",\\n                                                            tool_name,\\n                                                            tool_status,\\n                                                        )\\n\\n                                    # Extract text content for streaming (only AI responses)\\n                                    if (\\n                                        sender in [\\\"Machine\\\", \\\"AI\\\", \\\"Agent\\\"]\\n                                        and text != request.input\\n                                        and sender_name in [\\\"Agent\\\", \\\"AI\\\"]\\n                                    ):\\n                                        message_key = _streamed_message_key(data)\\n                                        is_republished_complete = (\\n                                            message_state == \\\"complete\\\"\\n                                            and previous_message_text.get(message_key) == text\\n                                        )\\n                                        if text:\\n                                            previous_message_text[message_key] = text\\n                                        # Calculate delta: only send newly generated content\\n                                        if is_republished_complete or _already_delivered(text, previous_content):\\n                                            # Nothing new: this completed snapshot was already handled,\\n                                            # the text was blanked because its id streamed, the frame is\\n                                            # text-less, or a new id repeats what the tokens delivered.\\n                                            # The baseline must survive here; letting such a frame fall\\n                                            # into the reset below emptied it, so the next message was\\n                                            # measured against nothing and re-sent the whole answer.\\n                                            await logger.adebug(\\n                                                \\\"[OpenAIResponses][stream] text already delivered; skipping len=%d\\\",\\n                                                len(text),\\n                                            )\\n                                        elif text.startswith(previous_content):\\n                                            content = text[len(previous_content) :]\\n                                            previous_content = text\\n                                            if content:\\n                                                partial_text_ahead[message_key] = (\\n                                                    partial_text_ahead.get(message_key, \\\"\\\") + content\\n                                                )\\n                                            await logger.adebug(\\n                                                \\\"[OpenAIResponses][stream] delta computed len=%d total_len=%d\\\",\\n                                                len(content),\\n                                                len(previous_content),\\n                                            )\\n                                        else:\\n                                            # If text doesn't start with previous content, send full text\\n                                            # This handles cases where the content might be reset\\n                                            content = text\\n                                            previous_content = text\\n                                            await logger.adebug(\\n                                                \\\"[OpenAIResponses][stream] content reset; sending full text len=%d\\\",\\n                                                len(content),\\n                                            )\\n\\n                        except (json.JSONDecodeError, UnicodeDecodeError):\\n                            await logger.adebug(\\\"[OpenAIResponses][stream] failed to decode event bytes; skipping\\\")\\n                            continue\\n\\n                    # Only send chunks with actual content\\n                    if content or token_data:\\n                        if isinstance(token_data, str):\\n                            content = token_data\\n                            await logger.adebug(\\n                                f\\\"[OpenAIResponses][stream] sent chunk with content={content}\\\",\\n                            )\\n                        chunk = OpenAIResponsesStreamChunk(\\n                            id=response_id,\\n                            created=created_timestamp,\\n                            model=request.model,\\n                            delta={\\\"content\\\": content},\\n                        )\\n                        yield f\\\"data: {chunk.model_dump_json()}\\\\n\\\\n\\\"\\n                        await logger.adebug(\\n                            \\\"[OpenAIResponses][stream] sent chunk with delta_len=%d\\\",\\n                            len(content),\\n                        )\\n\\n                # Send final completion chunk\\n                final_chunk = OpenAIResponsesStreamChunk(\\n                    id=response_id,\\n                    created=created_timestamp,\\n                    model=request.model,\\n                    delta={},\\n                    status=\\\"completed\\\",\\n                    finish_reason=\\\"stop\\\",\\n                )\\n                yield f\\\"data: {final_chunk.model_dump_json()}\\\\n\\\\n\\\"\\n\\n                # Send response.completed event with usage (OpenAI format)\\n                completed_event = {\\n                    \\\"type\\\": \\\"response.completed\\\",\\n                    \\\"response\\\": {\\n                        \\\"id\\\": response_id,\\n                        \\\"object\\\": \\\"response\\\",\\n                        \\\"created_at\\\": created_timestamp,\\n                        \\\"status\\\": \\\"completed\\\",\\n                        \\\"model\\\": request.model,\\n                        \\\"usage\\\": stream_usage_data,\\n                    },\\n                }\\n                yield f\\\"event: response.completed\\\\ndata: {json.dumps(completed_event)}\\\\n\\\\n\\\"\\n\\n                yield \\\"data: [DONE]\\\\n\\\\n\\\"\\n                await logger.adebug(\\n                    \\\"[OpenAIResponses][stream] completed: response_id=%s total_sent_len=%d usage=%s\\\",\\n                    response_id,\\n                    len(previous_content),\\n                    stream_usage_data,\\n                )\\n\\n            except Exception as e:  # noqa: BLE001\\n                await logger.aexception(\\\"Error in OpenAI Responses stream generator\\\")\\n                client_error = error_for_client(e, expose_details=expose_error_details)\\n                # Send error as content chunk with finish_reason=\\\"error\\\"\\n                error_chunk = create_openai_error_chunk(\\n                    response_id=response_id,\\n                    created_timestamp=created_timestamp,\\n                    model=request.model,\\n                    error_message=str(client_error),\\n                )\\n                yield f\\\"data: {error_chunk.model_dump_json()}\\\\n\\\\n\\\"\\n                yield \\\"data: [DONE]\\\\n\\\\n\\\"\\n            finally:\\n                if not main_task.done():\\n                    main_task.cancel()\\n\\n        return StreamingResponse(\\n            openai_stream_generator(),\\n            media_type=\\\"text/event-stream\\\",\\n            headers={\\n                \\\"Cache-Control\\\": \\\"no-cache\\\",\\n                \\\"Connection\\\": \\\"keep-alive\\\",\\n                \\\"Access-Control-Allow-Origin\\\": \\\"*\\\",\\n            },\\n        )\\n\\n    # Handle non-streaming response\\n    with execution_protocol(\\\"openai_responses\\\"):\\n        result = await simple_run_flow(\\n            flow=flow,\\n            input_request=simplified_request,\\n            stream=False,\\n            api_key_user=api_key_user,\\n            context=context,\\n            expose_error_details=expose_error_details,\\n            http_request=http_request,\\n        )\\n\\n    # Extract output text, tool calls, and usage from result\\n    output_text = \\\"\\\"\\n    tool_calls: list[dict[str, Any]] = []\\n    usage_data: dict[str, int] | None = None\\n    try:\\n        outputs_len = len(result.outputs) if getattr(result, \\\"outputs\\\", None) else 0\\n        await logger.adebug(\\\"[OpenAIResponses][non-stream] result.outputs len=%d\\\", outputs_len)\\n    except Exception:  # noqa: BLE001\\n        await logger.adebug(\\\"[OpenAIResponses][non-stream] unable to read result.outputs len\\\")\\n\\n    if result.outputs:\\n        for run_output in result.outputs:\\n            if run_output and run_output.outputs:\\n                for component_output in run_output.outputs:\\n                    if component_output:\\n                        # First, try to extract usage from results (contains actual Message objects)\\n                        if hasattr(component_output, \\\"results\\\") and component_output.results:\\n                            for value in component_output.results.values():\\n                                # Extract usage from Message properties if available\\n                                if (\\n                                    not usage_data\\n                                    and hasattr(value, \\\"properties\\\")\\n                                    and hasattr(value.properties, \\\"usage\\\")\\n                                    and value.properties.usage\\n                                ):\\n                                    usage_obj = value.properties.usage\\n                                    usage_data = {\\n                                        \\\"input_tokens\\\": getattr(usage_obj, \\\"input_tokens\\\", None) or 0,\\n                                        \\\"output_tokens\\\": getattr(usage_obj, \\\"output_tokens\\\", None) or 0,\\n                                        \\\"total_tokens\\\": getattr(usage_obj, \\\"total_tokens\\\", None) or 0,\\n                                    }\\n                                    break\\n                        # Handle messages (final chat outputs) for text extraction\\n                        if hasattr(component_output, \\\"messages\\\") and component_output.messages:\\n                            for msg in component_output.messages:\\n                                if hasattr(msg, \\\"message\\\"):\\n                                    output_text = msg.message\\n                                    break\\n                        # Handle results for text extraction if not found in messages\\n                        if not output_text and hasattr(component_output, \\\"results\\\") and component_output.results:\\n                            for value in component_output.results.values():\\n                                if hasattr(value, \\\"get_text\\\"):\\n                                    output_text = value.get_text()\\n                                    break\\n                                if isinstance(value, str):\\n                                    output_text = value\\n                                    break\\n\\n                        if hasattr(component_output, \\\"results\\\") and component_output.results:\\n                            message = component_output.results.get(\\\"message\\\")\\n                            for block in getattr(message, \\\"content_blocks\\\", None) or []:\\n                                # The agent's flat log carries tool_use as top-level\\n                                # ToolContent leaves; the legacy/grouped shape nests\\n                                # them inside a group's ``contents``. Handle both.\\n                                # Match on the ``type`` discriminator rather than\\n                                # ``isinstance``: the agent builds its blocks from\\n                                # ``lfx.schema.content_types``, a different class than\\n                                # the langflow-side copy, so an isinstance check never\\n                                # matched a real message and no tool call was returned.\\n                                leaves = [block] if _is_tool_step(block) else getattr(block, \\\"contents\\\", None) or []\\n                                tool_calls.extend(\\n                                    {\\n                                        \\\"name\\\": content.name,\\n                                        \\\"input\\\": content.tool_input,\\n                                        \\\"output\\\": content.output,\\n                                        \\\"error\\\": content.error,\\n                                    }\\n                                    for content in leaves\\n                                    if _is_tool_step(content)\\n                                )\\n                    if output_text:\\n                        break\\n            if output_text:\\n                break\\n\\n    await logger.adebug(\\n        \\\"[OpenAIResponses][non-stream] extracted output_text_len=%d tool_calls=%d usage=%s\\\",\\n        len(output_text) if isinstance(output_text, str) else -1,\\n        len(tool_calls),\\n        usage_data,\\n    )\\n\\n    # Build output array\\n    output_items = []\\n\\n    # Add tool calls if includes parameter requests them\\n    include_results = request.include and \\\"tool_call.results\\\" in request.include\\n\\n    tool_call_id_counter = 1\\n    for tool_call in tool_calls:\\n        # Same contract as the stream: an output-less error is a failure; otherwise the\\n        # output wins (a retried call that eventually succeeded keeps its stale error).\\n        tool_error = tool_call.get(\\\"error\\\")\\n        tool_failed = tool_call.get(\\\"output\\\") is None and tool_error is not None\\n        tool_status = \\\"failed\\\" if tool_failed else \\\"completed\\\"\\n        if include_results:\\n            # Format as detailed tool call with results (like file_search_call in sample)\\n            tool_call_item = {\\n                \\\"id\\\": f\\\"{tool_call['name']}_{tool_call_id_counter}\\\",\\n                \\\"queries\\\": list(tool_call[\\\"input\\\"].values())\\n                if isinstance(tool_call[\\\"input\\\"], dict)\\n                else [str(tool_call[\\\"input\\\"])],\\n                \\\"status\\\": tool_status,\\n                \\\"tool_name\\\": f\\\"{tool_call['name']}\\\",\\n                \\\"type\\\": \\\"tool_call\\\",\\n                \\\"results\\\": tool_call[\\\"output\\\"] if tool_call[\\\"output\\\"] is not None else [],\\n            }\\n        else:\\n            # Format as basic function call\\n            tool_call_item = {\\n                \\\"id\\\": f\\\"fc_{tool_call_id_counter}\\\",\\n                \\\"type\\\": \\\"function_call\\\",\\n                \\\"status\\\": tool_status,\\n                \\\"name\\\": tool_call[\\\"name\\\"],\\n                \\\"arguments\\\": json.dumps(tool_call[\\\"input\\\"]) if tool_call[\\\"input\\\"] is not None else \\\"{}\\\",\\n            }\\n        if tool_failed:\\n            tool_call_item[\\\"error\\\"] = _client_tool_error(tool_error, expose_details=expose_error_details)\\n\\n        output_items.append(tool_call_item)\\n        tool_call_id_counter += 1\\n\\n    # Add the message output\\n    output_message = {\\n        \\\"type\\\": \\\"message\\\",\\n        \\\"id\\\": f\\\"msg_{response_id}\\\",\\n        \\\"status\\\": \\\"completed\\\",\\n        \\\"role\\\": \\\"assistant\\\",\\n        \\\"content\\\": [{\\\"type\\\": \\\"output_text\\\", \\\"text\\\": output_text, \\\"annotations\\\": []}],\\n    }\\n    output_items.append(output_message)\\n\\n    return OpenAIResponsesResponse(\\n        id=response_id,\\n        created_at=created_timestamp,\\n        model=request.model,\\n        output=output_items,\\n        previous_response_id=request.previous_response_id,\\n        usage=usage_data,\\n    )\\n\\n\\n@router.post(\\\"/responses\\\", response_model=None)\\nasync def create_response(\\n    request: OpenAIResponsesRequest,\\n    background_tasks: BackgroundTasks,\\n    api_key_user: Annotated[UserRead, Depends(api_key_security)],\\n    telemetry_service: Annotated[TelemetryService, Depends(get_telemetry_service)],\\n    http_request: Request,\\n) -> OpenAIResponsesResponse | StreamingResponse | OpenAIErrorResponse:\\n    \\\"\\\"\\\"Create a response using OpenAI Responses API format.\\n\\n    This endpoint accepts a flow_id in the model parameter and processes\\n    the input through the specified Langflow flow.\\n\\n    Args:\\n        request: OpenAI Responses API request with model (flow_id) and input\\n        background_tasks: FastAPI background task manager\\n        api_key_user: Authenticated user from API key\\n        http_request: The incoming HTTP request\\n        telemetry_service: Telemetry service for logging\\n\\n    Returns:\\n        OpenAI-compatible response or streaming response\\n\\n    Raises:\\n        HTTPException: For validation errors or flow execution issues\\n    \\\"\\\"\\\"\\n    start_time = time.perf_counter()\\n\\n    # Extract global variables from X-LANGFLOW-GLOBAL-VAR-* headers\\n    variables = extract_global_variables_from_headers(http_request.headers)\\n\\n    await logger.adebug(f\\\"All headers received: {list(http_request.headers.keys())}\\\")\\n    await logger.adebug(f\\\"Extracted global variables from headers: {list(variables.keys())}\\\")\\n\\n    # Validate tools parameter - error out if tools are provided\\n    if request.tools is not None:\\n        error_response = create_openai_error(\\n            message=\\\"Tools are not supported yet\\\",\\n            type_=\\\"invalid_request_error\\\",\\n            code=\\\"tools_not_supported\\\",\\n        )\\n        return OpenAIErrorResponse(error=error_response[\\\"error\\\"])\\n\\n    # Get flow using the model field (which contains flow_id). The lookup\\n    # becomes share-aware when an authorization plugin is registered, so we\\n    # also enforce ``flow:execute`` explicitly \u2014 otherwise an API key with\\n    # cross-user fetch enabled would skip policy here.\\n    try:\\n        flow = await get_flow_by_id_or_endpoint_name(\\n            request.model,\\n            str(api_key_user.id),\\n            widen_for_shares=True,\\n        )\\n    except HTTPException:\\n        flow = None\\n\\n    if flow is None:\\n        return _flow_not_found_response(request.model)\\n\\n    expose_error_details = _caller_owns_flow(flow, api_key_user)\\n\\n    try:\\n        await ensure_flow_permission(\\n            api_key_user,\\n            FlowAction.EXECUTE,\\n            flow_id=flow.id,\\n            flow_user_id=flow.user_id,\\n            workspace_id=getattr(flow, \\\"workspace_id\\\", None),\\n            folder_id=getattr(flow, \\\"folder_id\\\", None),\\n        )\\n    except HTTPException as exc:\\n        if exc.status_code == status.HTTP_403_FORBIDDEN:\\n            return _flow_not_found_response(request.model)\\n        raise\\n\\n    # Required-identity gate must fire BEFORE the run: create_response wraps the run in a blanket\\n    # ``except Exception`` (below) that converts any raise \u2014 including the identity 401 from\\n    # simple_run_flow \u2014 into an OpenAIErrorResponse returned at the route's default 200, and the\\n    # streaming variant returns before the run even executes. Enforce it synchronously here so a\\n    # required-but-absent identity is a real 401 (idempotent with the scope simple_run_flow applies\\n    # again). Mirrors the webhook pre-check (I3). See BUG-01.\\n    try:\\n        resolve_serving_scope(http_request=http_request, requested_session_id=None, default_session_id=str(flow.id))\\n    except EndUserIdentityRequiredError as exc:\\n        raise HTTPException(\\n            status_code=status.HTTP_401_UNAUTHORIZED,\\n            detail=end_user_required_detail(exc),\\n        ) from exc\\n\\n    try:\\n        # Process the request\\n        result = await run_flow_for_openai_responses(\\n            flow=flow,\\n            request=request,\\n            api_key_user=api_key_user,\\n            stream=request.stream,\\n            variables=variables,\\n            http_request=http_request,\\n        )\\n\\n    except CustomComponentValidationError as exc:\\n        await logger.aerror(\\\"OpenAI Responses custom-component validation failed: %s\\\", exc, exc_info=True)\\n        client_error = error_for_client(exc, expose_details=expose_error_details)\\n        error_response = create_openai_error(\\n            message=str(client_error),\\n            type_=\\\"invalid_request_error\\\",\\n            code=\\\"custom_components_blocked\\\",\\n        )\\n        return OpenAIErrorResponse(error=error_response[\\\"error\\\"])\\n\\n    except ValueError as exc:\\n        await logger.aerror(\\\"OpenAI Responses flow validation failed: %s\\\", exc, exc_info=True)\\n        client_error = error_for_client(exc, expose_details=expose_error_details)\\n        error_response = create_openai_error(\\n            message=str(client_error),\\n            type_=\\\"invalid_request_error\\\",\\n            code=\\\"invalid_flow_request\\\",\\n        )\\n        return OpenAIErrorResponse(error=error_response[\\\"error\\\"])\\n\\n    except Exception as exc:  # noqa: BLE001\\n        await logger.aexception(\\\"Error processing OpenAI Responses request\\\")\\n        client_error = error_for_client(exc, expose_details=expose_error_details)\\n\\n        # Log telemetry for failed completion\\n        background_tasks.add_task(\\n            telemetry_service.log_package_run,\\n            RunPayload(\\n                run_is_webhook=False,\\n                run_seconds=int(time.perf_counter() - start_time),\\n                run_success=False,\\n                run_error_message=str(exc),\\n                run_id=None,  # OpenAI endpoint doesn't use simple_run_flow\\n            ),\\n        )\\n\\n        # Return OpenAI-compatible error\\n        error_response = create_openai_error(\\n            message=str(client_error),\\n            type_=\\\"processing_error\\\",\\n        )\\n        return OpenAIErrorResponse(error=error_response[\\\"error\\\"])\\n\\n    # Log telemetry for successful completion\\n    if not request.stream:  # Only log for non-streaming responses\\n        end_time = time.perf_counter()\\n        background_tasks.add_task(\\n            telemetry_service.log_package_run,\\n            RunPayload(\\n                run_is_webhook=False,\\n                run_seconds=int(end_time - start_time),\\n                run_success=True,\\n                run_error_message=\\\"\\\",\\n                run_id=None,  # OpenAI endpoint doesn't use simple_run_flow\\n            ),\\n        )\\n\\n    return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/policy_bundle.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cabdd83ece9feca8869ad4fe007ac696908feb4f5360f4d9f3eb98c2d99007e4\",\"content\":\"\\\"\\\"\\\"Superuser administration for atomic provider-and-catalog policy bundles.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, Query, status\\nfrom lfx.base.models.provider_registry import resolve_provider_id\\nfrom lfx.services.deps import get_catalog_policy_service, get_model_provider_policy_service\\nfrom lfx.services.model_provider_policy import normalize_blocked_model_key\\nfrom lfx.services.policy_bundle import PolicyBundleSnapshot\\nfrom pydantic import BaseModel, Field, StringConstraints, field_validator\\n\\nfrom langflow.api.utils import DbSession, DbSessionReadOnly\\nfrom langflow.api.v1.policy_bundle_errors import policy_bundle_revision_conflict\\nfrom langflow.api.v1.schemas.catalog_policy import CatalogPolicyKeyList, normalize_catalog_policy_keys\\nfrom langflow.services.auth.utils import get_current_active_superuser\\nfrom langflow.services.authorization.audit import AUDIT_ALLOW, audit_decision\\nfrom langflow.services.database.models.policy_bundle import POLICY_BUNDLE_REASON_MAX_LENGTH\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.policy_bundle import (\\n    PolicyBundleApplicationNotSupportedError,\\n    PolicyBundleNotInitializedError,\\n    PolicyBundleRevisionConflictError,\\n    apply_policy_bundle_state,\\n    ensure_policy_bundle_application_supported,\\n    get_policy_bundle_state,\\n    list_policy_bundle_history,\\n    replace_policy_bundle_state,\\n    rollback_policy_bundle_state,\\n)\\n\\nrouter = APIRouter(prefix=\\\"/policy-bundle\\\", tags=[\\\"Policy Bundle\\\"])\\n\\nProviderId = Annotated[str, StringConstraints(pattern=r\\\"^[a-z0-9][a-z0-9._-]*$\\\", max_length=255)]\\n\\n\\nclass PolicyBundleWrite(BaseModel):\\n    \\\"\\\"\\\"Complete replacement guarded by the caller's observed revision.\\\"\\\"\\\"\\n\\n    expected_revision: int = Field(ge=1)\\n    approved_provider_ids: Annotated[list[ProviderId], Field(max_length=1000)]\\n    blocked_component_keys: CatalogPolicyKeyList\\n    blocked_template_keys: CatalogPolicyKeyList\\n    # Defaulted so policy writers built before model blocking existed keep\\n    # working; omitting the field clears no other decision but blocks no models.\\n    blocked_model_keys: CatalogPolicyKeyList = Field(default_factory=list)\\n    reason: str | None = Field(default=None, max_length=POLICY_BUNDLE_REASON_MAX_LENGTH)\\n\\n    @field_validator(\\\"approved_provider_ids\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def canonicalize_provider_ids(cls, provider_ids):\\n        if not isinstance(provider_ids, list):\\n            return provider_ids\\n        return [\\n            resolve_provider_id(provider_id) if isinstance(provider_id, str) else provider_id\\n            for provider_id in provider_ids\\n        ]\\n\\n    @field_validator(\\\"approved_provider_ids\\\")\\n    @classmethod\\n    def deduplicate_provider_ids(cls, provider_ids: list[str]) -> list[str]:\\n        return sorted(set(provider_ids))\\n\\n    @field_validator(\\\"blocked_component_keys\\\", \\\"blocked_template_keys\\\")\\n    @classmethod\\n    def normalize_catalog_keys(cls, values: list[str]) -> list[str]:\\n        return normalize_catalog_policy_keys(values)\\n\\n    @field_validator(\\\"blocked_model_keys\\\")\\n    @classmethod\\n    def normalize_model_keys(cls, values: list[str]) -> list[str]:\\n        try:\\n            normalized = [normalize_blocked_model_key(value) for value in values]\\n        except ValueError as exc:\\n            raise ValueError(str(exc)) from exc\\n        return sorted(set(normalized))\\n\\n\\nclass PolicyBundleRollbackWrite(BaseModel):\\n    expected_revision: int = Field(ge=1)\\n    reason: str | None = Field(default=None, max_length=POLICY_BUNDLE_REASON_MAX_LENGTH)\\n\\n\\nclass PolicyBundleRead(BaseModel):\\n    revision: int\\n    initialized: bool\\n    source: str\\n    approved_provider_ids: list[str]\\n    blocked_component_keys: list[str]\\n    blocked_template_keys: list[str]\\n    blocked_model_keys: list[str]\\n    content_hash: str\\n    created_at: datetime | None\\n    created_by: UUID | None\\n    reason: str | None\\n    rollback_of_revision: int | None\\n    managed_externally: bool = False\\n\\n\\nclass PolicyBundleHistoryRead(BaseModel):\\n    items: list[PolicyBundleRead]\\n    next_before_revision: int | None\\n\\n\\ndef _managed_externally() -> bool:\\n    return (\\n        get_model_provider_policy_service().external_approved_provider_ids is not None\\n        or get_catalog_policy_service().external_policy_snapshot is not None\\n    )\\n\\n\\ndef _response(snapshot: PolicyBundleSnapshot, *, managed_externally: bool = False) -> PolicyBundleRead:\\n    return PolicyBundleRead(\\n        revision=snapshot.revision,\\n        initialized=snapshot.initialized,\\n        source=snapshot.source,\\n        approved_provider_ids=sorted(snapshot.approved_provider_ids),\\n        blocked_component_keys=sorted(snapshot.blocked_component_keys),\\n        blocked_template_keys=sorted(snapshot.blocked_template_keys),\\n        blocked_model_keys=sorted(snapshot.blocked_model_keys),\\n        content_hash=snapshot.content_hash,\\n        created_at=snapshot.created_at,\\n        created_by=snapshot.created_by,\\n        reason=snapshot.reason,\\n        rollback_of_revision=snapshot.rollback_of_revision,\\n        managed_externally=managed_externally,\\n    )\\n\\n\\ndef _unavailable() -> HTTPException:\\n    return HTTPException(\\n        status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n        detail=\\\"Policy bundle is not initialized. Apply the latest database migrations and restart Langflow.\\\",\\n    )\\n\\n\\ndef _raise_if_externally_managed() -> None:\\n    if _managed_externally():\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"Policy bundle is externally managed and cannot be changed through this API.\\\",\\n        )\\n    try:\\n        ensure_policy_bundle_application_supported()\\n    except PolicyBundleApplicationNotSupportedError as exc:\\n        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=str(exc)) from exc\\n\\n\\nasync def _audit_bundle(snapshot: PolicyBundleSnapshot, *, user_id: UUID, action: str) -> None:\\n    await audit_decision(\\n        user_id=user_id,\\n        action=action,\\n        obj=f\\\"policy_bundle:{snapshot.revision}\\\",\\n        result=AUDIT_ALLOW,\\n        details={\\n            \\\"revision\\\": snapshot.revision,\\n            \\\"content_hash\\\": snapshot.content_hash,\\n            \\\"source\\\": snapshot.source,\\n            \\\"rollback_of_revision\\\": snapshot.rollback_of_revision,\\n            \\\"reason\\\": snapshot.reason,\\n        },\\n    )\\n\\n\\n@router.get(\\\"\\\", response_model=PolicyBundleRead)\\n@router.get(\\\"/\\\", response_model=PolicyBundleRead, include_in_schema=False)\\nasync def read_policy_bundle(\\n    _admin: Annotated[User, Depends(get_current_active_superuser)],\\n    session: DbSessionReadOnly,\\n) -> PolicyBundleRead:\\n    try:\\n        snapshot = await get_policy_bundle_state(session)\\n    except PolicyBundleNotInitializedError as exc:\\n        raise _unavailable() from exc\\n    return _response(snapshot, managed_externally=_managed_externally())\\n\\n\\n@router.put(\\\"\\\", response_model=PolicyBundleRead)\\n@router.put(\\\"/\\\", response_model=PolicyBundleRead, include_in_schema=False)\\nasync def replace_policy_bundle(\\n    payload: PolicyBundleWrite,\\n    admin: Annotated[User, Depends(get_current_active_superuser)],\\n    session: DbSession,\\n) -> PolicyBundleRead:\\n    _raise_if_externally_managed()\\n    try:\\n        snapshot = await replace_policy_bundle_state(\\n            session,\\n            expected_revision=payload.expected_revision,\\n            approved_provider_ids=payload.approved_provider_ids,\\n            blocked_component_keys=payload.blocked_component_keys,\\n            blocked_template_keys=payload.blocked_template_keys,\\n            blocked_model_keys=payload.blocked_model_keys,\\n            actor_user_id=admin.id,\\n            reason=payload.reason,\\n        )\\n    except PolicyBundleNotInitializedError as exc:\\n        raise _unavailable() from exc\\n    except PolicyBundleRevisionConflictError as exc:\\n        raise policy_bundle_revision_conflict(exc) from exc\\n\\n    try:\\n        await _audit_bundle(snapshot, user_id=admin.id, action=\\\"policy_bundle:replace\\\")\\n    finally:\\n        apply_policy_bundle_state(snapshot)\\n    return _response(snapshot)\\n\\n\\n@router.get(\\\"/history\\\", response_model=PolicyBundleHistoryRead)\\nasync def read_policy_bundle_history(\\n    _admin: Annotated[User, Depends(get_current_active_superuser)],\\n    session: DbSessionReadOnly,\\n    limit: Annotated[int, Query(ge=1, le=200)] = 50,\\n    before_revision: Annotated[int | None, Query(ge=1)] = None,\\n) -> PolicyBundleHistoryRead:\\n    items = await list_policy_bundle_history(\\n        session,\\n        limit=limit,\\n        before_revision=before_revision,\\n    )\\n    next_before_revision = items[-1].revision if len(items) == limit else None\\n    return PolicyBundleHistoryRead(\\n        items=[_response(item) for item in items],\\n        next_before_revision=next_before_revision,\\n    )\\n\\n\\n@router.post(\\\"/rollback/{revision}\\\", response_model=PolicyBundleRead)\\nasync def rollback_policy_bundle(\\n    revision: int,\\n    payload: PolicyBundleRollbackWrite,\\n    admin: Annotated[User, Depends(get_current_active_superuser)],\\n    session: DbSession,\\n) -> PolicyBundleRead:\\n    _raise_if_externally_managed()\\n    try:\\n        snapshot = await rollback_policy_bundle_state(\\n            session,\\n            expected_revision=payload.expected_revision,\\n            target_revision=revision,\\n            actor_user_id=admin.id,\\n            reason=payload.reason,\\n        )\\n    except PolicyBundleNotInitializedError as exc:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=str(exc)) from exc\\n    except PolicyBundleRevisionConflictError as exc:\\n        raise policy_bundle_revision_conflict(exc) from exc\\n\\n    try:\\n        await _audit_bundle(snapshot, user_id=admin.id, action=\\\"policy_bundle:rollback\\\")\\n    finally:\\n        apply_policy_bundle_state(snapshot)\\n    return _response(snapshot)\\n\\n\\n__all__ = [\\n    \\\"PolicyBundleHistoryRead\\\",\\n    \\\"PolicyBundleRead\\\",\\n    \\\"PolicyBundleRollbackWrite\\\",\\n    \\\"PolicyBundleWrite\\\",\\n    \\\"router\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/policy_bundle_errors.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ca8d83b31f85a7dbc1ece9a64fb16e803bb2ee98b707b70d48d79a2d240103ef\",\"content\":\"\\\"\\\"\\\"Shared HTTP error mapping for policy-bundle-backed administration APIs.\\\"\\\"\\\"\\n\\nfrom fastapi import HTTPException, status\\n\\nfrom langflow.services.policy_bundle import PolicyBundleRevisionConflictError\\n\\n\\ndef policy_bundle_revision_conflict(exc: PolicyBundleRevisionConflictError) -> HTTPException:\\n    \\\"\\\"\\\"Preserve the structured optimistic-concurrency response across policy APIs.\\\"\\\"\\\"\\n    return HTTPException(\\n        status_code=status.HTTP_409_CONFLICT,\\n        detail={\\n            \\\"message\\\": \\\"Policy bundle revision conflict\\\",\\n            \\\"expected_revision\\\": exc.expected_revision,\\n            \\\"active_revision\\\": exc.active_revision,\\n        },\\n    )\\n\\n\\n__all__ = [\\\"policy_bundle_revision_conflict\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/projects.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1f5982f05c632010df5b156924025517dadc99e1bcae553614cffdc7a4dd6263\",\"content\":\"import warnings\\nfrom typing import Annotated, cast\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, BackgroundTasks, Depends, File, HTTPException, Query, Response, UploadFile, status\\nfrom fastapi.encoders import jsonable_encoder\\nfrom fastapi_pagination import Params\\nfrom fastapi_pagination.ext.sqlmodel import apaginate\\nfrom lfx.log.logger import logger\\nfrom lfx.services.mcp_composer.service import MCPComposerService\\nfrom lfx.utils.util_strings import escape_like_pattern\\nfrom sqlalchemy import literal, null, or_, update\\nfrom sqlalchemy.orm import selectinload\\nfrom sqlmodel import select\\n\\nfrom langflow.api.utils import (\\n    CurrentActiveUser,\\n    DbSession,\\n    cascade_delete_flow,\\n    custom_params,\\n)\\nfrom langflow.api.v1.auth_helpers import handle_auth_settings_update\\nfrom langflow.api.v1.flows import _handle_unique_constraint_error\\nfrom langflow.api.v1.mappers.deployments.sync import (\\n    retry_flow_operation_on_deployment_guard,\\n    retry_project_operation_on_deployment_guard,\\n)\\nfrom langflow.api.v1.mcp_projects import register_project_with_composer\\nfrom langflow.api.v1.projects_files import download_project_flows, upload_project_flows\\nfrom langflow.api.v1.projects_mcp_helpers import (\\n    cleanup_mcp_on_delete,\\n    handle_mcp_server_rename,\\n    reconcile_mcp_server_for_auth_update,\\n    register_mcp_servers_for_project,\\n)\\nfrom langflow.initial_setup.constants import ASSISTANT_FOLDER_NAME, STARTER_FOLDER_NAME\\nfrom langflow.services.auth.mcp_encryption import encrypt_auth_settings\\nfrom langflow.services.authorization import (\\n    FlowAction,\\n    ProjectAction,\\n    ensure_project_permission,\\n    filter_visible_resources,\\n    resource_visible_in_scope,\\n    restrict_to_owned_or_visible_scope,\\n    visible_scope_prefilter,\\n)\\nfrom langflow.services.authorization.fetch import (\\n    authorized_or_owner_scoped,\\n    deny_to_404,\\n    deny_to_404_unless_readable,\\n)\\nfrom langflow.services.authorization.utils import _resolve_authz_domain\\nfrom langflow.services.database.lock_retry import (\\n    is_database_lock_error,\\n    run_with_lock_retry,\\n    sanitize_database_error,\\n)\\nfrom langflow.services.database.models.deployment.exceptions import (\\n    araise_if_deployment_guard_error_or_skip,\\n    remap_flow_guard_for_project_delete,\\n)\\nfrom langflow.services.database.models.deployment.guards import check_project_has_deployments\\nfrom langflow.services.database.models.deployment.orm_guards import ensure_flow_moves_allowed\\nfrom langflow.services.database.models.flow.model import Flow, FlowRead\\nfrom langflow.services.database.models.folder.constants import DEFAULT_FOLDER_NAME\\nfrom langflow.services.database.models.folder.model import (\\n    Folder,\\n    FolderCreate,\\n    FolderListRead,\\n    FolderRead,\\n    FolderReadWithFlows,\\n    FolderUpdate,\\n)\\nfrom langflow.services.database.models.folder.pagination_model import FolderWithPaginatedFlows\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_service, get_settings_service\\nfrom langflow.services.schema import ServiceType\\n\\nrouter = APIRouter(prefix=\\\"/projects\\\", tags=[\\\"Projects\\\"])\\n\\nPROJECT_READ_FAILED = \\\"Could not read the project.\\\"\\nPROJECT_CREATE_FAILED = \\\"Could not create the project.\\\"\\nPROJECT_UPDATE_FAILED = \\\"Could not update the project.\\\"\\nPROJECT_SAVE_FAILED = \\\"Could not save the project.\\\"\\nPROJECT_DELETE_FAILED = \\\"Could not delete the project.\\\"\\nPROJECT_DELETE_BUSY = \\\"The database is busy. Please retry the request.\\\"\\nPROJECT_WRITE_DENIED_DETAIL = \\\"You don't have permission to edit this project.\\\"\\nPROJECT_DELETE_DENIED_DETAIL = \\\"You don't have permission to delete this project.\\\"\\n\\n# Backwards-compatible local alias; the implementation now lives in lfx.utils.util_strings so the\\n# same LIKE-escaping is shared across the API endpoints + the tracing repository.\\n_escape_like = escape_like_pattern\\n\\n\\nasync def _new_project(\\n    *,\\n    session: DbSession,\\n    project: FolderCreate,\\n    current_user: User,\\n    project_id: UUID | None = None,\\n    fail_on_name_conflict: bool = False,\\n) -> FolderRead:\\n    \\\"\\\"\\\"Create a project (folder), optionally at a caller-specified id (PUT upsert).\\n\\n    Mirrors ``_new_flow``:\\n    - ``project_id`` overrides the ``uuid4`` default when provided so a project can be\\n      synced across instances under the same UUID.\\n    - ``fail_on_name_conflict`` skips the auto-rename dedup loop so a name collision fails\\n      loud via the ``(user_id, name)`` unique constraint (mapped to 409 by the caller) instead\\n      of silently appending ``\\\" (N)\\\"``.\\n\\n    Runs the same MCP server auto-registration + AUTO_LOGIN apikey auth + flow-move side\\n    effects as ``POST /projects/``. Raises on unique-constraint / deployment-guard errors;\\n    callers map those to HTTP status.\\n\\n    ``current_user`` (the full ``User``) is required because the MCP registration and flow-move\\n    side effects operate on the owning user, not just their id.\\n    \\\"\\\"\\\"\\n    new_project = Folder.model_validate(project, from_attributes=True)\\n    new_project.user_id = current_user.id\\n    # Apply the stable id: an explicit ``project_id`` (PUT upsert) overrides the uuid4 default.\\n    if project_id is not None:\\n        new_project.id = project_id\\n\\n    # POST auto-renames on a name collision; PUT (fail_on_name_conflict) skips the dedup so the\\n    # unique constraint fires and the caller can surface a 409. Dedup uses a LIKE scan over\\n    # existing project names (e.g. \\\"MyProject\\\", \\\"MyProject (1)\\\", \\\"MyProject (2)\\\") to find the\\n    # highest suffix and append N+1.\\n    if (\\n        not fail_on_name_conflict\\n        and (\\n            await session.exec(\\n                statement=select(Folder).where(Folder.name == new_project.name).where(Folder.user_id == current_user.id)\\n            )\\n        ).first()\\n    ):\\n        escaped_project_name = _escape_like(new_project.name)\\n        project_results = await session.exec(\\n            select(Folder).where(\\n                Folder.name.like(f\\\"{escaped_project_name}%\\\", escape=\\\"\\\\\\\\\\\"),  # type: ignore[attr-defined]\\n                Folder.user_id == current_user.id,\\n            )\\n        )\\n        # No emptiness guard: session.exec() returns a ScalarResult, which is always truthy even\\n        # when it yields no rows. Iterating an empty result simply leaves project_numbers empty.\\n        project_numbers = []\\n        for name in (existing.name for existing in project_results):\\n            if \\\"(\\\" not in name:\\n                continue\\n            try:\\n                project_numbers.append(int(name.split(\\\"(\\\")[-1].split(\\\")\\\")[0]))\\n            except ValueError:\\n                continue\\n        if project_numbers:\\n            new_project.name = f\\\"{new_project.name} ({max(project_numbers) + 1})\\\"\\n        else:\\n            new_project.name = f\\\"{new_project.name} (1)\\\"\\n\\n    settings_service = get_settings_service()\\n    mcp_auth: dict = {\\\"auth_type\\\": \\\"none\\\"}\\n\\n    if project.auth_settings:\\n        mcp_auth = project.auth_settings.copy()\\n        new_project.auth_settings = encrypt_auth_settings(mcp_auth)\\n    # If AUTO_LOGIN is false, automatically enable API key authentication\\n    elif not settings_service.auth_settings.AUTO_LOGIN:\\n        mcp_auth = {\\\"auth_type\\\": \\\"apikey\\\"}\\n        new_project.auth_settings = encrypt_auth_settings(mcp_auth)\\n        await logger.adebug(\\n            \\\"Auto-enabled API key authentication for project %s (%s) due to AUTO_LOGIN=false\\\",\\n            new_project.name,\\n            new_project.id,\\n        )\\n\\n    session.add(new_project)\\n    await session.flush()\\n    await session.refresh(new_project)\\n\\n    # Auto-register MCP server for this project with configured default auth\\n    if get_settings_service().settings.add_projects_to_mcp_servers:\\n        await register_mcp_servers_for_project(new_project, mcp_auth, current_user, session)\\n\\n    flow_ids_for_sync = list(dict.fromkeys((project.flows_list or []) + (project.components_list or [])))\\n    authorized_flow_owner_ids: dict[UUID, UUID] = {}\\n\\n    async def _move_flows_into_project() -> None:\\n        if project.components_list:\\n            component_flows = (\\n                await session.exec(\\n                    select(Flow.id, Flow.folder_id).where(\\n                        Flow.id.in_(project.components_list),  # type: ignore[attr-defined]\\n                        Flow.user_id == current_user.id,\\n                    )\\n                )\\n            ).all()\\n            authorized_flow_owner_ids.update((flow_id, current_user.id) for flow_id, _folder_id in component_flows)\\n            await ensure_flow_moves_allowed(\\n                session,\\n                flow_folder_pairs=list(component_flows),\\n                new_folder_id=new_project.id,\\n            )\\n            update_statement_components = (\\n                update(Flow)\\n                .where(Flow.id.in_(project.components_list), Flow.user_id == current_user.id)  # type: ignore[attr-defined]\\n                .values(folder_id=new_project.id, workspace_id=new_project.workspace_id)\\n            )\\n            await session.exec(update_statement_components)\\n\\n        if project.flows_list:\\n            project_flows = (\\n                await session.exec(\\n                    select(Flow.id, Flow.folder_id).where(\\n                        Flow.id.in_(project.flows_list),  # type: ignore[attr-defined]\\n                        Flow.user_id == current_user.id,\\n                    )\\n                )\\n            ).all()\\n            authorized_flow_owner_ids.update((flow_id, current_user.id) for flow_id, _folder_id in project_flows)\\n            await ensure_flow_moves_allowed(\\n                session,\\n                flow_folder_pairs=list(project_flows),\\n                new_folder_id=new_project.id,\\n            )\\n            update_statement_flows = (\\n                update(Flow)\\n                .where(Flow.id.in_(project.flows_list), Flow.user_id == current_user.id)  # type: ignore[attr-defined]\\n                .values(folder_id=new_project.id, workspace_id=new_project.workspace_id)\\n            )\\n            await session.exec(update_statement_flows)\\n\\n    if flow_ids_for_sync:\\n        await retry_flow_operation_on_deployment_guard(\\n            db=session,\\n            flow_owner_ids=authorized_flow_owner_ids,\\n            operation=_move_flows_into_project,\\n        )\\n    else:\\n        await _move_flows_into_project()\\n\\n    # Convert to FolderRead while session is still active to avoid detached instance errors\\n    return FolderRead.model_validate(new_project, from_attributes=True)\\n\\n\\n@router.post(\\\"/\\\", response_model=FolderRead, status_code=201)\\nasync def create_project(\\n    *,\\n    session: DbSession,\\n    project: FolderCreate,\\n    current_user: CurrentActiveUser,\\n):\\n    await ensure_project_permission(\\n        current_user, ProjectAction.CREATE, workspace_id=getattr(project, \\\"workspace_id\\\", None)\\n    )\\n    try:\\n        return await _new_project(\\n            session=session,\\n            project=project,\\n            current_user=current_user,\\n        )\\n    except HTTPException:\\n        # Re-raise HTTP exceptions (like 409 conflicts) without modification\\n        raise\\n    except Exception as e:\\n        await araise_if_deployment_guard_error_or_skip(\\n            e,\\n            log_message=\\\"op=create_project\\\",\\n        )\\n        raise HTTPException(status_code=500, detail=sanitize_database_error(e, PROJECT_CREATE_FAILED)) from e\\n\\n\\n@router.get(\\\"/\\\", response_model=list[FolderListRead], status_code=200)\\nasync def read_projects(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n):\\n    try:\\n        # Rows the caller owns outright. The legacy owner-scoped fallback also\\n        # surfaces null-owner projects (e.g. the starter project), but those must\\n        # be policy-checked rather than blanket-included: ``filter_visible_resources``\\n        # below treats a null owner as un-owned (its ``owner_extractor`` returns\\n        # None, which never equals a real user id) and routes them through\\n        # ``batch_enforce``. So the SQL prefilter union uses the owned-only clause\\n        # \u2014 a null-owner project is visible only when the plugin lists its id \u2014\\n        # keeping both paths' null semantics identical (the name filter below is\\n        # then a convenience, not the thing preventing a null-owner leak).\\n        owned_clause = Folder.user_id == current_user.id\\n        # DB-layer authz prefilter: when a plugin returns the concrete set of\\n        # project ids the caller may read, widen the owner-scoped query to\\n        # (owned \u2295 visible) in SQL and skip the per-row in-memory filter below.\\n        # OSS pass-through returns None \u2192 owner-scoped query + filter unchanged.\\n        visibility_scope = await visible_scope_prefilter(current_user, resource_type=\\\"project\\\", act=ProjectAction.READ)\\n        if visibility_scope is not None:\\n            stmt = restrict_to_owned_or_visible_scope(\\n                select(Folder),\\n                id_column=Folder.id,\\n                owner_clause=owned_clause,\\n                workspace_column=Folder.workspace_id,\\n                project_column=Folder.id,\\n                visibility=visibility_scope,\\n            )\\n        else:\\n            stmt = select(Folder).where(or_(owned_clause, Folder.user_id == None))  # noqa: E711\\n        projects = (await session.exec(stmt)).all()\\n        projects = [\\n            project for project in projects if not (project.name == STARTER_FOLDER_NAME and project.user_id is None)\\n        ]\\n        # When no DB prefilter is available (OSS pass-through), drop projects the\\n        # user can't read in memory. ``domain_extractor`` groups requests by\\n        # concrete project so each batch is evaluated against the same policy\\n        # tuple as the single-resource guard. When the prefilter is active the\\n        # SQL union is already authoritative \u2014 skip the per-row enforce to\\n        # avoid an N+1.\\n        if visibility_scope is None:\\n            projects = await filter_visible_resources(\\n                current_user,\\n                resource_type=\\\"project\\\",\\n                candidates=list(projects),\\n                domain_extractor=lambda project: _resolve_authz_domain(project.workspace_id, project.id),\\n                owner_extractor=lambda project: project.user_id,\\n                act=ProjectAction.READ,\\n            )\\n        sorted_projects = sorted(projects, key=lambda x: x.name != DEFAULT_FOLDER_NAME)\\n\\n        owner_ids = {project.user_id for project in sorted_projects if project.user_id is not None}\\n        owners_by_id: dict[str, str] = {}\\n        if owner_ids:\\n            owner_rows = (await session.exec(select(User.id, User.username).where(User.id.in_(owner_ids)))).all()\\n            owners_by_id = {str(owner_id): username for owner_id, username in owner_rows}\\n\\n        # Convert while the session is active so owner-qualified project lists\\n        # do not trigger lazy loads after the request-scoped session closes.\\n        return [\\n            FolderListRead.model_validate(\\n                project,\\n                from_attributes=True,\\n                update={\\n                    \\\"owner_username\\\": owners_by_id.get(str(project.user_id)) if project.user_id is not None else None,\\n                    \\\"is_owner\\\": str(project.user_id) == str(current_user.id),\\n                },\\n            )\\n            for project in sorted_projects\\n        ]\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=sanitize_database_error(e, PROJECT_READ_FAILED)) from e\\n\\n\\n@router.get(\\\"/{project_id}\\\", response_model=FolderWithPaginatedFlows | FolderReadWithFlows, status_code=200)\\nasync def read_project(\\n    *,\\n    session: DbSession,\\n    project_id: UUID,\\n    current_user: CurrentActiveUser,\\n    params: Annotated[Params | None, Depends(custom_params)],\\n    page: Annotated[int | None, Query()] = None,\\n    size: Annotated[int | None, Query()] = None,\\n    is_component: bool = False,\\n    is_flow: bool = False,\\n    search: str = \\\"\\\",\\n):\\n    try:\\n        # Share-aware fetch: when an authorization plugin is\\n        # registered (``SUPPORTS_CROSS_USER_FETCH=True``) the project is\\n        # loaded by id alone and ``ensure_project_permission`` below decides\\n        # access. The OSS pass-through keeps the owner-scoped query so the\\n        # strict-pass-through stub cannot widen visibility.\\n        from langflow.services.deps import get_authorization_service\\n\\n        authz = get_authorization_service()\\n        # Cross-user fetch only when both the plugin capability and the\\n        # ``AUTHZ_ENABLED`` flag are on \u2014 otherwise route guards are no-ops\\n        # and widening the lookup would expose foreign projects without any\\n        # policy check.\\n        share_aware = await authz.supports_cross_user_fetch() and await authz.is_enabled()\\n        stmt = select(Folder).options(selectinload(Folder.flows)).where(Folder.id == project_id)\\n        if not share_aware:\\n            stmt = stmt.where(Folder.user_id == current_user.id)\\n        project = (await session.exec(stmt)).first()\\n    except Exception as e:\\n        if \\\"No result found\\\" in str(e):\\n            raise HTTPException(status_code=404, detail=\\\"Project not found\\\") from e\\n        raise HTTPException(status_code=500, detail=sanitize_database_error(e, PROJECT_READ_FAILED)) from e\\n\\n    if not project:\\n        raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n    try:\\n        await ensure_project_permission(\\n            current_user,\\n            ProjectAction.READ,\\n            project_id=project_id,\\n            project_user_id=project.user_id,\\n            workspace_id=project.workspace_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Project not found\\\") from exc\\n\\n    try:\\n        # When share-aware fetch is on and the project is not owned by the\\n        # caller (i.e. reached via a share grant), show all flows in the\\n        # project \u2014 the share grant on the project implies access to its\\n        # contents. Otherwise keep the existing owner-scoped flow filter.\\n        treat_as_shared = share_aware and project.user_id != current_user.id\\n\\n        # DB-layer authz prefilter for the project's flows. Only meaningful for\\n        # shared-project reads (owner reads are already owner-scoped and run no\\n        # per-flow enforce). A concrete list lets us constrain the paginated SQL\\n        # query / set-filter the eager-loaded collection to (owned \u2295 visible) and\\n        # skip the per-row enforce; None keeps the in-memory fallback. The flows\\n        # all live in this project, so a single project-scoped domain applies.\\n        visibility_scope = (\\n            await visible_scope_prefilter(\\n                current_user,\\n                resource_type=\\\"flow\\\",\\n                domain=_resolve_authz_domain(project.workspace_id, project_id),\\n                act=FlowAction.READ,\\n            )\\n            if treat_as_shared\\n            else None\\n        )\\n\\n        # Check if pagination is explicitly requested by the user (both page and size provided)\\n        if page is not None and size is not None:\\n            stmt = select(Flow).where(Flow.folder_id == project_id)\\n            if not treat_as_shared:\\n                stmt = stmt.where(Flow.user_id == current_user.id)\\n            elif visibility_scope is not None:\\n                # Shared project with a concrete prefilter: widen to\\n                # (owned \u2295 visible) at the DB layer so ``page.total`` reflects the\\n                # prefilter and no per-row enforce runs.\\n                stmt = restrict_to_owned_or_visible_scope(\\n                    stmt,\\n                    id_column=Flow.id,\\n                    owner_clause=Flow.user_id == current_user.id,\\n                    workspace_expression=null() if project.workspace_id is None else literal(project.workspace_id),\\n                    project_column=Flow.folder_id,\\n                    visibility=visibility_scope,\\n                )\\n\\n            if Flow.updated_at is not None:\\n                stmt = stmt.order_by(Flow.updated_at.desc())  # type: ignore[attr-defined]\\n            if is_component:\\n                stmt = stmt.where(Flow.is_component == True)  # noqa: E712\\n            if is_flow:\\n                stmt = stmt.where(Flow.is_component == False)  # noqa: E712\\n            if search:\\n                _search = _escape_like(search)\\n                stmt = stmt.where(Flow.name.like(f\\\"%{_search}%\\\", escape=\\\"\\\\\\\\\\\"))  # type: ignore[attr-defined]\\n\\n            with warnings.catch_warnings():\\n                warnings.filterwarnings(\\n                    \\\"ignore\\\", category=DeprecationWarning, module=r\\\"fastapi_pagination\\\\.ext\\\\.sqlalchemy\\\"\\n                )\\n                paginated_flows = await apaginate(session, stmt, params=params)\\n\\n            # Apply the same per-flow authz filter the non-paginated branch\\n            # uses so shared-project reads behave identically regardless of\\n            # page/size. Without this, a project READ grant would expose\\n            # every flow in the page even when finer-grained per-flow\\n            # policy (deny rules, lower-permission shares) should narrow\\n            # the result. OSS pass-through returns the input unchanged.\\n            # Only runs as the in-memory fallback: when a concrete prefilter is\\n            # available the SQL union above already narrowed the page (and\\n            # ``page.total``); this fallback path's ``page.total`` may overcount\\n            # when items are dropped \u2014 same caveat as ``read_flows``.\\n            if treat_as_shared and visibility_scope is None:\\n                paginated_flows.items = await filter_visible_resources(\\n                    current_user,\\n                    resource_type=\\\"flow\\\",\\n                    candidates=list(paginated_flows.items),\\n                    domain_extractor=lambda flow: _resolve_authz_domain(project.workspace_id, flow.folder_id),\\n                    owner_extractor=lambda flow: flow.user_id,\\n                    act=FlowAction.READ,\\n                )\\n\\n            return FolderWithPaginatedFlows(folder=FolderRead.model_validate(project), flows=paginated_flows)\\n\\n        # If no pagination requested, return flows visible to the caller.\\n        if treat_as_shared:\\n            # A project share grant implies access to the project itself, but\\n            # per-flow policy (deny rules, lower scopes) still applies. Without\\n            # this, ``list(project.flows)`` would leak every flow in the project\\n            # regardless of finer-grained policy engine rules the plugin may\\n            # have. OSS pass-through returns the input list unchanged, so this\\n            # has no effect on default OSS installs.\\n            if visibility_scope is not None:\\n                # Eager-loaded ``project.flows`` constrained to (owned \u2295 visible)\\n                # by set membership \u2014 the same union as the SQL prefilter, applied\\n                # in memory because the relationship is already materialized\\n                # (still no per-row enforce, so no N+1).\\n                visible_flows = [\\n                    flow\\n                    for flow in project.flows\\n                    if flow.user_id == current_user.id\\n                    or resource_visible_in_scope(\\n                        resource_id=flow.id,\\n                        workspace_id=project.workspace_id,\\n                        project_id=flow.folder_id,\\n                        visibility=visibility_scope,\\n                    )\\n                ]\\n            else:\\n                visible_flows = await filter_visible_resources(\\n                    current_user,\\n                    resource_type=\\\"flow\\\",\\n                    candidates=list(project.flows),\\n                    domain_extractor=lambda flow: _resolve_authz_domain(project.workspace_id, flow.folder_id),\\n                    owner_extractor=lambda flow: flow.user_id,\\n                    act=FlowAction.READ,\\n                )\\n        else:\\n            visible_flows = [flow for flow in project.flows if flow.user_id == current_user.id]\\n        # Convert without assigning the filtered list back to the ORM\\n        # relationship. ``Folder.flows`` owns delete-orphan cascade; mutating it\\n        # in this GET handler would delete every hidden flow when the request\\n        # session commits.\\n        project_read = FolderReadWithFlows.model_validate(project, from_attributes=True)\\n        project_read.flows = [FlowRead.model_validate(flow, from_attributes=True) for flow in visible_flows]\\n        return project_read  # noqa: TRY300 - conversion must happen while the ORM session is active\\n\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=sanitize_database_error(e, PROJECT_READ_FAILED)) from e\\n\\n\\nasync def _apply_project_update(\\n    *,\\n    session: DbSession,\\n    existing_project: Folder,\\n    project: FolderUpdate,\\n    current_user: User,\\n    background_tasks: BackgroundTasks,\\n) -> FolderRead:\\n    \\\"\\\"\\\"Apply an in-place project update, shared by PATCH and the PUT upsert update branch.\\n\\n    A rename onto a name the owner already uses fails loud as 409 *before* the row is mutated.\\n    Relying on the ``(user_id, name)`` constraint instead does not work here: assigning the name\\n    dirties the ORM row, the next query autoflushes, and ``handle_mcp_server_rename``'s blanket\\n    ``except Exception`` swallows the resulting IntegrityError \u2014 leaving the session needing\\n    rollback so the later flush raises PendingRollbackError, which reached callers as a 500\\n    carrying the SQL statement and bound parameters.\\n\\n    A concurrent rename that slips between that check and the flush still hits the constraint;\\n    both callers map it through _handle_unique_constraint_error, so it also surfaces as a 409.\\n\\n    Raises on deployment-guard errors; callers map those to their own status.\\n    \\\"\\\"\\\"\\n    if (\\n        project.name is not None\\n        and project.name != existing_project.name\\n        and existing_project.name == STARTER_FOLDER_NAME\\n        and existing_project.user_id is None\\n    ):\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=f\\\"The system-managed '{STARTER_FOLDER_NAME}' project cannot be renamed.\\\",\\n        )\\n\\n    # Rename collision -> 409, checked before the mutation (see docstring). Scoped to the project\\n    # owner because the constraint is ``(user_id, name)``; the constraint still backstops a\\n    # concurrent rename that slips between this check and the flush.\\n    if project.name is not None and project.name != existing_project.name:\\n        name_taken = (\\n            await session.exec(\\n                select(Folder.id).where(\\n                    Folder.name == project.name,\\n                    Folder.user_id == existing_project.user_id,\\n                    Folder.id != existing_project.id,\\n                )\\n            )\\n        ).first()\\n        if name_taken is not None:\\n            raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=\\\"Project name must be unique\\\")\\n\\n    # Flow rollup uses the project owner \u2014 a non-owner editing a shared\\n    # project must touch the owner's flows, not the actor's same-folder\\n    # flows (which would be empty for a non-owner anyway).\\n    project_owner_id = existing_project.user_id\\n    result = await session.exec(\\n        select(Flow.id, Flow.is_component).where(\\n            Flow.folder_id == existing_project.id, Flow.user_id == project_owner_id\\n        )\\n    )\\n    flows_and_components = result.all()\\n\\n    project.flows = [flow_id for flow_id, is_component in flows_and_components if not is_component]\\n    project.components = [flow_id for flow_id, is_component in flows_and_components if is_component]\\n\\n    # Track if MCP Composer needs to be started or stopped\\n    should_start_mcp_composer = False\\n    should_stop_mcp_composer = False\\n    new_auth_type: str | None = None\\n    auth_settings_updated = False\\n\\n    # Check if auth_settings is being updated\\n    if \\\"auth_settings\\\" in project.model_fields_set:  # Check if auth_settings was explicitly provided\\n        auth_result = handle_auth_settings_update(\\n            existing_project=existing_project,\\n            new_auth_settings=project.auth_settings,\\n        )\\n\\n        should_start_mcp_composer = auth_result[\\\"should_start_composer\\\"]\\n        should_stop_mcp_composer = auth_result[\\\"should_stop_composer\\\"]\\n        new_auth_type = auth_result[\\\"new_auth_type\\\"]\\n        auth_settings_updated = True\\n\\n    # Handle project rename and corresponding MCP server rename\\n    if project.name and project.name != existing_project.name:\\n        old_project_name = existing_project.name\\n        existing_project.name = project.name\\n\\n        if get_settings_service().settings.add_projects_to_mcp_servers:\\n            await handle_mcp_server_rename(existing_project, old_project_name, project.name, current_user, session)\\n\\n    if project.description is not None:\\n        existing_project.description = project.description\\n\\n    if project.parent_id is not None:\\n        # Validate the supplied parent references a folder owned by the project owner, so\\n        # shared-project writes cannot create cross-owner folder hierarchies.\\n        parent = (\\n            await session.exec(select(Folder).where(Folder.id == project.parent_id, Folder.user_id == project_owner_id))\\n        ).first()\\n        if parent is None:\\n            raise HTTPException(status_code=404, detail=\\\"Parent project not found\\\")\\n        existing_project.parent_id = project.parent_id\\n\\n    session.add(existing_project)\\n    await session.flush()\\n    await session.refresh(existing_project)\\n\\n    # Start MCP Composer if auth changed to OAuth\\n    if should_start_mcp_composer:\\n        await logger.adebug(\\n            \\\"Auth settings changed to OAuth for project %s (%s), starting MCP Composer\\\",\\n            existing_project.name,\\n            existing_project.id,\\n        )\\n        background_tasks.add_task(register_project_with_composer, existing_project)\\n\\n    # Stop MCP Composer if auth changed FROM OAuth to something else\\n    elif should_stop_mcp_composer:\\n        await logger.ainfo(\\n            \\\"Auth settings changed from OAuth for project %s (%s), stopping MCP Composer\\\",\\n            existing_project.name,\\n            existing_project.id,\\n        )\\n\\n        mcp_composer_service: MCPComposerService = cast(\\n            MCPComposerService, get_service(ServiceType.MCP_COMPOSER_SERVICE)\\n        )\\n        await mcp_composer_service.stop_project_composer(str(existing_project.id))\\n\\n    # Sync MCP server config for apikey/none auth; OAuth is handled by MCP Composer above.\\n    if auth_settings_updated and new_auth_type in {\\\"apikey\\\", \\\"none\\\"}:\\n        try:\\n            await reconcile_mcp_server_for_auth_update(\\n                existing_project,\\n                new_auth_type,\\n                current_user,\\n                session,\\n            )\\n        except HTTPException:\\n            raise\\n        except Exception as e:  # noqa: BLE001\\n            await logger.awarning(\\n                \\\"Failed to reconcile MCP server config for project %s after auth update: %s\\\",\\n                existing_project.id,\\n                e,\\n            )\\n\\n    concat_project_components = project.components + project.flows\\n\\n    # Both queries scope to the project owner. Every user gets their own folder named\\n    # DEFAULT_FOLDER_NAME (see get_or_create_default_folder), so an unscoped ``.first()`` can\\n    # return a *different* user's folder and this code would move the owner's excluded flows into\\n    # it, copying that stranger's workspace_id. get_default_folder_id() scopes the same lookup by\\n    # user_id; match it. If the owner has no default folder the move is skipped by the guard\\n    # below, which is the safe outcome.\\n    flows_ids = (\\n        await session.exec(\\n            select(Flow.id).where(Flow.folder_id == existing_project.id, Flow.user_id == project_owner_id)\\n        )\\n    ).all()\\n\\n    excluded_flows = list(set(flows_ids) - set(project.flows))\\n\\n    my_collection_project = (\\n        await session.exec(select(Folder).where(Folder.name == DEFAULT_FOLDER_NAME, Folder.user_id == project_owner_id))\\n    ).first()\\n    flow_ids_for_sync = list(dict.fromkeys(excluded_flows + concat_project_components))\\n    authorized_flow_owner_ids: dict[UUID, UUID] = {}\\n\\n    async def _move_flows_for_project_update() -> None:\\n        # Both SELECT and UPDATE must scope to the project owner \u2014 a\\n        # non-owner editing a shared project must touch the *owner's*\\n        # flows, not the actor's. The previous code filtered the SELECT\\n        # by ``current_user.id`` (returning zero rows for non-owners) but\\n        # then ran an UPDATE without any owner filter, so an id collision\\n        # would have moved cross-user flows without per-flow authz.\\n        # Scoping both statements to ``project_owner_id`` closes the gap.\\n        if my_collection_project:\\n            excluded_flow_rows = (\\n                await session.exec(\\n                    select(Flow.id, Flow.folder_id).where(\\n                        Flow.id.in_(excluded_flows),  # type: ignore[attr-defined]\\n                        Flow.user_id == project_owner_id,\\n                    )\\n                )\\n            ).all()\\n            authorized_flow_owner_ids.update((flow_id, project_owner_id) for flow_id, _folder_id in excluded_flow_rows)\\n            await ensure_flow_moves_allowed(\\n                session,\\n                flow_folder_pairs=list(excluded_flow_rows),\\n                new_folder_id=my_collection_project.id,\\n            )\\n            update_statement_my_collection = (\\n                update(Flow)\\n                .where(\\n                    Flow.id.in_(excluded_flows),  # type: ignore[attr-defined]\\n                    Flow.user_id == project_owner_id,\\n                )\\n                .values(folder_id=my_collection_project.id, workspace_id=my_collection_project.workspace_id)\\n            )\\n            await session.exec(update_statement_my_collection)\\n\\n        if concat_project_components:\\n            component_flow_rows = (\\n                await session.exec(\\n                    select(Flow.id, Flow.folder_id).where(\\n                        Flow.id.in_(concat_project_components),  # type: ignore[attr-defined]\\n                        Flow.user_id == project_owner_id,\\n                    )\\n                )\\n            ).all()\\n            authorized_flow_owner_ids.update((flow_id, project_owner_id) for flow_id, _folder_id in component_flow_rows)\\n            await ensure_flow_moves_allowed(\\n                session,\\n                flow_folder_pairs=list(component_flow_rows),\\n                new_folder_id=existing_project.id,\\n            )\\n            update_statement_components = (\\n                update(Flow)\\n                .where(\\n                    Flow.id.in_(concat_project_components),  # type: ignore[attr-defined]\\n                    Flow.user_id == project_owner_id,\\n                )\\n                .values(folder_id=existing_project.id, workspace_id=existing_project.workspace_id)\\n            )\\n            await session.exec(update_statement_components)\\n\\n    if flow_ids_for_sync:\\n        await retry_flow_operation_on_deployment_guard(\\n            db=session,\\n            flow_owner_ids=authorized_flow_owner_ids,\\n            operation=_move_flows_for_project_update,\\n        )\\n    else:\\n        await _move_flows_for_project_update()\\n\\n    # Convert to FolderRead while session is still active to avoid detached instance errors\\n    return FolderRead.model_validate(existing_project, from_attributes=True)\\n\\n\\ndef _folder_create_to_update(project: FolderCreate) -> FolderUpdate:\\n    \\\"\\\"\\\"Map a ``FolderCreate`` (PUT upsert body) onto a ``FolderUpdate`` for the shared update core.\\n\\n    Only fields explicitly set on the incoming body are carried over so the PUT update branch\\n    matches PATCH semantics (unset fields are left untouched). ``flows``/``components`` are not\\n    mapped because ``_apply_project_update`` recomputes them from the project's current DB\\n    contents; ``parent_id`` is not part of ``FolderCreate``.\\n    \\\"\\\"\\\"\\n    # exclude_unset carries only fields explicitly set on the body; include restricts to the three\\n    # fields FolderUpdate shares with FolderCreate (flows/components/parent_id handled per docstring).\\n    data = project.model_dump(include={\\\"name\\\", \\\"description\\\", \\\"auth_settings\\\"}, exclude_unset=True)\\n    return FolderUpdate(**data)\\n\\n\\n@router.patch(\\\"/{project_id}\\\", response_model=FolderRead, status_code=200)\\nasync def update_project(\\n    *,\\n    session: DbSession,\\n    project_id: UUID,\\n    project: FolderUpdate,  # Assuming FolderUpdate is a Pydantic model defining updatable fields\\n    current_user: CurrentActiveUser,\\n    background_tasks: BackgroundTasks,\\n):\\n    try:\\n        existing_project = await authorized_or_owner_scoped(\\n            session,\\n            Folder,\\n            id_column=Folder.id,\\n            resource_id=project_id,\\n            owner_column=Folder.user_id,\\n            owner_id=current_user.id,\\n        )\\n    except Exception as e:\\n        # authorized_or_owner_scoped runs SQL, so the raw str() would carry the statement and its\\n        # bound parameters \u2014 sanitize like the rest of this module.\\n        raise HTTPException(status_code=500, detail=sanitize_database_error(e, PROJECT_UPDATE_FAILED)) from e\\n\\n    if not existing_project:\\n        raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n    try:\\n        await ensure_project_permission(\\n            current_user,\\n            ProjectAction.WRITE,\\n            project_id=project_id,\\n            project_user_id=existing_project.user_id,\\n            workspace_id=existing_project.workspace_id,\\n        )\\n    except HTTPException as exc:\\n        # A caller who can read this project already knows it exists, so the\\n        # 404 mask only hides *why* the edit failed. Match the flow-edit path:\\n        # readable -> 403 with a permission message, unreadable -> 404.\\n        raise await deny_to_404_unless_readable(\\n            exc,\\n            lambda: ensure_project_permission(\\n                current_user,\\n                ProjectAction.READ,\\n                project_id=project_id,\\n                project_user_id=existing_project.user_id,\\n                workspace_id=existing_project.workspace_id,\\n            ),\\n            denied_detail=PROJECT_WRITE_DENIED_DETAIL,\\n            not_found_detail=\\\"Project not found\\\",\\n        ) from exc\\n\\n    try:\\n        return await _apply_project_update(\\n            session=session,\\n            existing_project=existing_project,\\n            project=project,\\n            current_user=current_user,\\n            background_tasks=background_tasks,\\n        )\\n    except HTTPException:\\n        # Re-raise HTTP exceptions (like 409 conflicts) without modification\\n        raise\\n    except Exception as e:\\n        await araise_if_deployment_guard_error_or_skip(\\n            e,\\n            log_message=f\\\"op=update_project project_id={project_id}\\\",\\n        )\\n        # Same mapping as the PUT upsert so both verbs answer a constraint backstop identically:\\n        # 409 for a unique violation that slipped past the pre-check, sanitized 500 otherwise.\\n        raise _handle_unique_constraint_error(e, status_code=status.HTTP_409_CONFLICT) from e\\n\\n\\n@router.put(\\n    \\\"/{project_id}\\\",\\n    response_model=FolderRead,\\n    # The handler returns 201 on create and 200 on update, so the 201 needs declaring for the\\n    # schema to be accurate for generated clients (FastAPI infers only the 200 default).\\n    responses={status.HTTP_201_CREATED: {\\\"model\\\": FolderRead, \\\"description\\\": \\\"Project created.\\\"}},\\n)\\nasync def upsert_project(\\n    *,\\n    session: DbSession,\\n    project_id: UUID,\\n    project: FolderCreate,\\n    current_user: CurrentActiveUser,\\n    background_tasks: BackgroundTasks,\\n):\\n    \\\"\\\"\\\"Create or update a project with a specific ID (upsert).\\n\\n    Returns 201 for creation, 200 for update. Returns 404 if owned by another user (avoids\\n    leaking existence). A name collision fails loud as 409 on both the create and update paths\\n    (unlike POST, which auto-renames).\\n\\n    ``workspace_id`` is out of scope: ``FolderCreate`` cannot express it, so a synced project\\n    inherits ``NULL`` exactly like one created via POST. Workspace assignment is not part of the\\n    upsert contract.\\n    \\\"\\\"\\\"\\n    from fastapi.responses import JSONResponse\\n\\n    try:\\n        # Existence check WITHOUT user filter to distinguish ownership vs CREATE.\\n        existing_project = (await session.exec(select(Folder).where(Folder.id == project_id))).first()\\n\\n        if existing_project is not None:\\n            # Block non-owner upsert when cross-user fetch is off (UUID privacy).\\n            from langflow.services.deps import get_authorization_service\\n\\n            authz = get_authorization_service()\\n            can_widen = await authz.supports_cross_user_fetch() and await authz.is_enabled()\\n            if not can_widen and existing_project.user_id != current_user.id:\\n                raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n            try:\\n                await ensure_project_permission(\\n                    current_user,\\n                    ProjectAction.WRITE,\\n                    project_id=project_id,\\n                    project_user_id=existing_project.user_id,\\n                    workspace_id=existing_project.workspace_id,\\n                )\\n            except HTTPException as exc:\\n                raise deny_to_404(exc, detail=\\\"Project not found\\\") from exc\\n\\n            # The update core recomputes membership from the project's current flows, so\\n            # flows_list/components_list on the body cannot be honored here. Fail loud rather\\n            # than silently discarding them (unlike the CREATE branch, which moves them).\\n            if project.flows_list or project.components_list:\\n                raise HTTPException(\\n                    status_code=400,\\n                    detail=(\\n                        \\\"flows_list/components_list are not supported when updating an existing \\\"\\n                        \\\"project; set a flow's project via PUT /api/v1/flows/{flow_id} instead.\\\"\\n                    ),\\n                )\\n\\n            # Reuse the PATCH update core, which raises the 409 on a rename collision itself.\\n            # Map the PUT body onto a FolderUpdate so unset fields are left untouched.\\n            folder_read = await _apply_project_update(\\n                session=session,\\n                existing_project=existing_project,\\n                project=_folder_create_to_update(project),\\n                current_user=current_user,\\n                background_tasks=background_tasks,\\n            )\\n            status_code = 200\\n        else:\\n            # CREATE path - project doesn't exist. Create it at the caller-specified id and fail\\n            # loud (409) on a name collision instead of auto-renaming.\\n            await ensure_project_permission(\\n                current_user, ProjectAction.CREATE, workspace_id=getattr(project, \\\"workspace_id\\\", None)\\n            )\\n            folder_read = await _new_project(\\n                session=session,\\n                project=project,\\n                current_user=current_user,\\n                project_id=project_id,\\n                fail_on_name_conflict=True,\\n            )\\n            status_code = 201\\n\\n        return JSONResponse(status_code=status_code, content=jsonable_encoder(folder_read))\\n\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        await araise_if_deployment_guard_error_or_skip(\\n            e,\\n            log_message=f\\\"op=upsert_project project_id={project_id}\\\",\\n        )\\n        # The shared helper maps a unique violation on either backend (409, with a detail naming\\n        # the constraint that fired) and sanitizes anything else into a 500.\\n        raise _handle_unique_constraint_error(e, status_code=status.HTTP_409_CONFLICT) from e\\n\\n\\n@router.delete(\\\"/{project_id}\\\", status_code=204)\\nasync def delete_project(\\n    *,\\n    session: DbSession,\\n    project_id: UUID,\\n    current_user: CurrentActiveUser,\\n):\\n    async def _load_project() -> Folder | None:\\n        return await authorized_or_owner_scoped(\\n            session,\\n            Folder,\\n            id_column=Folder.id,\\n            resource_id=project_id,\\n            owner_column=Folder.user_id,\\n            owner_id=current_user.id,\\n        )\\n\\n    try:\\n        project = await _load_project()\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=sanitize_database_error(e, PROJECT_READ_FAILED)) from e\\n\\n    if not project:\\n        raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n    try:\\n        await ensure_project_permission(\\n            current_user,\\n            ProjectAction.DELETE,\\n            project_id=project_id,\\n            project_user_id=project.user_id,\\n            workspace_id=project.workspace_id,\\n        )\\n    except HTTPException as exc:\\n        raise await deny_to_404_unless_readable(\\n            exc,\\n            lambda: ensure_project_permission(\\n                current_user,\\n                ProjectAction.READ,\\n                project_id=project_id,\\n                project_user_id=project.user_id,\\n                workspace_id=project.workspace_id,\\n            ),\\n            denied_detail=PROJECT_DELETE_DENIED_DETAIL,\\n            not_found_detail=\\\"Project not found\\\",\\n        ) from exc\\n\\n    # Prevent deletion of projects managed by Langflow. The ownerless Starter\\n    # Project is also a stable authorization boundary for bundled examples.\\n    is_system_starter = project.name == STARTER_FOLDER_NAME and project.user_id is None\\n    if project.name == ASSISTANT_FOLDER_NAME or is_system_starter:\\n        msg = f\\\"Cannot delete the '{project.name}' folder, which contains pre-built flows.\\\"\\n        await logger.adebug(\\\"Cannot delete the '%s' folder, which contains pre-built flows.\\\", project.name)\\n        raise HTTPException(\\n            status_code=403,\\n            detail=msg,\\n        )\\n\\n    # Cascade and deployment guards operate over the project owner's flows \u2014\\n    # a non-owner with a delete share must remove the owner's resources, not\\n    # only their own (which is the empty set for a non-owner).\\n    project_owner_id = project.user_id\\n\\n    def _make_delete_operation(target: Folder):\\n        async def _delete_project_operation() -> None:\\n            flows = (\\n                await session.exec(select(Flow).where(Flow.folder_id == project_id, Flow.user_id == project_owner_id))\\n            ).all()\\n            if len(flows) > 0:\\n                for flow in flows:\\n                    await cascade_delete_flow(session, flow.id)\\n\\n            await check_project_has_deployments(session, project_id=project_id)\\n            await session.delete(target)\\n            # Flush eagerly so guard/constraint errors surface in-request rather than at teardown commit.\\n            await session.flush()\\n\\n        return _delete_project_operation\\n\\n    # LE-2020: a retry runs in a brand new transaction, and the rollback that\\n    # precedes it expires every instance loaded so far. The user and the row are\\n    # therefore re-read with awaits \u2014 a plain attribute read on expired state\\n    # would lazy-load outside the greenlet context and raise MissingGreenlet.\\n    async def _delete_attempt(attempt: int) -> None:\\n        if attempt == 0:\\n            target = project\\n        else:\\n            await session.refresh(current_user)\\n            target = await _load_project()\\n        if target is None:\\n            return\\n        await cleanup_mcp_on_delete(target, project_id, current_user, session)\\n        await retry_project_operation_on_deployment_guard(\\n            db=session,\\n            user_id=project_owner_id,\\n            project_id=project_id,\\n            operation=_make_delete_operation(target),\\n        )\\n\\n    try:\\n        await run_with_lock_retry(_delete_attempt, session=session, description=f\\\"delete_project {project_id}\\\")\\n        return Response(status_code=status.HTTP_204_NO_CONTENT)\\n    except Exception as e:\\n        await araise_if_deployment_guard_error_or_skip(\\n            e,\\n            log_message=f\\\"op=delete_project project_id={project_id}\\\",\\n            remap=remap_flow_guard_for_project_delete,\\n        )\\n        if is_database_lock_error(e):\\n            # Contention that outlived the retry budget is transient, not a\\n            # server fault: 503 + Retry-After lets a client retry correctly.\\n            await logger.awarning(\\\"op=delete_project project_id=%s exhausted lock retries\\\", project_id)\\n            raise HTTPException(\\n                status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n                detail=PROJECT_DELETE_BUSY,\\n                headers={\\\"Retry-After\\\": \\\"1\\\"},\\n            ) from e\\n        await logger.aexception(\\\"op=delete_project project_id=%s failed with %s\\\", project_id, type(e).__name__)\\n        raise HTTPException(status_code=500, detail=sanitize_database_error(e, PROJECT_DELETE_FAILED)) from e\\n\\n\\n@router.get(\\\"/download/{project_id}\\\", status_code=200)\\nasync def download_file(\\n    *,\\n    session: DbSession,\\n    project_id: UUID,\\n    current_user: CurrentActiveUser,\\n):\\n    \\\"\\\"\\\"Download all flows from project as a zip file.\\\"\\\"\\\"\\n    # Fetch the project row first so the authorization call carries the\\n    # owner id (for the owner-override path) and the workspace id (for the\\n    # project-domain resolver). When share-aware fetch is supported, the\\n    # row is loaded by id and ``ensure_project_permission`` decides access;\\n    # otherwise the query stays owner-scoped.\\n    project = await authorized_or_owner_scoped(\\n        session,\\n        Folder,\\n        id_column=Folder.id,\\n        resource_id=project_id,\\n        owner_column=Folder.user_id,\\n        owner_id=current_user.id,\\n    )\\n    if not project:\\n        raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n    await ensure_project_permission(\\n        current_user,\\n        ProjectAction.READ,\\n        project_id=project_id,\\n        project_user_id=project.user_id,\\n        workspace_id=project.workspace_id,\\n    )\\n    return await download_project_flows(\\n        session=session,\\n        project_id=project_id,\\n        current_user=current_user,\\n        project_owner_id=project.user_id,\\n    )\\n\\n\\n@router.post(\\\"/upload/\\\", response_model=list[FlowRead], status_code=201)\\nasync def upload_file(\\n    *,\\n    session: DbSession,\\n    file: Annotated[UploadFile | None, File()] = None,\\n    current_user: CurrentActiveUser,\\n):\\n    \\\"\\\"\\\"Upload flows from a file.\\n\\n    Accepts either a JSON file with project metadata (folder_name, folder_description, flows)\\n    or a ZIP file containing individual flow JSON files (as produced by the download endpoint).\\n    \\\"\\\"\\\"\\n    await ensure_project_permission(current_user, ProjectAction.CREATE)\\n    return await upload_project_flows(session=session, file=file, current_user=current_user)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/projects_files.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"305fa1e53c114785dd7703077e0368699af37e6e71d21b2c4f616d918ceba932\",\"content\":\"\\\"\\\"\\\"File upload and download handlers for projects.\\n\\nExtracted from projects.py to reduce file size and separate file I/O concerns.\\n\\\"\\\"\\\"\\n\\nimport io\\nimport zipfile\\nfrom datetime import datetime, timezone\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nimport orjson\\nfrom fastapi import File, HTTPException, UploadFile\\nfrom fastapi.responses import StreamingResponse\\nfrom lfx.log.logger import logger\\nfrom sqlmodel import select\\n\\nfrom langflow.api.utils import (\\n    CurrentActiveUser,\\n    DbSession,\\n    build_content_disposition,\\n    normalize_code_for_import,\\n    normalize_flow_for_export,\\n    strip_flow_secrets,\\n)\\nfrom langflow.api.utils.zip_utils import extract_flows_from_zip\\nfrom langflow.api.v1.flows import create_flows\\nfrom langflow.api.v1.flows_helpers import _sanitize_flow_filename\\nfrom langflow.api.v1.schemas import FlowListCreate\\nfrom langflow.helpers.flow import generate_unique_flow_name\\nfrom langflow.helpers.folders import generate_unique_folder_name\\nfrom langflow.services.auth.mcp_encryption import encrypt_auth_settings\\nfrom langflow.services.authorization import FlowAction, filter_visible_resources\\nfrom langflow.services.authorization.utils import _resolve_authz_domain\\nfrom langflow.services.database.models.base import orjson_dumps\\nfrom langflow.services.database.models.flow.model import Flow, FlowCreate, FlowRead\\nfrom langflow.services.database.models.folder.model import (\\n    Folder,\\n    FolderCreate,\\n)\\nfrom langflow.services.deps import get_settings_service\\n\\n\\nasync def download_project_flows(\\n    *,\\n    session: DbSession,\\n    project_id: UUID,\\n    current_user: CurrentActiveUser,\\n    project_owner_id: UUID | None = None,\\n) -> StreamingResponse:\\n    \\\"\\\"\\\"Download all flows from project as a zip file.\\\"\\\"\\\"\\n    try:\\n        owner_id = project_owner_id or current_user.id\\n        query = select(Folder).where(Folder.id == project_id, Folder.user_id == owner_id)\\n        result = await session.exec(query)\\n        project = result.first()\\n\\n        if not project:\\n            raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n        flows_query = select(Flow).where(Flow.folder_id == project_id, Flow.user_id == owner_id)\\n        flows_result = await session.exec(flows_query)\\n        visible_flows = await filter_visible_resources(\\n            current_user,\\n            resource_type=\\\"flow\\\",\\n            candidates=list(flows_result.all()),\\n            domain_extractor=lambda flow: _resolve_authz_domain(flow.workspace_id, flow.folder_id),\\n            owner_extractor=lambda flow: flow.user_id,\\n            act=FlowAction.READ,\\n        )\\n        flows = [FlowRead.model_validate(flow, from_attributes=True) for flow in visible_flows]\\n\\n        if not flows:\\n            raise HTTPException(status_code=404, detail=\\\"No flows found in project\\\")\\n\\n        # Strip secret field values then normalise for git-friendly export\\n        # (sorted keys, volatile fields removed, code fields as line arrays).\\n        normalised_flows = [normalize_flow_for_export(strip_flow_secrets(flow.model_dump())) for flow in flows]\\n        zip_stream = io.BytesIO()\\n\\n        with zipfile.ZipFile(zip_stream, \\\"w\\\") as zip_file:\\n            for flow in normalised_flows:\\n                safe_name = _sanitize_flow_filename(str(flow[\\\"name\\\"]), str(flow.get(\\\"id\\\", \\\"flow\\\")))\\n                # Serialise with sorted keys and 2-space indent for stable diffs.\\n                flow_json = orjson_dumps(flow, sort_keys=True)\\n                zip_file.writestr(f\\\"{safe_name}.json\\\", flow_json.encode(\\\"utf-8\\\"))\\n\\n        zip_stream.seek(0)\\n\\n        current_time = datetime.now(tz=timezone.utc).astimezone().strftime(\\\"%Y%m%d_%H%M%S\\\")\\n        filename = f\\\"{current_time}_{project.name}_flows.zip\\\"\\n\\n        return StreamingResponse(\\n            zip_stream,\\n            media_type=\\\"application/x-zip-compressed\\\",\\n            headers={\\\"Content-Disposition\\\": build_content_disposition(filename)},\\n        )\\n\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        if \\\"No result found\\\" in str(e):\\n            raise HTTPException(status_code=404, detail=\\\"Project not found\\\") from e\\n        logger.exception(\\\"Error downloading project flows for project_id=%s\\\", project_id)\\n        raise HTTPException(\\n            status_code=500, detail=\\\"An internal error occurred while downloading project flows.\\\"\\n        ) from e\\n\\n\\nasync def upload_project_flows(\\n    *,\\n    session: DbSession,\\n    file: Annotated[UploadFile | None, File()] = None,\\n    current_user: CurrentActiveUser,\\n) -> list[FlowRead]:\\n    \\\"\\\"\\\"Upload flows from a file.\\n\\n    Accepts either a JSON file with project metadata (folder_name, folder_description, flows)\\n    or a ZIP file containing individual flow JSON files (as produced by the download endpoint).\\n    \\\"\\\"\\\"\\n    if file is None:\\n        raise HTTPException(status_code=400, detail=\\\"No file provided\\\")\\n\\n    contents = await file.read()\\n\\n    if not contents:\\n        raise HTTPException(status_code=400, detail=\\\"The uploaded file is empty\\\")\\n\\n    # Detect ZIP files and extract flow data\\n    if zipfile.is_zipfile(io.BytesIO(contents)):\\n        try:\\n            flows_data = await extract_flows_from_zip(contents)\\n        except ValueError as e:\\n            raise HTTPException(status_code=400, detail=str(e)) from e\\n        if not flows_data:\\n            raise HTTPException(status_code=400, detail=\\\"No valid flow JSON files found in the ZIP\\\")\\n\\n        # Use the uploaded filename (without extension) as the project name\\n        project_name_base = file.filename.rsplit(\\\".\\\", 1)[0] if file.filename else \\\"Imported Project\\\"\\n        project_name_base = project_name_base or \\\"Imported Project\\\"\\n        data: dict = {\\n            \\\"folder_name\\\": project_name_base,\\n            \\\"folder_description\\\": \\\"\\\",\\n            \\\"flows\\\": flows_data,\\n        }\\n    else:\\n        try:\\n            data = orjson.loads(contents)\\n        except orjson.JSONDecodeError as e:\\n            raise HTTPException(status_code=400, detail=f\\\"Invalid JSON file: {e}\\\") from e\\n\\n    if not data:\\n        raise HTTPException(status_code=400, detail=\\\"No flows found in the file\\\")\\n\\n    # Validate that the uploaded JSON has the required structure before accessing keys\\n    if not isinstance(data, dict):\\n        raise HTTPException(\\n            status_code=400,\\n            detail=\\\"Invalid project data: expected a JSON object with 'folder_name' and 'flows' fields\\\",\\n        )\\n\\n    missing_keys = [key for key in (\\\"folder_name\\\", \\\"flows\\\") if key not in data]\\n    if missing_keys:\\n        raise HTTPException(\\n            status_code=400,\\n            detail=f\\\"Missing required field(s): {', '.join(missing_keys)}\\\",\\n        )\\n    project_name = await generate_unique_folder_name(data[\\\"folder_name\\\"], current_user.id, session)\\n\\n    data[\\\"folder_name\\\"] = project_name\\n\\n    project = FolderCreate(name=data[\\\"folder_name\\\"], description=data.get(\\\"folder_description\\\", \\\"\\\"))\\n\\n    new_project = Folder.model_validate(project, from_attributes=True)\\n    new_project.id = None\\n    new_project.user_id = current_user.id\\n\\n    settings_service = get_settings_service()\\n\\n    # If AUTO_LOGIN is false, automatically enable API key authentication\\n    if not settings_service.auth_settings.AUTO_LOGIN and not new_project.auth_settings:\\n        default_auth = {\\\"auth_type\\\": \\\"apikey\\\"}\\n        new_project.auth_settings = encrypt_auth_settings(default_auth)\\n        await logger.adebug(\\n            \\\"Auto-enabled API key authentication for uploaded project %s (%s) due to AUTO_LOGIN=false\\\",\\n            new_project.name,\\n            new_project.id,\\n        )\\n\\n    session.add(new_project)\\n    await session.flush()\\n    await session.refresh(new_project)\\n    del data[\\\"folder_name\\\"]\\n    data.pop(\\\"folder_description\\\", None)\\n\\n    if \\\"flows\\\" in data:\\n        # Normalise code fields: if exported with code-as-lines format, rejoin to\\n        # strings before creating Pydantic models so the DB always stores strings.\\n        flow_list = FlowListCreate(flows=[FlowCreate(**normalize_code_for_import(flow)) for flow in data[\\\"flows\\\"]])\\n    else:\\n        raise HTTPException(status_code=400, detail=\\\"No flows found in the data\\\")\\n    # Generate unique names, tracking names already assigned within this batch\\n    # to avoid collisions when multiple flows would get the same generated name\\n    used_names_in_batch: set[str] = set()\\n    for flow in flow_list.flows:\\n        flow_name = await generate_unique_flow_name(flow.name, current_user.id, session)\\n        # Ensure the name is also unique within the current batch;\\n        # generate suffixed candidates and verify each against DB\\n        base_name = flow_name\\n        n = 1\\n        while flow_name in used_names_in_batch:\\n            candidate = f\\\"{base_name} ({n})\\\"\\n            n += 1\\n            flow_name = await generate_unique_flow_name(candidate, current_user.id, session)\\n        used_names_in_batch.add(flow_name)\\n        flow.name = flow_name\\n        flow.user_id = current_user.id\\n        flow.folder_id = new_project.id\\n        flow.workspace_id = new_project.workspace_id\\n\\n    return await create_flows(session=session, flow_list=flow_list, current_user=current_user)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/projects_mcp_helpers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"51d1b0fe0e786f6d3569f640cc303e02fe82eec92ce85bfedf20abf4b0792bb4\",\"content\":\"\\\"\\\"\\\"MCP server registration and management helpers for projects.\\n\\nExtracted from projects.py to reduce file size and isolate MCP concerns (SO1).\\n\\\"\\\"\\\"\\n\\nfrom typing import Any, cast\\nfrom uuid import UUID\\n\\nfrom fastapi import HTTPException\\nfrom lfx.base.mcp.uvx import mcp_sdk_constraint_args\\nfrom lfx.log.logger import logger\\nfrom lfx.services.mcp_composer.service import MCPComposerService\\n\\nfrom langflow.api.utils.mcp.config_utils import (\\n    mcp_server_config_uses_current_uvx_constraint,\\n    validate_mcp_server_for_project,\\n)\\nfrom langflow.api.v1.mcp_projects import get_project_streamable_http_url\\nfrom langflow.api.v2.mcp import update_server\\nfrom langflow.services.database.models.api_key.crud import create_api_key\\nfrom langflow.services.database.models.api_key.model import ApiKeyCreate\\nfrom langflow.services.deps import get_service, get_settings_service, get_storage_service\\nfrom langflow.services.schema import ServiceType\\n\\n\\ndef _server_config_uses_streamable_http(args: list[Any], streamable_http_url: str) -> bool:\\n    \\\"\\\"\\\"Return whether the server args target this project's Streamable HTTP endpoint.\\\"\\\"\\\"\\n    string_args = [arg for arg in args if isinstance(arg, str)]\\n    return (\\n        \\\"mcp-proxy\\\" in string_args\\n        and \\\"--transport\\\" in string_args\\n        and \\\"streamablehttp\\\" in string_args\\n        and streamable_http_url in string_args\\n    )\\n\\n\\ndef _server_config_has_project_api_key(args: list[Any]) -> bool:\\n    \\\"\\\"\\\"Return whether the server args include the generated Langflow API key header.\\\"\\\"\\\"\\n    return any(\\n        arg == \\\"--headers\\\" and index + 2 < len(args) and args[index + 1] == \\\"x-api-key\\\"\\n        for index, arg in enumerate(args)\\n    )\\n\\n\\ndef _server_config_matches_project_auth(\\n    existing_config: dict[str, Any] | None,\\n    auth_type: str,\\n    streamable_http_url: str,\\n) -> bool:\\n    \\\"\\\"\\\"Check whether the stored MCP server config already matches the project's auth mode.\\\"\\\"\\\"\\n    if not existing_config:\\n        return False\\n\\n    args = existing_config.get(\\\"args\\\")\\n    if (\\n        not isinstance(args, list)\\n        or not mcp_server_config_uses_current_uvx_constraint(existing_config, \\\"mcp-proxy\\\")\\n        or not _server_config_uses_streamable_http(args, streamable_http_url)\\n    ):\\n        return False\\n\\n    has_project_api_key = _server_config_has_project_api_key(args)\\n    if auth_type == \\\"apikey\\\":\\n        return has_project_api_key\\n    if auth_type == \\\"none\\\":\\n        return not has_project_api_key\\n    return False\\n\\n\\nasync def register_mcp_servers_for_project(\\n    project,\\n    default_auth: dict,\\n    current_user,\\n    session,\\n    *,\\n    raise_on_error: bool = False,\\n    owns_transaction: bool = True,\\n) -> bool:\\n    \\\"\\\"\\\"Register MCP servers for a newly created project.\\n\\n    This handles the full MCP auto-registration flow: building the transport URL,\\n    creating API keys if needed, validating conflicts, and calling update_server.\\n\\n    Pass ``owns_transaction=False`` when the caller already owns the transaction (the\\n    startup reconciliation runs inside ``session.begin_nested()``). That keeps the API\\n    key created below in the same unit of work as the server write, so a failure rolls\\n    both back instead of leaving an unreferenced credential behind.\\n\\n    Returns:\\n        True when the server config was created or updated, otherwise False.\\n\\n    Raises:\\n        HTTPException: On server name conflicts.\\n    \\\"\\\"\\\"\\n    try:\\n        streamable_http_url = await get_project_streamable_http_url(project.id)\\n        auth_type = default_auth.get(\\\"auth_type\\\", \\\"none\\\")\\n\\n        validation_result = await validate_mcp_server_for_project(\\n            project.id,\\n            project.name,\\n            current_user,\\n            session,\\n            get_storage_service(),\\n            get_settings_service(),\\n            operation=\\\"create\\\",\\n        )\\n\\n        if validation_result.has_conflict:\\n            await logger.aerror(validation_result.conflict_message)\\n            raise HTTPException(\\n                status_code=409,\\n                detail=validation_result.conflict_message,\\n            )\\n\\n        if validation_result.should_skip and _server_config_matches_project_auth(\\n            validation_result.existing_config,\\n            auth_type,\\n            streamable_http_url,\\n        ):\\n            await logger.adebug(\\n                \\\"MCP server '%s' already matches auth %s for project %s, skipping\\\",\\n                validation_result.server_name,\\n                auth_type,\\n                project.id,\\n            )\\n            return False\\n\\n        if auth_type == \\\"apikey\\\":\\n            api_key_name = f\\\"MCP Project {project.name} - default\\\"\\n            unmasked_api_key = await create_api_key(session, ApiKeyCreate(name=api_key_name), current_user.id)\\n            command = \\\"uvx\\\"\\n            args = [\\n                *mcp_sdk_constraint_args(),\\n                \\\"mcp-proxy\\\",\\n                \\\"--transport\\\",\\n                \\\"streamablehttp\\\",\\n                \\\"--headers\\\",\\n                \\\"x-api-key\\\",\\n                unmasked_api_key.api_key,\\n                streamable_http_url,\\n            ]\\n        elif auth_type == \\\"oauth\\\":\\n            msg = \\\"OAuth authentication is not yet implemented for MCP server creation during project creation.\\\"\\n            await logger.awarning(msg)\\n            return False\\n        else:\\n            command = \\\"uvx\\\"\\n            args = [\\n                *mcp_sdk_constraint_args(),\\n                \\\"mcp-proxy\\\",\\n                \\\"--transport\\\",\\n                \\\"streamablehttp\\\",\\n                streamable_http_url,\\n            ]\\n\\n        server_config = {\\\"command\\\": command, \\\"args\\\": args}\\n\\n        if validation_result.should_skip:\\n            await logger.adebug(\\n                \\\"MCP server '%s' exists for project %s but does not match auth %s, updating\\\",\\n                validation_result.server_name,\\n                project.id,\\n                auth_type,\\n            )\\n\\n        server_name = validation_result.server_name\\n\\n        await update_server(\\n            server_name,\\n            server_config,\\n            current_user,\\n            session,\\n            get_storage_service(),\\n            get_settings_service(),\\n            owns_transaction=owns_transaction,\\n        )\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        await logger.aexception(\\\"Failed to auto-register MCP server for project %s: %s\\\", project.id, e)\\n        if raise_on_error:\\n            raise\\n        return False\\n    else:\\n        return True\\n\\n\\nasync def reconcile_mcp_server_for_auth_update(\\n    project,\\n    new_auth_type: str | None,\\n    current_user,\\n    session,\\n) -> bool:\\n    \\\"\\\"\\\"Sync the MCP server config for a project whose auth settings just changed.\\n\\n    OAuth reconciliation is driven separately by MCP Composer, so this helper only\\n    touches apikey/none modes. Returns True when the server config was updated.\\n    \\\"\\\"\\\"\\n    if new_auth_type not in {\\\"apikey\\\", \\\"none\\\"}:\\n        return False\\n\\n    if not get_settings_service().settings.add_projects_to_mcp_servers:\\n        return False\\n\\n    return await register_mcp_servers_for_project(\\n        project,\\n        {\\\"auth_type\\\": new_auth_type},\\n        current_user,\\n        session,\\n    )\\n\\n\\nasync def handle_mcp_server_rename(\\n    existing_project,\\n    old_project_name: str,\\n    new_project_name: str,\\n    current_user,\\n    session,\\n) -> None:\\n    \\\"\\\"\\\"Handle MCP server name update when a project is renamed.\\n\\n    Validates old and new server names, checks for conflicts, and performs\\n    the rename (delete old + create new) if needed.\\n\\n    Raises HTTPException on name conflicts.\\n    \\\"\\\"\\\"\\n    try:\\n        old_validation = await validate_mcp_server_for_project(\\n            existing_project.id,\\n            old_project_name,\\n            current_user,\\n            session,\\n            get_storage_service(),\\n            get_settings_service(),\\n            operation=\\\"update\\\",\\n        )\\n\\n        new_validation = await validate_mcp_server_for_project(\\n            existing_project.id,\\n            new_project_name,\\n            current_user,\\n            session,\\n            get_storage_service(),\\n            get_settings_service(),\\n            operation=\\\"update\\\",\\n        )\\n\\n        if old_validation.server_name != new_validation.server_name:\\n            if new_validation.has_conflict:\\n                await logger.aerror(new_validation.conflict_message)\\n                raise HTTPException(\\n                    status_code=409,\\n                    detail=new_validation.conflict_message,\\n                )\\n\\n            if old_validation.server_exists and old_validation.project_id_matches:\\n                await update_server(\\n                    old_validation.server_name,\\n                    {},\\n                    current_user,\\n                    session,\\n                    get_storage_service(),\\n                    get_settings_service(),\\n                    delete=True,\\n                )\\n\\n                await update_server(\\n                    new_validation.server_name,\\n                    old_validation.existing_config or {},\\n                    current_user,\\n                    session,\\n                    get_storage_service(),\\n                    get_settings_service(),\\n                )\\n\\n                await logger.adebug(\\n                    \\\"Updated MCP server name from %s to %s\\\",\\n                    old_validation.server_name,\\n                    new_validation.server_name,\\n                )\\n            else:\\n                await logger.adebug(\\n                    \\\"Old MCP server '%s' not found for this project, skipping rename\\\",\\n                    old_validation.server_name,\\n                )\\n\\n    except HTTPException:\\n        raise\\n    except Exception as e:  # noqa: BLE001\\n        await logger.awarning(\\\"Failed to handle MCP server name update for project rename: %s\\\", e)\\n\\n\\nasync def cleanup_mcp_on_delete(\\n    project,\\n    project_id: UUID,\\n    current_user,\\n    session,\\n) -> None:\\n    \\\"\\\"\\\"Clean up MCP resources when a project is deleted.\\n\\n    Stops the MCP Composer if the project uses OAuth, and removes the\\n    corresponding MCP server entry if auto-add was enabled.\\n    \\\"\\\"\\\"\\n    # Stop MCP Composer if project used OAuth\\n    if project.auth_settings and project.auth_settings.get(\\\"auth_type\\\") == \\\"oauth\\\":\\n        try:\\n            mcp_composer_service: MCPComposerService = cast(\\n                MCPComposerService, get_service(ServiceType.MCP_COMPOSER_SERVICE)\\n            )\\n            await mcp_composer_service.stop_project_composer(str(project_id))\\n            await logger.adebug(\\\"Stopped MCP Composer for deleted OAuth project %s (%s)\\\", project.name, project_id)\\n        except Exception as e:  # noqa: BLE001\\n            await logger.aerror(\\\"Failed to stop MCP Composer for deleted project %s: %s\\\", project_id, e)\\n\\n    # Delete corresponding MCP server if auto-add was enabled\\n    if get_settings_service().settings.add_projects_to_mcp_servers:\\n        try:\\n            validation_result = await validate_mcp_server_for_project(\\n                project_id,\\n                project.name,\\n                current_user,\\n                session,\\n                get_storage_service(),\\n                get_settings_service(),\\n                operation=\\\"delete\\\",\\n            )\\n\\n            if validation_result.server_exists and validation_result.project_id_matches:\\n                await update_server(\\n                    validation_result.server_name,\\n                    {},\\n                    current_user,\\n                    session,\\n                    get_storage_service(),\\n                    get_settings_service(),\\n                    delete=True,\\n                )\\n                await logger.adebug(\\n                    \\\"Deleted MCP server %s for deleted project %s (%s)\\\",\\n                    validation_result.server_name,\\n                    project.name,\\n                    project_id,\\n                )\\n            elif validation_result.server_exists and not validation_result.project_id_matches:\\n                await logger.adebug(\\n                    \\\"MCP server '%s' exists but belongs to different project, skipping deletion\\\",\\n                    validation_result.server_name,\\n                )\\n            else:\\n                await logger.adebug(\\\"No MCP server found for deleted project %s (%s)\\\", project.name, project_id)\\n\\n        except Exception as e:  # noqa: BLE001\\n            await logger.awarning(\\\"Failed to handle MCP server cleanup for deleted project %s: %s\\\", project_id, e)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/run_validation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d53db73ce858ef3d462d122e0e63b2cc040440e39ca3d33ddfb890042c642a5e\",\"content\":\"\\\"\\\"\\\"Guards for the v1 run endpoints \u2014 reject flows the synchronous run path cannot execute.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom fastapi import HTTPException, status\\n\\n_HUMAN_INPUT_TYPE = \\\"HumanInput\\\"\\n\\nHITL_UNSUPPORTED_DETAIL = (\\n    \\\"This flow uses Human-in-the-Loop (a Human Input node or a tool that requires approval), which the \\\"\\n    \\\"v1 run API cannot execute because it cannot pause and resume. Run it with the v2 workflows API instead: \\\"\\n    \\\"POST /api/v2/workflows with mode='background', then resume via POST /api/v2/workflows/{job_id}/resume.\\\"\\n)\\n\\n\\ndef flow_requires_hitl(graph_data: dict) -> bool:\\n    \\\"\\\"\\\"True if the flow pauses for a human decision.\\n\\n    Two HITL shapes: a Human Input node wired to a downstream consumer (an isolated node is\\n    skipped at runtime, so it is not blocking), or an approval-gated agent tool (a\\n    ``tools_metadata`` row carrying a non-empty ``approval_actions``).\\n    \\\"\\\"\\\"\\n    nodes = graph_data.get(\\\"nodes\\\") or []\\n    edges = graph_data.get(\\\"edges\\\") or []\\n    edge_sources = {edge.get(\\\"source\\\") for edge in edges}\\n    for node in nodes:\\n        node_data = node.get(\\\"data\\\") or {}\\n        node_id = node_data.get(\\\"id\\\") or node.get(\\\"id\\\")\\n        if node_data.get(\\\"type\\\") == _HUMAN_INPUT_TYPE and node_id in edge_sources:\\n            return True\\n        template = (node_data.get(\\\"node\\\") or {}).get(\\\"template\\\") or {}\\n        rows = (template.get(\\\"tools_metadata\\\") or {}).get(\\\"value\\\")\\n        if isinstance(rows, list) and any(isinstance(row, dict) and row.get(\\\"approval_actions\\\") for row in rows):\\n            return True\\n    return False\\n\\n\\ndef raise_if_hitl_unsupported(graph_data: dict) -> None:\\n    \\\"\\\"\\\"Reject a v1 run of a HITL flow with a clear pointer to the v2 workflows API.\\\"\\\"\\\"\\n    if flow_requires_hitl(graph_data):\\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=HITL_UNSUPPORTED_DETAIL)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/schemas/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c81696da7d18c00abee1d397a545ae0f2f0291c583c9388372dbdd03b53b20f3\",\"content\":\"from datetime import datetime, timezone\\nfrom enum import Enum\\nfrom typing import Any, Literal\\nfrom uuid import UUID\\n\\nfrom lfx.graph.schema import RunOutputs\\nfrom lfx.services.settings.base import Settings\\nfrom lfx.services.settings.feature_flags import FEATURE_FLAGS, FeatureFlags\\nfrom pydantic import (\\n    BaseModel,\\n    ConfigDict,\\n    Field,\\n    SecretStr,\\n    field_serializer,\\n    field_validator,\\n    model_serializer,\\n)\\n\\nfrom langflow.schema.dotdict import dotdict\\nfrom langflow.schema.graph import Tweaks\\nfrom langflow.schema.schema import InputType, OutputType, OutputValue\\nfrom langflow.serialization.serialization import get_max_items_length, get_max_text_length, serialize\\nfrom langflow.services.database.models.api_key.model import ApiKeyRead\\nfrom langflow.services.database.models.base import orjson_dumps\\nfrom langflow.services.database.models.flow.model import FlowCreate, FlowRead\\nfrom langflow.services.database.models.user.model import UserRead\\nfrom langflow.services.tracing.schema import Log\\n\\n\\nclass BuildStatus(Enum):\\n    \\\"\\\"\\\"Status of the build.\\\"\\\"\\\"\\n\\n    SUCCESS = \\\"success\\\"\\n    FAILURE = \\\"failure\\\"\\n    STARTED = \\\"started\\\"\\n    IN_PROGRESS = \\\"in_progress\\\"\\n\\n\\nclass TweaksRequest(BaseModel):\\n    tweaks: dict[str, dict[str, Any]] | None = Field(default_factory=dict)\\n\\n\\nclass UpdateTemplateRequest(BaseModel):\\n    template: dict\\n\\n\\nclass TaskResponse(BaseModel):\\n    \\\"\\\"\\\"Task response schema.\\\"\\\"\\\"\\n\\n    id: str | None = Field(None)\\n    href: str | None = Field(None)\\n\\n\\nclass ProcessResponse(BaseModel):\\n    \\\"\\\"\\\"Process response schema.\\\"\\\"\\\"\\n\\n    result: Any\\n    status: str | None = None\\n    task: TaskResponse | None = None\\n    session_id: str | None = None\\n    backend: str | None = None\\n\\n\\nclass RunResponse(BaseModel):\\n    \\\"\\\"\\\"Run response schema.\\\"\\\"\\\"\\n\\n    outputs: list[RunOutputs] | None = []\\n    session_id: str | None = None\\n\\n    @model_serializer(mode=\\\"plain\\\")\\n    def serialize(self):\\n        # Serialize all the outputs if they are base models\\n        serialized = {\\\"session_id\\\": self.session_id, \\\"outputs\\\": []}\\n        if self.outputs:\\n            serialized_outputs = []\\n            for output in self.outputs:\\n                if isinstance(output, BaseModel) and not isinstance(output, RunOutputs):\\n                    serialized_outputs.append(output.model_dump(exclude_none=True))\\n                else:\\n                    serialized_outputs.append(output)\\n            serialized[\\\"outputs\\\"] = serialized_outputs\\n        return serialized\\n\\n\\nclass PreloadResponse(BaseModel):\\n    \\\"\\\"\\\"Preload response schema.\\\"\\\"\\\"\\n\\n    session_id: str | None = None\\n    is_clear: bool | None = None\\n\\n\\nclass TaskStatusResponse(BaseModel):\\n    \\\"\\\"\\\"Task status response schema.\\\"\\\"\\\"\\n\\n    status: str\\n    result: Any | None = None\\n\\n\\nclass ChatMessage(BaseModel):\\n    \\\"\\\"\\\"Chat message schema.\\\"\\\"\\\"\\n\\n    is_bot: bool = False\\n    message: str | None | dict = None\\n    chat_key: str | None = Field(None, serialization_alias=\\\"chatKey\\\")\\n    type: str = \\\"human\\\"\\n\\n\\nclass ChatResponse(ChatMessage):\\n    \\\"\\\"\\\"Chat response schema.\\\"\\\"\\\"\\n\\n    intermediate_steps: str\\n\\n    type: str\\n    is_bot: bool = True\\n    files: list = []\\n\\n    @field_validator(\\\"type\\\")\\n    @classmethod\\n    def validate_message_type(cls, v):\\n        if v not in {\\\"start\\\", \\\"stream\\\", \\\"end\\\", \\\"error\\\", \\\"info\\\", \\\"file\\\"}:\\n            msg = \\\"type must be start, stream, end, error, info, or file\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n\\nclass PromptResponse(ChatMessage):\\n    \\\"\\\"\\\"Prompt response schema.\\\"\\\"\\\"\\n\\n    prompt: str\\n    type: str = \\\"prompt\\\"\\n    is_bot: bool = True\\n\\n\\nclass FileResponse(ChatMessage):\\n    \\\"\\\"\\\"File response schema.\\\"\\\"\\\"\\n\\n    data: Any = None\\n    data_type: str\\n    type: str = \\\"file\\\"\\n    is_bot: bool = True\\n\\n    @field_validator(\\\"data_type\\\")\\n    @classmethod\\n    def validate_data_type(cls, v):\\n        if v not in {\\\"image\\\", \\\"csv\\\"}:\\n            msg = \\\"data_type must be image or csv\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n\\nclass FlowListCreate(BaseModel):\\n    flows: list[FlowCreate]\\n\\n\\nclass FlowListIds(BaseModel):\\n    flow_ids: list[str]\\n\\n\\nclass FlowListRead(BaseModel):\\n    flows: list[FlowRead]\\n\\n\\nclass FlowListReadWithFolderName(BaseModel):\\n    flows: list[FlowRead]\\n    folder_name: str\\n    description: str\\n\\n\\nclass InitResponse(BaseModel):\\n    flow_id: str = Field(serialization_alias=\\\"flowId\\\")\\n\\n\\nclass BuiltResponse(BaseModel):\\n    built: bool\\n\\n\\nclass UploadFileResponse(BaseModel):\\n    \\\"\\\"\\\"Upload file response schema.\\\"\\\"\\\"\\n\\n    flow_id: str = Field(serialization_alias=\\\"flowId\\\")\\n    file_path: str\\n\\n\\nclass StreamData(BaseModel):\\n    event: str\\n    data: dict\\n\\n    def __str__(self) -> str:\\n        return f\\\"event: {self.event}\\\\ndata: {orjson_dumps(self.data, indent_2=False)}\\\\n\\\\n\\\"\\n\\n\\nclass CustomComponentRequest(BaseModel):\\n    model_config = ConfigDict(arbitrary_types_allowed=True)\\n    code: str\\n    frontend_node: dict | None = None\\n\\n\\nclass CustomComponentResponse(BaseModel):\\n    data: dict\\n    type: str\\n\\n\\nclass UpdateCustomComponentRequest(CustomComponentRequest):\\n    field: str\\n    field_value: str | int | float | bool | dict | list | None = None\\n    template: dict\\n    tool_mode: bool = False\\n\\n    def get_template(self):\\n        return dotdict(self.template)\\n\\n\\nclass CustomComponentResponseError(BaseModel):\\n    detail: str\\n    traceback: str\\n\\n\\nclass ComponentListCreate(BaseModel):\\n    flows: list[FlowCreate]\\n\\n\\nclass ComponentListRead(BaseModel):\\n    flows: list[FlowRead]\\n\\n\\nclass UsersResponse(BaseModel):\\n    total_count: int\\n    users: list[UserRead]\\n\\n\\nclass PasswordResetRequest(BaseModel):\\n    current_password: str\\n    password: str\\n\\n\\nclass ApiKeyResponse(BaseModel):\\n    id: str\\n    api_key: str\\n    name: str\\n    created_at: str\\n    last_used_at: str\\n\\n\\nclass ApiKeysResponse(BaseModel):\\n    total_count: int\\n    user_id: UUID\\n    api_keys: list[ApiKeyRead]\\n\\n\\nclass CreateApiKeyRequest(BaseModel):\\n    name: str\\n\\n\\nclass Token(BaseModel):\\n    access_token: str\\n    refresh_token: str\\n    token_type: str\\n\\n\\nclass ApiKeyCreateRequest(BaseModel):\\n    api_key: str\\n\\n\\nclass VerticesOrderResponse(BaseModel):\\n    ids: list[str]\\n    run_id: UUID\\n    vertices_to_run: list[str]\\n\\n\\nclass ResultDataResponse(BaseModel):\\n    results: Any | None = Field(default_factory=dict)\\n    outputs: dict[str, OutputValue] = Field(default_factory=dict)\\n    logs: dict[str, list[Log]] = Field(default_factory=dict)\\n    message: Any | None = Field(default_factory=dict)\\n    artifacts: Any | None = Field(default_factory=dict)\\n    timedelta: float | None = None\\n    duration: str | None = None\\n    used_frozen_result: bool | None = False\\n    token_usage: dict | None = None\\n\\n    @field_validator(\\\"token_usage\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_token_usage(cls, v):\\n        if v is not None and not isinstance(v, dict) and hasattr(v, \\\"model_dump\\\"):\\n            return v.model_dump()\\n        return v\\n\\n    @field_serializer(\\\"results\\\")\\n    @classmethod\\n    def serialize_results(cls, v):\\n        \\\"\\\"\\\"Serializes the results value with custom handling for special types and applies truncation limits.\\n\\n        Returns:\\n            The serialized representation of the input value, truncated according to configured\\n            maximum text length and item count.\\n        \\\"\\\"\\\"\\n        return serialize(v, max_length=get_max_text_length(), max_items=get_max_items_length())\\n\\n    @model_serializer(mode=\\\"plain\\\")\\n    def serialize_model(self) -> dict:\\n        \\\"\\\"\\\"Serialize the entire model into a dictionary with truncation applied to large fields.\\n\\n        Returns:\\n            dict: A dictionary representation of the model with serialized and truncated\\n            results, outputs, logs, message, and artifacts.\\n        \\\"\\\"\\\"\\n        return {\\n            \\\"results\\\": self.serialize_results(self.results),\\n            \\\"outputs\\\": serialize(self.outputs, max_length=get_max_text_length(), max_items=get_max_items_length()),\\n            \\\"logs\\\": serialize(self.logs, max_length=get_max_text_length(), max_items=get_max_items_length()),\\n            \\\"message\\\": serialize(self.message, max_length=get_max_text_length(), max_items=get_max_items_length()),\\n            \\\"artifacts\\\": serialize(self.artifacts, max_length=get_max_text_length(), max_items=get_max_items_length()),\\n            \\\"timedelta\\\": self.timedelta,\\n            \\\"duration\\\": self.duration,\\n            \\\"used_frozen_result\\\": self.used_frozen_result,\\n            \\\"token_usage\\\": self.token_usage,\\n        }\\n\\n\\nclass VertexBuildResponse(BaseModel):\\n    id: str | None = None\\n    inactivated_vertices: list[str] | None = None\\n    next_vertices_ids: list[str] | None = None\\n    top_level_vertices: list[str] | None = None\\n    valid: bool\\n    params: Any | None = Field(default_factory=dict)\\n    \\\"\\\"\\\"JSON string of the params.\\\"\\\"\\\"\\n    data: ResultDataResponse\\n    \\\"\\\"\\\"Mapping of vertex ids to result dict containing the param name and result value.\\\"\\\"\\\"\\n    timestamp: datetime | None = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    \\\"\\\"\\\"Timestamp of the build.\\\"\\\"\\\"\\n\\n    @field_serializer(\\\"data\\\")\\n    def serialize_data(self, data: ResultDataResponse) -> dict:\\n        \\\"\\\"\\\"Serialize a ResultDataResponse object into a dictionary with enforced maximum text and item lengths.\\n\\n        Parameters:\\n            data (ResultDataResponse): The data object to serialize.\\n\\n        Returns:\\n            dict: The serialized representation of the data with truncation applied.\\n        \\\"\\\"\\\"\\n        # return serialize(data, max_length=get_max_text_length())  TODO: Safe?\\n        return serialize(data, max_length=get_max_text_length(), max_items=get_max_items_length())\\n\\n\\nclass VerticesBuiltResponse(BaseModel):\\n    vertices: list[VertexBuildResponse]\\n\\n\\nclass SimplifiedAPIRequest(BaseModel):\\n    input_value: str | None = Field(default=None, description=\\\"The input value\\\")\\n    input_type: InputType | None = Field(default=\\\"chat\\\", description=\\\"The input type\\\")\\n    output_type: OutputType | None = Field(default=\\\"chat\\\", description=\\\"The output type\\\")\\n    output_component: str | None = Field(\\n        default=\\\"\\\",\\n        description=\\\"If there are multiple output components, you can specify the component to get the output from.\\\",\\n    )\\n    tweaks: Tweaks | None = Field(default=None, description=\\\"The tweaks\\\")\\n    session_id: str | None = Field(default=None, description=\\\"The session id\\\")\\n    user_id: str | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Optional end-user identifier forwarded to tracing providers (e.g. Langfuse) \\\"\\n            \\\"as the trace's user_id. Does not affect authentication or authorization \u2014 the \\\"\\n            \\\"API key owner remains the effective Langflow user.\\\"\\n        ),\\n    )\\n\\n\\n# Mirrors the frontend's ReactFlowJsonObject shape: { nodes, edges, viewport }.\\nclass FlowDataRequest(BaseModel):\\n    nodes: list[dict]\\n    edges: list[dict]\\n    viewport: dict | None = None\\n\\n\\nclass BaseConfigResponse(BaseModel):\\n    \\\"\\\"\\\"Base configuration shared by both public and authenticated responses.\\n\\n    Contains fields that are safe to expose publicly and needed by the frontend\\n    for basic functionality (file uploads, event delivery, voice mode, timeouts).\\n    \\\"\\\"\\\"\\n\\n    feature_flags: FeatureFlags\\n    max_file_size_upload: int\\n    event_delivery: Literal[\\\"polling\\\", \\\"streaming\\\", \\\"direct\\\"]\\n    voice_mode_available: bool\\n    frontend_timeout: int\\n    mcp_base_url: str\\n    # Runtime mirror of LANGFLOW_ENABLE_EXTENSION_RELOAD: the packaged frontend is built\\n    # before an operator can opt in, so the palette Reload button consults this field too.\\n    enable_extension_reload: bool\\n    # Mirrors ``LANGFLOW_AUTHZ_ENABLED``. EE/custom frontends gate the Access\\n    # Control settings entry on this flag; OSS UI ignores it until wired.\\n    authz_enabled: bool = False\\n    # Signals that at least one component or template is governed without\\n    # exposing the policy contents through the public config response.\\n    catalog_governance_enabled: bool = False\\n    # The editor uses the same policy as the build path when deciding whether\\n    # drifted built-in components must block a run.\\n    substitute_outdated_component_code: bool\\n\\n\\nclass PublicConfigResponse(BaseConfigResponse):\\n    \\\"\\\"\\\"Configuration response for public/unauthenticated endpoints like the public playground.\\n\\n    Contains only the configuration values needed for public features, without sensitive data.\\n    The 'type' field is a discriminator to distinguish from full ConfigResponse.\\n    \\\"\\\"\\\"\\n\\n    type: Literal[\\\"public\\\"] = \\\"public\\\"\\n    allow_custom_components: bool\\n\\n    @classmethod\\n    def from_settings(\\n        cls,\\n        settings: Settings,\\n        auth_settings,\\n        *,\\n        catalog_governance_enabled: bool = False,\\n    ) -> \\\"PublicConfigResponse\\\":\\n        \\\"\\\"\\\"Create a PublicConfigResponse instance using values from a Settings object.\\n\\n        Parameters:\\n            settings (Settings): The Settings object containing configuration values.\\n            auth_settings: Auth settings (for ``authz_enabled``).\\n            catalog_governance_enabled: Whether any catalog policy currently restricts resources.\\n\\n        Returns:\\n            PublicConfigResponse: An instance populated with public-safe configuration values.\\n        \\\"\\\"\\\"\\n        return cls(\\n            feature_flags=FEATURE_FLAGS,\\n            max_file_size_upload=settings.max_file_size_upload,\\n            event_delivery=settings.event_delivery,\\n            voice_mode_available=settings.voice_mode_available,\\n            frontend_timeout=settings.frontend_timeout,\\n            mcp_base_url=settings.mcp_base_url,\\n            enable_extension_reload=settings.enable_extension_reload,\\n            allow_custom_components=settings.allow_custom_components,\\n            substitute_outdated_component_code=settings.substitute_outdated_component_code,\\n            authz_enabled=bool(getattr(auth_settings, \\\"AUTHZ_ENABLED\\\", False)),\\n            catalog_governance_enabled=catalog_governance_enabled,\\n        )\\n\\n\\nclass ConfigResponse(BaseConfigResponse):\\n    \\\"\\\"\\\"Full configuration response for authenticated users.\\n\\n    The 'type' field is a discriminator to distinguish from PublicConfigResponse.\\n    \\\"\\\"\\\"\\n\\n    type: Literal[\\\"full\\\"] = \\\"full\\\"\\n    serialization_max_items_length: int\\n    serialization_max_text_length: int\\n    auto_saving: bool\\n    auto_saving_interval: int\\n    health_check_max_retries: int\\n    webhook_polling_interval: int\\n    public_flow_cleanup_interval: int\\n    public_flow_expiration: int\\n    webhook_auth_enable: bool\\n    default_folder_name: str\\n    hide_getting_started_progress: bool\\n    allow_custom_components: bool\\n    # Embedded mode feature flags\\n    embedded_mode: bool\\n    hide_logout_button: bool\\n    hide_new_project_button: bool\\n    hide_new_flow_button: bool\\n    hide_starter_projects: bool\\n    mcp_servers_locked: bool\\n    custom_component_admin_only: bool\\n    # Whether the server serves the A2A surface at all (LANGFLOW_A2A_ENABLED, default off). The\\n    # publish-as-agent UI reads this to explain, rather than 404, when A2A is disabled server-side.\\n    a2a_enabled: bool = False\\n    # Mirrors LANGFLOW_AGENTIC_EXPERIENCE (default on) so the Assistant panel\\n    # can explain, rather than 404, when the experience is disabled server-side.\\n    agentic_experience: bool = True\\n    # Mirrors LANGFLOW_ASSISTANT_MAX_MESSAGE_LENGTH so the Assistant composer enforces the same\\n    # cap the API does. A UI-only constant drifted below the API's and silently truncated long\\n    # prompts before they were ever sent.\\n    assistant_max_message_length: int = 2000\\n    # True when local Chroma may back a knowledge base or memory base \u2014 i.e. on\\n    # the dev profile. The production profile refuses it (vectors on the serving\\n    # box's own disk don't survive a restart and can't be shared across\\n    # replicas), so the vector-store picker hides the option rather than offering\\n    # a choice the create endpoint always rejects with 422.\\n    local_vector_store_available: bool = True\\n    # The component types an administrator blocked, for authenticated callers\\n    # only. ``catalog_governance_enabled`` says a policy exists somewhere; it\\n    # cannot say which component in front of you it applies to, and a missing\\n    # template is equally an uninstalled bundle, an imported flow or the\\n    # caller's own component. The editor needs the identities to name a cause\\n    # truthfully. It reveals nothing the palette does not: these are exactly\\n    # the components already withheld from ``/all`` for this caller.\\n    blocked_component_types: list[str] = []\\n\\n    @classmethod\\n    def from_settings(\\n        cls,\\n        settings: Settings,\\n        auth_settings,\\n        *,\\n        catalog_governance_enabled: bool = False,\\n        blocked_component_types: list[str] | None = None,\\n    ) -> \\\"ConfigResponse\\\":\\n        \\\"\\\"\\\"Create a ConfigResponse instance using values from a Settings object and AuthSettings.\\n\\n        Parameters:\\n            settings (Settings): The Settings object containing configuration values.\\n            auth_settings: The AuthSettings object containing authentication configuration values.\\n            catalog_governance_enabled: Whether any catalog policy currently restricts resources.\\n            blocked_component_types: Component types this caller may not use.\\n\\n        Returns:\\n            ConfigResponse: An instance populated with configuration and feature flag values.\\n        \\\"\\\"\\\"\\n        from langflow.services.database.models.folder.constants import DEFAULT_FOLDER_NAME\\n\\n        return cls(\\n            feature_flags=FEATURE_FLAGS,\\n            serialization_max_items_length=settings.max_items_length,\\n            serialization_max_text_length=settings.max_text_length,\\n            frontend_timeout=settings.frontend_timeout,\\n            auto_saving=settings.auto_saving,\\n            auto_saving_interval=settings.auto_saving_interval,\\n            health_check_max_retries=settings.health_check_max_retries,\\n            max_file_size_upload=settings.max_file_size_upload,\\n            webhook_polling_interval=settings.webhook_polling_interval,\\n            public_flow_cleanup_interval=settings.public_flow_cleanup_interval,\\n            public_flow_expiration=settings.public_flow_expiration,\\n            event_delivery=settings.event_delivery,\\n            voice_mode_available=settings.voice_mode_available,\\n            mcp_base_url=settings.mcp_base_url,\\n            enable_extension_reload=settings.enable_extension_reload,\\n            webhook_auth_enable=auth_settings.WEBHOOK_AUTH_ENABLE,\\n            default_folder_name=DEFAULT_FOLDER_NAME,\\n            hide_getting_started_progress=settings.hide_getting_started_progress,\\n            allow_custom_components=settings.allow_custom_components,\\n            substitute_outdated_component_code=settings.substitute_outdated_component_code,\\n            authz_enabled=bool(getattr(auth_settings, \\\"AUTHZ_ENABLED\\\", False)),\\n            catalog_governance_enabled=catalog_governance_enabled,\\n            blocked_component_types=sorted(blocked_component_types or []),\\n            embedded_mode=settings.embedded_mode,\\n            hide_logout_button=settings.hide_logout_button or settings.embedded_mode,\\n            hide_new_project_button=settings.hide_new_project_button or settings.embedded_mode,\\n            hide_new_flow_button=settings.hide_new_flow_button or settings.embedded_mode,\\n            hide_starter_projects=settings.hide_starter_projects or settings.embedded_mode,\\n            mcp_servers_locked=settings.mcp_servers_locked,\\n            custom_component_admin_only=settings.custom_component_admin_only,\\n            a2a_enabled=settings.a2a_enabled,\\n            agentic_experience=settings.agentic_experience,\\n            assistant_max_message_length=settings.assistant_max_message_length,\\n            local_vector_store_available=settings.deployment_profile != \\\"prod\\\",\\n        )\\n\\n\\nclass CancelFlowResponse(BaseModel):\\n    \\\"\\\"\\\"Response model for flow build cancellation.\\\"\\\"\\\"\\n\\n    success: bool\\n    message: str\\n\\n\\nclass AuthSettings(BaseModel):\\n    \\\"\\\"\\\"Model representing authentication settings for MCP.\\\"\\\"\\\"\\n\\n    auth_type: Literal[\\\"none\\\", \\\"apikey\\\", \\\"oauth\\\"] = \\\"none\\\"\\n    oauth_host: str | None = None\\n    oauth_port: str | None = None\\n    oauth_server_url: str | None = None\\n    oauth_callback_path: str | None = None  # Deprecated: use oauth_callback_url instead\\n    oauth_callback_url: str | None = None\\n    oauth_client_id: str | None = None\\n    oauth_client_secret: SecretStr | None = None\\n    oauth_auth_url: str | None = None\\n    oauth_token_url: str | None = None\\n    oauth_mcp_scope: str | None = None\\n    oauth_provider_scope: str | None = None\\n\\n    def model_post_init(self, __context, /) -> None:\\n        \\\"\\\"\\\"Normalize oauth_callback_path to oauth_callback_url for backwards compatibility.\\\"\\\"\\\"\\n        # If oauth_callback_url is not set but oauth_callback_path is, use the path value\\n        if self.oauth_callback_url is None and self.oauth_callback_path is not None:\\n            self.oauth_callback_url = self.oauth_callback_path\\n        # If both are set, oauth_callback_url takes precedence (already set correctly)\\n\\n\\nclass MCPSettings(BaseModel):\\n    \\\"\\\"\\\"Model representing MCP settings for a flow.\\\"\\\"\\\"\\n\\n    id: UUID\\n    mcp_enabled: bool | None = None\\n    action_name: str | None = None\\n    action_description: str | None = None\\n    name: str | None = None\\n    description: str | None = None\\n\\n\\nclass MCPProjectUpdateRequest(BaseModel):\\n    \\\"\\\"\\\"Request model for updating MCP project settings including auth.\\\"\\\"\\\"\\n\\n    settings: list[MCPSettings]\\n    auth_settings: AuthSettings | None = None\\n\\n\\nclass MCPProjectResponse(BaseModel):\\n    \\\"\\\"\\\"Response model for MCP project tools with auth settings.\\\"\\\"\\\"\\n\\n    tools: list[MCPSettings]\\n    auth_settings: AuthSettings | None = None\\n\\n\\nclass ComposerUrlResponse(BaseModel):\\n    \\\"\\\"\\\"Response model for MCP Composer connection details.\\\"\\\"\\\"\\n\\n    project_id: str\\n    uses_composer: bool\\n    streamable_http_url: str | None = None\\n    legacy_sse_url: str | None = None\\n    error_message: str | None = None\\n\\n\\nclass MCPInstallRequest(BaseModel):\\n    client: str\\n    transport: Literal[\\\"sse\\\", \\\"streamablehttp\\\"] | None = None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/schemas/authz_role_assignments.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7bb490629cdf18220bf1ba5f3de84e4a887c20b47652e826029cc78a44764f8b\",\"content\":\"\\\"\\\"\\\"Pydantic schemas for /api/v1/authz/role-assignments.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime\\nfrom typing import Literal\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, Field, model_validator\\n\\n# Recognized domain categories for ``authz_role_assignment.domain_type``.\\n# ``global``  \u2014 assignment is unscoped, ``domain_id`` MUST be null.\\n# ``org`` / ``workspace`` / ``project`` \u2014 scoped, ``domain_id`` MUST be set.\\n# Keeping this as a ``Literal`` rejects free-form strings at the API\\n# boundary instead of letting a typo (``\\\"organization\\\"``) silently\\n# create a row that no enforcer will ever match.\\nDomainType = Literal[\\\"global\\\", \\\"org\\\", \\\"workspace\\\", \\\"project\\\"]\\n\\n\\nclass RoleAssignmentCreate(BaseModel):\\n    \\\"\\\"\\\"Payload for assigning a role to a user.\\\"\\\"\\\"\\n\\n    user_id: UUID\\n    role_id: UUID\\n    domain_type: DomainType = Field(\\n        default=\\\"global\\\",\\n        description=(\\n            \\\"Domain scope of the assignment. ``global`` is unscoped (no \\\"\\n            \\\"``domain_id``); ``org``/``workspace``/``project`` require a \\\"\\n            \\\"matching ``domain_id``.\\\"\\n        ),\\n    )\\n    domain_id: UUID | None = Field(\\n        default=None,\\n        description=\\\"Required when ``domain_type`` is org/workspace/project; must be null for ``global``.\\\",\\n    )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _check_domain_id_consistency(self) -> RoleAssignmentCreate:\\n        if self.domain_type == \\\"global\\\" and self.domain_id is not None:\\n            msg = \\\"domain_id must be null when domain_type='global'\\\"\\n            raise ValueError(msg)\\n        # org / workspace / project all require an id \u2014 without one the\\n        # assignment cannot match any concrete domain in the enforcer.\\n        if self.domain_type != \\\"global\\\" and self.domain_id is None:\\n            msg = f\\\"domain_id is required when domain_type={self.domain_type!r}\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass RoleAssignmentGrantSummary(BaseModel):\\n    \\\"\\\"\\\"Non-secret provenance returned with an effective role assignment.\\\"\\\"\\\"\\n\\n    source_kind: Literal[\\\"manual\\\", \\\"idp\\\"]\\n    provider_id: str | None\\n    external_group: str | None\\n    administrative_actor: UUID | None\\n    created_at: datetime\\n    updated_at: datetime\\n\\n    model_config = {\\\"from_attributes\\\": True}\\n\\n\\nclass RoleAssignmentRead(BaseModel):\\n    \\\"\\\"\\\"Serialized effective assignment plus its independent grant sources.\\\"\\\"\\\"\\n\\n    id: UUID\\n    user_id: UUID\\n    role_id: UUID\\n    domain_type: str\\n    domain_id: UUID | None\\n    assigned_at: datetime\\n    assigned_by: UUID | None\\n    grant_sources: list[RoleAssignmentGrantSummary] = Field(default_factory=list)\\n\\n    model_config = {\\\"from_attributes\\\": True}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/schemas/authz_roles.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"52997a8e4cc5fc2c56d1d7f47ba98847aa044c792f140201a4a0b6d594b759af\",\"content\":\"\\\"\\\"\\\"Pydantic schemas for /api/v1/authz/roles.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\nfrom datetime import datetime\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, Field, field_validator\\n\\nfrom langflow.services.authorization.actions import (\\n    DeploymentAction,\\n    FileAction,\\n    FlowAction,\\n    KnowledgeBaseAction,\\n    ProjectAction,\\n    ProviderAccountAction,\\n    ShareAction,\\n    VariableAction,\\n    VoiceAction,\\n)\\n\\n# Canonical permission slug is ``<resource>:<action>`` \u2014 matches the\\n# system-role seed in ``8d3a1f9c2e0b_seed_authz_system_roles`` and the\\n# ``\\\"{resource}:{action}\\\"`` contract documented in AGENTS.md. Plugins\\n# that compile these to policy rows expect this exact shape, so we\\n# reject other forms (``flow:*:read``, ``flow:read:extra``, ...) at the\\n# API boundary instead of letting them slip into ``authz_role.permissions``\\n# and silently fail the next policy sync.\\n#\\n# Resource and action validation is *coupled*: each resource only supports\\n# the actions exposed by its enum in ``services/authorization/actions.py``.\\n# Validating them independently would let admins create permissions like\\n# ``file:deploy`` or ``share:execute`` that no enforce() call could ever\\n# match \u2014 undermining the canonical-slug guarantee. The map below is the\\n# authoritative source. ``*`` (all actions on that resource) is always\\n# accepted; ``*`` as a resource is NOT \u2014 a role granting every action on\\n# every resource is effectively superuser and should not be expressible\\n# as a slug.\\n_RESOURCE_ACTIONS: dict[str, frozenset[str]] = {\\n    \\\"flow\\\": frozenset({a.value for a in FlowAction}) | {\\\"*\\\"},\\n    \\\"deployment\\\": frozenset({a.value for a in DeploymentAction}) | {\\\"*\\\"},\\n    \\\"project\\\": frozenset({a.value for a in ProjectAction}) | {\\\"*\\\"},\\n    \\\"knowledge_base\\\": frozenset({a.value for a in KnowledgeBaseAction}) | {\\\"*\\\"},\\n    \\\"variable\\\": frozenset({a.value for a in VariableAction}) | {\\\"*\\\"},\\n    \\\"file\\\": frozenset({a.value for a in FileAction}) | {\\\"*\\\"},\\n    \\\"share\\\": frozenset({a.value for a in ShareAction}) | {\\\"*\\\"},\\n    \\\"provider_account\\\": frozenset({a.value for a in ProviderAccountAction}) | {\\\"*\\\"},\\n    \\\"voice\\\": frozenset({a.value for a in VoiceAction}) | {\\\"*\\\"},\\n}\\n\\n_PERMISSION_SLUG_RE = re.compile(r\\\"^[a-z_]+:[a-z_*]+$\\\")\\n_MODEL_COMPONENT_PERMISSION_RE = re.compile(r\\\"^component:models/(?:[a-z0-9][a-z0-9._-]*|\\\\*):read$\\\")\\n\\n\\ndef _validate_permission_slug(slug: str) -> str:\\n    # Pydantic coerces ``list[str]`` so we only ever see strings here; the\\n    # regex check carries the real format guarantee.\\n    # Model-provider palette permissions are the single supported nested\\n    # object form. Keep this exception deliberately narrow so accepting\\n    # ``component:models/openai:read`` does not make arbitrary three-segment\\n    # slugs valid. Provider IDs share the registry's stable-ID alphabet.\\n    if _MODEL_COMPONENT_PERMISSION_RE.fullmatch(slug):\\n        return slug\\n\\n    if not _PERMISSION_SLUG_RE.fullmatch(slug):\\n        msg = (\\n            f\\\"permission {slug!r} is not in the canonical \\\"\\n            \\\"'<resource>:<action>' form (e.g. 'flow:read', 'deployment:execute')\\\"\\n        )\\n        raise ValueError(msg)\\n    resource, action = slug.split(\\\":\\\", 1)\\n    allowed = _RESOURCE_ACTIONS.get(resource)\\n    if allowed is None:\\n        msg = f\\\"permission {slug!r} has unknown resource {resource!r}; expected one of {sorted(_RESOURCE_ACTIONS)}\\\"\\n        raise ValueError(msg)\\n    if action not in allowed:\\n        # Surface the resource-specific action vocabulary so callers can\\n        # fix the slug without consulting the enums directly.\\n        msg = (\\n            f\\\"permission {slug!r} has unknown action {action!r} for resource {resource!r}; \\\"\\n            f\\\"expected one of {sorted(allowed)}\\\"\\n        )\\n        raise ValueError(msg)\\n    return slug\\n\\n\\nclass RoleCreate(BaseModel):\\n    \\\"\\\"\\\"Payload for creating an authz_role row.\\\"\\\"\\\"\\n\\n    name: str = Field(..., min_length=1, max_length=255)\\n    description: str | None = Field(default=None)\\n    permissions: list[str] = Field(\\n        default_factory=list,\\n        description=(\\n            \\\"Permission slugs in the canonical ``<resource>:<action>`` form \u2014 for \\\"\\n            \\\"example ``flow:read``, ``deployment:execute``, ``share:create``. \\\"\\n            \\\"Resources must be one of flow, deployment, project, knowledge_base, \\\"\\n            \\\"variable, file, share, provider_account, voice, plus the narrow model-provider form \\\"\\n            \\\"``component:models/<provider-id>:read``. Actions are constrained per-resource (see \\\"\\n            \\\"``services/authorization/actions.py``): e.g. ``deploy`` is only valid \\\"\\n            \\\"on ``flow``, ``ingest`` only on ``knowledge_base``, ``update`` only on \\\"\\n            \\\"``share``. ``*`` (all actions on that resource) is always accepted. \\\"\\n            \\\"A registered authorization plugin is responsible for compiling these \\\"\\n            \\\"into its policy format.\\\"\\n        ),\\n    )\\n    parent_role_id: UUID | None = Field(default=None)\\n\\n    @field_validator(\\\"permissions\\\")\\n    @classmethod\\n    def _validate_permissions(cls, value: list[str]) -> list[str]:\\n        return [_validate_permission_slug(s) for s in value]\\n\\n\\nclass RoleUpdate(BaseModel):\\n    \\\"\\\"\\\"Payload for updating an authz_role row (PATCH semantics \u2014 only set fields apply).\\\"\\\"\\\"\\n\\n    name: str | None = Field(default=None, min_length=1, max_length=255)\\n    description: str | None = None\\n    permissions: list[str] | None = None\\n    parent_role_id: UUID | None = None\\n\\n    @field_validator(\\\"permissions\\\")\\n    @classmethod\\n    def _validate_permissions(cls, value: list[str] | None) -> list[str] | None:\\n        if value is None:\\n            return None\\n        return [_validate_permission_slug(s) for s in value]\\n\\n\\nclass RoleRead(BaseModel):\\n    \\\"\\\"\\\"Serialized authz_role row returned by the API.\\\"\\\"\\\"\\n\\n    id: UUID\\n    name: str\\n    description: str | None\\n    is_system: bool\\n    permissions: list[str]\\n    parent_role_id: UUID | None\\n    workspace_id: UUID | None\\n    created_at: datetime\\n    updated_at: datetime\\n    created_by: UUID | None\\n\\n    model_config = {\\\"from_attributes\\\": True}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/schemas/authz_shares.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e56154d16eec7c03c3911fc01196c356af0f34a2f8c9671104940b58bde10a66\",\"content\":\"\\\"\\\"\\\"Pydantic schemas for /api/v1/authz/shares.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime\\nfrom typing import Literal\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, Field, model_validator\\n\\n# Shareable resource slugs (keep aligned with authorization action modules).\\nShareResourceType = Literal[\\n    \\\"flow\\\",\\n    \\\"deployment\\\",\\n    \\\"project\\\",\\n    \\\"knowledge_base\\\",\\n    \\\"variable\\\",\\n    \\\"file\\\",\\n]\\n\\nShareScopeLiteral = Literal[\\\"private\\\", \\\"team\\\", \\\"user\\\", \\\"public\\\"]\\nSharePermissionLiteral = Literal[\\\"read\\\", \\\"write\\\", \\\"execute\\\", \\\"admin\\\"]\\n\\n\\nclass ShareCreate(BaseModel):\\n    \\\"\\\"\\\"Payload for creating an authz_share row.\\\"\\\"\\\"\\n\\n    resource_type: ShareResourceType\\n    resource_id: UUID\\n    scope: ShareScopeLiteral\\n    target_id: UUID | None = Field(default=None)\\n    permission_level: SharePermissionLiteral = \\\"read\\\"\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _check_scope_target_consistency(self) -> ShareCreate:\\n        \\\"\\\"\\\"Require target_id for user/team scopes; forbid it for private/public.\\\"\\\"\\\"\\n        targeted = self.scope in (\\\"team\\\", \\\"user\\\")\\n        if targeted and self.target_id is None:\\n            msg = f\\\"scope {self.scope!r} requires target_id\\\"\\n            raise ValueError(msg)\\n        if not targeted and self.target_id is not None:\\n            msg = f\\\"scope {self.scope!r} must not set target_id\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass ShareUpdate(BaseModel):\\n    \\\"\\\"\\\"Payload for updating an authz_share permission level.\\\"\\\"\\\"\\n\\n    permission_level: SharePermissionLiteral\\n\\n\\nclass ShareRead(BaseModel):\\n    \\\"\\\"\\\"Serialized authz_share row returned by the API.\\\"\\\"\\\"\\n\\n    id: UUID\\n    resource_type: ShareResourceType\\n    resource_id: UUID\\n    scope: ShareScopeLiteral\\n    target_id: UUID | None\\n    target_name: str | None = None\\n    permission_level: SharePermissionLiteral\\n    created_by: UUID | None\\n    created_at: datetime\\n\\n    model_config = {\\\"from_attributes\\\": True}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/schemas/authz_teams.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"65d90fdb55d88f501b72ac5dd71aeb416b83edff59ea165890994c40a4e2e17c\",\"content\":\"\\\"\\\"\\\"Pydantic schemas for /api/v1/authz/teams and team members.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime\\nfrom typing import Literal\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, Field\\n\\n\\nclass TeamCreate(BaseModel):\\n    \\\"\\\"\\\"Payload for creating an authz_team.\\\"\\\"\\\"\\n\\n    team_name: str = Field(..., min_length=1, max_length=255)\\n    adom_name: str = Field(\\n        ...,\\n        min_length=1,\\n        max_length=255,\\n        description=\\\"Administrative-domain slug, unique across all teams (often the SSO group name).\\\",\\n    )\\n    description: str | None = None\\n    is_active: bool = True\\n\\n\\nclass TeamUpdate(BaseModel):\\n    \\\"\\\"\\\"Payload for updating an authz_team (PATCH semantics).\\\"\\\"\\\"\\n\\n    team_name: str | None = Field(default=None, min_length=1, max_length=255)\\n    adom_name: str | None = Field(default=None, min_length=1, max_length=255)\\n    description: str | None = None\\n    is_active: bool | None = None\\n\\n\\nclass TeamRead(BaseModel):\\n    \\\"\\\"\\\"Serialized authz_team row returned by the API.\\\"\\\"\\\"\\n\\n    id: UUID\\n    team_name: str\\n    adom_name: str\\n    description: str | None\\n    is_active: bool\\n    created_at: datetime\\n    updated_at: datetime\\n\\n    model_config = {\\\"from_attributes\\\": True}\\n\\n\\nclass TeamMemberCreate(BaseModel):\\n    \\\"\\\"\\\"Payload for adding a user to a team.\\\"\\\"\\\"\\n\\n    user_id: UUID\\n    source: Literal[\\\"manual\\\", \\\"sso\\\"] = \\\"manual\\\"\\n\\n\\nclass TeamMemberRead(BaseModel):\\n    \\\"\\\"\\\"Serialized authz_team_member row.\\\"\\\"\\\"\\n\\n    id: UUID\\n    team_id: UUID\\n    user_id: UUID\\n    source: str\\n    created_at: datetime\\n\\n    model_config = {\\\"from_attributes\\\": True}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/schemas/catalog_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a6b6c5f26571513feb0a21b5e9d46b54856ba9036faf919de1498dfd8f3b1442\",\"content\":\"\\\"\\\"\\\"Schemas for the catalog-policy administration API.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, Field, StringConstraints, field_validator\\n\\nCATALOG_POLICY_KEY_MAX_LENGTH = 255\\nCATALOG_POLICY_KEYS_MAX_LENGTH = 1000\\n\\nCatalogPolicyKey = Annotated[\\n    str,\\n    StringConstraints(\\n        strip_whitespace=True,\\n        min_length=1,\\n        max_length=CATALOG_POLICY_KEY_MAX_LENGTH,\\n    ),\\n]\\nCatalogPolicyKeyList = Annotated[list[CatalogPolicyKey], Field(max_length=CATALOG_POLICY_KEYS_MAX_LENGTH)]\\n\\n\\ndef normalize_catalog_policy_keys(value: list[str]) -> list[str]:\\n    \\\"\\\"\\\"Deduplicate validated catalog keys and sort them deterministically.\\\"\\\"\\\"\\n    return sorted(set(value))\\n\\n\\nclass CatalogPolicyBlockedSet(BaseModel):\\n    \\\"\\\"\\\"A normalized whole-set catalog block policy.\\\"\\\"\\\"\\n\\n    blocked: CatalogPolicyKeyList = Field(\\n        ...,\\n        description=\\\"Complete set of blocked catalog keys for this resource kind.\\\",\\n    )\\n\\n    @field_validator(\\\"blocked\\\")\\n    @classmethod\\n    def normalize_blocked_keys(cls, value: list[str]) -> list[str]:\\n        \\\"\\\"\\\"Deduplicate and sort the already-trimmed, validated keys.\\\"\\\"\\\"\\n        return normalize_catalog_policy_keys(value)\\n\\n\\nclass CatalogPolicyRead(BaseModel):\\n    \\\"\\\"\\\"Current catalog block policy and its ownership source.\\\"\\\"\\\"\\n\\n    # Response/history schemas intentionally remain unconstrained so a policy\\n    # written by an older release can still be read and repaired.\\n    blocked: list[str]\\n    managed_externally: bool\\n\\n\\nclass CatalogPolicyUsageRead(BaseModel):\\n    \\\"\\\"\\\"Per-component flow-usage counts for catalog governance.\\\"\\\"\\\"\\n\\n    components: dict[str, int] = Field(\\n        description=(\\n            \\\"Number of flows using each component, keyed by the canonical \\\"\\n            \\\"registry identity (or the exact stored key for components not in \\\"\\n            \\\"the current registry). A flow is counted once per component.\\\"\\n        ),\\n    )\\n    flows_scanned: int = Field(description=\\\"Total number of flows examined.\\\")\\n\\n\\nclass CatalogPolicyUsageFlowRef(BaseModel):\\n    \\\"\\\"\\\"A flow that uses the queried component.\\\"\\\"\\\"\\n\\n    id: UUID\\n    name: str\\n\\n\\nclass CatalogPolicyUsageFlowsRead(BaseModel):\\n    \\\"\\\"\\\"Flows affected by blocking one component key.\\\"\\\"\\\"\\n\\n    component: str\\n    total: int = Field(description=\\\"Total number of matching flows, before the limit is applied.\\\")\\n    flows: list[CatalogPolicyUsageFlowRef]\\n\\n\\n__all__ = [\\n    \\\"CATALOG_POLICY_KEYS_MAX_LENGTH\\\",\\n    \\\"CATALOG_POLICY_KEY_MAX_LENGTH\\\",\\n    \\\"CatalogPolicyBlockedSet\\\",\\n    \\\"CatalogPolicyKey\\\",\\n    \\\"CatalogPolicyKeyList\\\",\\n    \\\"CatalogPolicyRead\\\",\\n    \\\"CatalogPolicyUsageFlowRef\\\",\\n    \\\"CatalogPolicyUsageFlowsRead\\\",\\n    \\\"CatalogPolicyUsageRead\\\",\\n    \\\"normalize_catalog_policy_keys\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/schemas/deployments.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"44277827be27291a73225ade336f7d42a11f3f2a416e66738d1cbb6e2549dccd\",\"content\":\"\\\"\\\"\\\"Deployment API request and response schemas.\\n\\nIdentifier domains\\n------------------\\nTwo identifier domains coexist in these schemas:\\n\\n* **Langflow-managed (UUID)** -- ``id``, ``provider_id``, ``project_id``,\\n  ``deployment_id``. These reference rows in the Langflow database.\\n  ``provider_id`` maps to ``deployment_provider_account.id``.\\n\\n* **Provider-owned (str)** -- ``reference_id``, ``config_id``,\\n  ``run_id``.\\n  Opaque values assigned or consumed by the external deployment provider.\\n  ``provider_key`` is Langflow-owned adapter vocabulary.\\n  Provider-specific metadata (for example URL and tenant/account identifiers)\\n  belongs inside ``provider_data``.\\n\\n* **Provider-originated but Langflow-owned once persisted** -- ``resource_key``.\\n  Langflow stores and indexes this as part of its own deployment record.\\n\\n``provider_data`` dicts are opaque pass-through containers whose contents\\nare defined by the provider adapter. Langflow forwards them without\\ninterpreting their schema.\\n\\nDeploymentType is imported from the adapter service layer as shared\\nvocabulary. Request/response models in this module are API-owned to keep\\nthe client-facing schema minimal and avoid exposing service-only fields.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime\\nfrom typing import Annotated, Any\\nfrom uuid import UUID\\n\\nfrom lfx.services.adapters.deployment.schema import DeploymentType\\nfrom pydantic import AfterValidator, BaseModel, Field, ValidationInfo, model_validator\\n\\nfrom langflow.services.database.models.deployment_provider_account.schemas import (\\n    DeploymentProviderKey,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.utils import (\\n    validate_provider_url,\\n)\\n\\n# ---------------------------------------------------------------------------\\n# Shared validation helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _validate_uuid_list(values: list[UUID], *, field_name: str) -> list[UUID]:\\n    \\\"\\\"\\\"Deduplicate (preserving order) and reject empty lists.\\\"\\\"\\\"\\n    deduped = list(dict.fromkeys(values))\\n    if not deduped:\\n        msg = f\\\"{field_name} must not be empty.\\\"\\n        raise ValueError(msg)\\n    return deduped\\n\\n\\ndef _normalize_str(value: str, *, field_name: str = \\\"Field\\\") -> str:\\n    \\\"\\\"\\\"Strip whitespace from a string, rejecting empty or whitespace-only values.\\\"\\\"\\\"\\n    normalized = value.strip()\\n    if not normalized:\\n        msg = f\\\"'{field_name}' must not be empty or whitespace.\\\"\\n        raise ValueError(msg)\\n    return normalized\\n\\n\\ndef _normalize_optional_str(value: str | None, *, field_name: str = \\\"Field\\\") -> str | None:\\n    \\\"\\\"\\\"Strip whitespace from an optional string, rejecting whitespace-only values.\\\"\\\"\\\"\\n    if value is None:\\n        return None\\n    return _normalize_str(value, field_name=field_name)\\n\\n\\ndef _strip_nonempty(value: str, info: ValidationInfo) -> str:\\n    \\\"\\\"\\\"AfterValidator function: strip whitespace, reject empty/whitespace-only.\\\"\\\"\\\"\\n    return _normalize_str(value, field_name=info.field_name or \\\"Field\\\")\\n\\n\\nNonEmptyStr = Annotated[str, AfterValidator(_strip_nonempty)]\\n\\\"\\\"\\\"String type that strips whitespace and rejects empty/whitespace-only values.\\\"\\\"\\\"\\n\\n\\nValidatedUrl = Annotated[str, AfterValidator(validate_provider_url)]\\n\\\"\\\"\\\"URL type that enforces HTTPS and normalizes.\\\"\\\"\\\"\\n\\n\\ndef _validate_flow_version_ids(values: list[UUID] | None) -> list[UUID] | None:\\n    \\\"\\\"\\\"AfterValidator for optional flow_version_ids query parameter.\\\"\\\"\\\"\\n    if values is None:\\n        return None\\n    return _validate_uuid_list(values, field_name=\\\"flow_version_ids\\\")\\n\\n\\nFlowVersionIdsQuery = Annotated[list[UUID] | None, AfterValidator(_validate_flow_version_ids)]\\n\\\"\\\"\\\"Optional flow-version filter query parameter.\\n\\n``None`` means no filter. Empty lists are rejected by validation.\\n\\\"\\\"\\\"\\n\\n\\ndef _validate_flow_ids(values: list[UUID] | None) -> list[UUID] | None:\\n    \\\"\\\"\\\"AfterValidator for optional flow_ids query parameter.\\n\\n    Deduplicates and enforces max length of 1 today; remove the length\\n    guard when multi-flow filtering is needed.\\n    \\\"\\\"\\\"\\n    if values is None:\\n        return None\\n    validated = _validate_uuid_list(values, field_name=\\\"flow_ids\\\")\\n    if len(validated) > 1:\\n        msg = \\\"flow_ids currently supports at most 1 value.\\\"\\n        raise ValueError(msg)\\n    return validated\\n\\n\\nFlowIdsQuery = Annotated[list[UUID] | None, AfterValidator(_validate_flow_ids)]\\n\\\"\\\"\\\"Optional flow-id filter query parameter.\\n\\n``None`` means no filter. Empty lists are rejected by validation.\\nMax supported length is 1 today.\\n\\\"\\\"\\\"\\n\\n\\ndef _validate_detect_vars_request_ids(values: list[UUID]) -> list[UUID]:\\n    \\\"\\\"\\\"AfterValidator for DetectVarsRequest.flow_version_ids.\\\"\\\"\\\"\\n    return _validate_uuid_list(values, field_name=\\\"flow_version_ids\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Provider sub-resource schemas\\n# ---------------------------------------------------------------------------\\n\\n\\nclass DeploymentProviderAccountCreateRequest(BaseModel):\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    name: NonEmptyStr = Field(\\n        description=(\\n            \\\"User-chosen display name for this provider account. Must be unique per user within a provider_key.\\\"\\n        ),\\n    )\\n    provider_key: DeploymentProviderKey = Field(description=\\\"Deployment provider key.\\\")\\n    provider_data: dict[str, Any] = Field(\\n        min_length=1,\\n        description=(\\n            \\\"Provider-specific credential/metadata payload. \\\"\\n            \\\"Contents are provider-defined and may include credentials \\\"\\n            \\\"and metadata such as URL/region and tenant/account identifiers.\\\"\\n        ),\\n    )\\n\\n\\nclass DeploymentProviderAccountUpdateRequest(BaseModel):\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    name: NonEmptyStr | None = Field(\\n        default=None,\\n        description=\\\"User-chosen display name. Omit to keep existing value; cannot be set to null.\\\",\\n    )\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Provider-specific credential payload. \\\"\\n            \\\"Omit to keep existing credentials; provided value replaces stored credentials. \\\"\\n            \\\"Cannot be set to null.\\\"\\n        ),\\n    )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def ensure_any_field_provided(self) -> DeploymentProviderAccountUpdateRequest:\\n        if not self.model_fields_set:\\n            msg = \\\"At least one field must be provided for update.\\\"\\n            raise ValueError(msg)\\n        for field_name in (\\\"name\\\", \\\"provider_data\\\"):\\n            if field_name in self.model_fields_set and getattr(self, field_name) is None:\\n                msg = f\\\"'{field_name}' cannot be set to null.\\\"\\n                raise ValueError(msg)\\n        return self\\n\\n\\nclass DeploymentProviderAccountGetResponse(BaseModel):\\n    id: UUID = Field(description=\\\"Langflow DB provider-account UUID (`deployment_provider_account.id`).\\\")\\n    name: str = Field(description=\\\"User-chosen display name for this provider account.\\\")\\n    provider_key: DeploymentProviderKey = Field(description=\\\"Official provider name used by Langflow.\\\")\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Provider-owned non-sensitive metadata for this provider account \\\"\\n            \\\"(for example URL, tenant/account identifiers). Credentials are excluded.\\\"\\n        ),\\n    )\\n    created_at: datetime | None = Field(default=None, description=\\\"Langflow DB row creation timestamp.\\\")\\n    updated_at: datetime | None = Field(default=None, description=\\\"Langflow DB row update timestamp.\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Deployment resource schemas\\n# ---------------------------------------------------------------------------\\n\\n\\nclass DeploymentTypeListResponse(BaseModel):\\n    \\\"\\\"\\\"Supported deployment types for a provider account.\\\"\\\"\\\"\\n\\n    deployment_types: list[DeploymentType]\\n\\n\\nclass DeploymentLlmListResponse(BaseModel):\\n    \\\"\\\"\\\"Provider model catalog payload for deployment LLM listing.\\\"\\\"\\\"\\n\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=\\\"Provider-owned opaque model catalog payload returned by the deployment provider.\\\",\\n    )\\n\\n\\nclass _DeploymentResponseCommon(BaseModel):\\n    \\\"\\\"\\\"Shared non-provider-data fields for deployment response schemas.\\\"\\\"\\\"\\n\\n    id: UUID = Field(description=\\\"Langflow DB deployment UUID.\\\")\\n    provider_id: UUID = Field(description=\\\"Langflow DB provider-account UUID (`deployment_provider_account.id`).\\\")\\n    provider_key: str = Field(description=\\\"Provider identifier (e.g. 'watsonx-orchestrate').\\\")\\n    description: str | None = None\\n    type: DeploymentType\\n    created_at: datetime | None = None\\n    updated_at: datetime | None = None\\n\\n\\nclass _DeploymentResponseWithProviderData(_DeploymentResponseCommon):\\n    \\\"\\\"\\\"Shared fields for responses that include provider_data.\\\"\\\"\\\"\\n\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=\\\"Provider-owned opaque payload returned by the deployment provider.\\\",\\n    )\\n\\n\\nclass DeploymentGetResponse(_DeploymentResponseWithProviderData):\\n    \\\"\\\"\\\"Full deployment detail.\\n\\n    Intentionally separate from ``DeploymentListItem`` even though both\\n    currently share the same fields.  The detail response is expected to\\n    grow (e.g. full config, attached flow versions, audit log) while the\\n    list item stays lean.\\n    \\\"\\\"\\\"\\n\\n    resource_key: str = Field(description=\\\"Langflow-persisted stable provider resource identifier.\\\")\\n    attached_count: int = Field(default=0, ge=0, description=\\\"Number of flow versions attached to this deployment.\\\")\\n\\n\\nclass DeploymentListItem(_DeploymentResponseCommon):\\n    \\\"\\\"\\\"Deployment representation used in list responses.\\n\\n    See ``DeploymentGetResponse`` docstring for rationale on the separate class.\\n    \\\"\\\"\\\"\\n\\n    resource_key: str = Field(description=\\\"Langflow-persisted stable provider resource identifier.\\\")\\n    attached_count: int = Field(default=0, ge=0, description=\\\"Number of flow versions attached to this deployment.\\\")\\n    flow_version_ids: list[UUID] | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Flow-version ids that matched the active flow_ids or \\\"\\n            \\\"flow_version_ids filter. Omitted when no such filter is active.\\\"\\n        ),\\n    )\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=\\\"Provider-owned opaque payload for this list item.\\\",\\n    )\\n\\n\\nclass _PaginatedResponse(BaseModel):\\n    \\\"\\\"\\\"Shared pagination fields for list responses.\\\"\\\"\\\"\\n\\n    page: int | None = Field(default=None, ge=1)\\n    size: int | None = Field(default=None, ge=1)\\n    total: int | None = Field(default=None, ge=0)\\n\\n\\nclass DeploymentListResponse(_PaginatedResponse):\\n    deployments: list[DeploymentListItem] | None = None\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=\\\"Provider-owned opaque payload for list-specific provider metadata.\\\",\\n    )\\n\\n\\nclass DeploymentProviderAccountListResponse(_PaginatedResponse):\\n    provider_accounts: list[DeploymentProviderAccountGetResponse]\\n\\n\\nclass DeploymentConfigListResponse(_PaginatedResponse):\\n    \\\"\\\"\\\"Paginated config list with all provider-owned data in a single opaque blob.\\\"\\\"\\\"\\n\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Provider-owned opaque payload containing the list of connections \\\"\\n            \\\"and any response-level metadata supplied by the provider.\\\"\\n        ),\\n    )\\n\\n\\nclass DeploymentSnapshotListResponse(_PaginatedResponse):\\n    \\\"\\\"\\\"Paginated snapshot list with all provider-owned data in a single opaque blob.\\\"\\\"\\\"\\n\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Provider-owned opaque payload containing the list of snapshots \\\"\\n            \\\"and any response-level metadata supplied by the provider.\\\"\\n        ),\\n    )\\n\\n\\nclass DeploymentFlowVersionListItem(BaseModel):\\n    \\\"\\\"\\\"Flow version metadata attached to a deployment.\\n\\n    **Identity model:** Langflow tracks provider tools by their immutable\\n    ``provider_snapshot_id`` (the wxO tool_id), never by name.  This\\n    distinguishes the following cases:\\n\\n    * **Tool renamed in provider** \u2014 Same ``provider_snapshot_id``, different\\n      ``provider_data.tool_display_name``. Langflow picks up the new label on the next fetch.\\n    * **Tool deleted in provider** \u2014 ``provider_snapshot_id`` no longer\\n      resolves. ``provider_data.tool_display_name`` may be missing/``None``.\\n    * **Tool deleted + new tool created with same name** \u2014 The new tool has\\n      a different ID.  Langflow's attachment still points to the old\\n      (missing) ID.  The new tool is invisible to Langflow until explicitly\\n      attached via an update operation.\\n\\n    Frontends should use ``provider_data.tool_display_name`` for display,\\n    ``provider_data.tool_name`` for provider technical metadata, and\\n    ``provider_snapshot_id`` for identity / operations.\\n    \\\"\\\"\\\"\\n\\n    id: UUID = Field(description=\\\"Langflow flow version UUID (`flow_version.id`).\\\")\\n    flow_id: UUID = Field(description=\\\"Langflow flow UUID (`flow.id`) for this version.\\\")\\n    flow_name: str | None = Field(\\n        default=None,\\n        description=\\\"Name of the flow owning this version (`flow.name`).\\\",\\n    )\\n    version_number: int = Field(ge=1, description=\\\"Flow version number.\\\")\\n    attached_at: datetime | None = Field(\\n        default=None,\\n        description=\\\"Timestamp when this flow version was attached to the deployment.\\\",\\n    )\\n    provider_snapshot_id: str | None = Field(\\n        default=None,\\n        description=\\\"Provider-owned snapshot/tool identifier linked by the attachment.\\\",\\n    )\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=\\\"Provider-owned opaque payload for this attached flow version.\\\",\\n    )\\n\\n\\nclass DeploymentFlowVersionListResponse(_PaginatedResponse):\\n    flow_versions: list[DeploymentFlowVersionListItem]\\n\\n\\nclass DeploymentCreateResponse(_DeploymentResponseWithProviderData):\\n    \\\"\\\"\\\"API response for deployment creation.\\\"\\\"\\\"\\n\\n    resource_key: str = Field(description=\\\"Langflow-persisted stable provider resource identifier.\\\")\\n\\n\\nclass DeploymentUpdateResponse(_DeploymentResponseWithProviderData):\\n    \\\"\\\"\\\"API response for deployment update.\\\"\\\"\\\"\\n\\n    resource_key: str = Field(description=\\\"Langflow-persisted stable provider resource identifier.\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Deployment create / update request schemas\\n# ---------------------------------------------------------------------------\\n\\n\\nclass DeploymentCreateRequest(BaseModel):\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    provider_id: UUID = Field(description=\\\"Langflow DB provider-account UUID (`deployment_provider_account.id`).\\\")\\n    description: str = Field(\\n        default=\\\"\\\",\\n        description=\\\"Deployment description.\\\",\\n    )\\n    type: DeploymentType = Field(description=\\\"Deployment type.\\\")\\n    project_id: UUID | None = Field(\\n        default=None,\\n        description=\\\"Langflow DB project id to persist the deployment under. Defaults to user's Starter Project.\\\",\\n    )\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=\\\"Provider-owned opaque create payload.\\\",\\n    )\\n\\n\\nclass DeploymentUpdateRequest(BaseModel):\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    description: str | None = Field(\\n        default=None,\\n        description=\\\"Updated deployment description.\\\",\\n    )\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=\\\"Provider-owned opaque update payload.\\\",\\n    )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def ensure_any_field_provided(self) -> DeploymentUpdateRequest:\\n        if not self.model_fields_set:\\n            msg = \\\"At least one of 'description' or 'provider_data' must be provided.\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\n# ---------------------------------------------------------------------------\\n# Run sub-resource schemas\\n# ---------------------------------------------------------------------------\\n\\n\\nclass RunCreateRequest(BaseModel):\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=\\\"Provider-owned opaque run input payload.\\\",\\n    )\\n\\n\\nclass _RunResponseBase(BaseModel):\\n    \\\"\\\"\\\"Shared fields for run responses.\\n\\n    Only Langflow-owned identifiers live at the top level.  All\\n    provider-owned data (including the provider's ``id``)\\n    is returned inside ``provider_data`` so that ownership boundaries\\n    stay clear and a future Langflow-managed run id won't\\n    collide with provider terminology.\\n    \\\"\\\"\\\"\\n\\n    deployment_id: UUID = Field(description=\\\"Langflow DB deployment UUID.\\\")\\n    provider_data: dict[str, Any] | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Provider-owned opaque run result payload.  \\\"\\n            \\\"Contains at least ``id`` (the provider's opaque run identifier) \\\"\\n            \\\"when the provider has assigned one.\\\"\\n        ),\\n    )\\n\\n\\nclass RunCreateResponse(_RunResponseBase):\\n    \\\"\\\"\\\"Response returned when a run is created.\\n\\n    Intentionally distinct from ``RunStatusResponse`` even though both\\n    currently share the same shape, mirroring the service-layer separation.\\n    \\\"\\\"\\\"\\n\\n\\nclass RunStatusResponse(_RunResponseBase):\\n    \\\"\\\"\\\"Response returned when querying a run status.\\n\\n    Intentionally distinct from ``RunCreateResponse`` even though both\\n    currently share the same shape, mirroring the service-layer separation.\\n    \\\"\\\"\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Snapshot sub-resource schemas\\n# ---------------------------------------------------------------------------\\n\\n\\nclass SnapshotUpdateRequest(BaseModel):\\n    \\\"\\\"\\\"Request body for PATCH /deployments/snapshots/{provider_snapshot_id}.\\n\\n    Updates the content of an existing provider snapshot with a new\\n    flow version's artifact.  The ``provider_snapshot_id`` is supplied\\n    as a path parameter; only ``flow_version_id`` is in the body.\\n    \\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    flow_version_id: UUID = Field(\\n        description=\\\"Langflow flow version whose artifact will replace the snapshot content.\\\",\\n    )\\n\\n\\nclass SnapshotUpdateResponse(BaseModel):\\n    \\\"\\\"\\\"Response for PATCH /deployments/snapshots/{provider_snapshot_id}.\\\"\\\"\\\"\\n\\n    flow_version_id: UUID\\n    provider_snapshot_id: str\\n\\n\\nclass DetectVarsRequest(BaseModel):\\n    \\\"\\\"\\\"Request body for detecting environment variables from flow version IDs.\\\"\\\"\\\"\\n\\n    flow_version_ids: Annotated[\\n        list[UUID],\\n        AfterValidator(_validate_detect_vars_request_ids),\\n    ] = Field(\\n        min_length=1,\\n        max_length=50,\\n        description=\\\"Flow version UUIDs to scan for global variable references.\\\",\\n    )\\n\\n\\nclass DetectVarsResponse(BaseModel):\\n    \\\"\\\"\\\"Response containing detected global variable names.\\\"\\\"\\\"\\n\\n    variables: list[str] = Field(default_factory=list, description=\\\"Detected global variable names.\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/schemas/public_flows.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9215e129a7c117e67ef0c45e917a028355f9c513c4ab22acac036586d5ce9d60\",\"content\":\"\\\"\\\"\\\"Pydantic schemas for the anonymous direct-link flow endpoint.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pydantic import Field\\n\\nfrom langflow.services.authorization.public_access import PublicFlowCapabilities\\nfrom langflow.services.database.models.flow.model import FlowRead\\n\\n\\nclass PublicFlowRead(FlowRead):\\n    \\\"\\\"\\\"A direct-link flow payload plus the capabilities its visitor actually has.\\n\\n    ``access_type`` alone cannot answer that question: a canonical\\n    ``AuthzShare(scope=public)`` admits a flow that is still PRIVATE, and the\\n    share's permission level \u2014 not the legacy flag \u2014 decides whether the visitor\\n    may run it. Clients gate on ``public_access`` so the UI matches the\\n    authorization decision that admitted the request.\\n    \\\"\\\"\\\"\\n\\n    public_access: PublicFlowCapabilities = Field(\\n        description=\\\"Anonymous actions permitted on this flow at its direct link.\\\",\\n    )\\n\\n\\n__all__ = [\\\"PublicFlowRead\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/starter_projects.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cd3abe8829e51b01ad5cb29f4e27f492c0bfa712f545e517f82d00a7b081520a\",\"content\":\"from typing import Any\\n\\nfrom fastapi import APIRouter, HTTPException, Request\\nfrom pydantic import BaseModel\\n\\nfrom langflow.api.utils import CurrentActiveUser\\nfrom langflow.services.deps import get_catalog_policy_service\\n\\nrouter = APIRouter(prefix=\\\"/starter-projects\\\", tags=[\\\"Flows\\\"])\\n\\n\\n# Pydantic models for API schema compatibility\\nclass ViewPort(BaseModel):\\n    x: float\\n    y: float\\n    zoom: float\\n\\n\\nclass NodeData(BaseModel):\\n    # This is a simplified version - the actual NodeData has many more fields\\n    # but we only need the basic structure for the API schema\\n    model_config = {\\\"extra\\\": \\\"allow\\\"}  # Allow extra fields\\n\\n\\nclass EdgeData(BaseModel):\\n    # This is a simplified version - the actual EdgeData has many more fields\\n    # but we only need the basic structure for the API schema\\n    model_config = {\\\"extra\\\": \\\"allow\\\"}  # Allow extra fields\\n\\n\\nclass GraphData(BaseModel):\\n    nodes: list[dict[str, Any]]  # Use dict to be flexible with the complex NodeData structure\\n    edges: list[dict[str, Any]]  # Use dict to be flexible with the complex EdgeData structure\\n    viewport: ViewPort | None = None\\n\\n\\nclass GraphDumpResponse(BaseModel):\\n    data: GraphData\\n    is_component: bool | None = None\\n    name: str | None = None\\n    name_key: str\\n    description: str | None = None\\n    endpoint_name: str | None = None\\n\\n\\n@router.get(\\\"/\\\", status_code=200)\\nasync def get_starter_projects(\\n    request: Request,\\n    current_user: CurrentActiveUser,\\n    *,\\n    include_blocked: bool = False,\\n) -> list[GraphDumpResponse]:\\n    \\\"\\\"\\\"Get a list of starter projects.\\\"\\\"\\\"\\n    from langflow.initial_setup.load import get_starter_projects_dump\\n    from langflow.utils.i18n import translate_flow_notes\\n\\n    if include_blocked and not current_user.is_superuser:\\n        raise HTTPException(status_code=403, detail=\\\"Only superusers can include blocked catalog templates.\\\")\\n\\n    catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n    locale = getattr(request.state, \\\"locale\\\", \\\"en\\\")\\n\\n    try:\\n        # Get the raw data from lfx GraphDump\\n        raw_data = get_starter_projects_dump()\\n\\n        # Convert TypedDict GraphDump to Pydantic GraphDumpResponse\\n        results = []\\n        for item in raw_data:\\n            name_key = item.get(\\\"name_key\\\")\\n            if not isinstance(name_key, str):\\n                continue\\n            if not include_blocked and catalog_policy_snapshot.is_template_blocked(name_key):\\n                continue\\n\\n            nodes = item.get(\\\"data\\\", {}).get(\\\"nodes\\\", [])\\n            translated_nodes = translate_flow_notes(nodes, locale)\\n\\n            # Create GraphData\\n            graph_data = GraphData(\\n                nodes=translated_nodes,\\n                edges=item.get(\\\"data\\\", {}).get(\\\"edges\\\", []),\\n                viewport=item.get(\\\"data\\\", {}).get(\\\"viewport\\\"),\\n            )\\n\\n            # Create GraphDumpResponse\\n            graph_dump = GraphDumpResponse(\\n                data=graph_data,\\n                is_component=item.get(\\\"is_component\\\"),\\n                name=item.get(\\\"name\\\"),\\n                name_key=name_key,\\n                description=item.get(\\\"description\\\"),\\n                endpoint_name=item.get(\\\"endpoint_name\\\"),\\n            )\\n            results.append(graph_dump)\\n\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n    return results\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/store.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8233abccadfacb3caeee6fcb82e872de8d59be4a0d49bfec0c2acafd238dc91f\",\"content\":\"from typing import Annotated\\nfrom uuid import UUID\\n\\nimport httpx\\nfrom fastapi import APIRouter, Depends, HTTPException, Query\\nfrom lfx.log.logger import logger\\n\\nfrom langflow.api.utils import CurrentActiveUser, check_langflow_version\\nfrom langflow.services.auth import utils as auth_utils\\nfrom langflow.services.deps import get_settings_service, get_store_service\\nfrom langflow.services.store.exceptions import CustomError\\nfrom langflow.services.store.schema import (\\n    CreateComponentResponse,\\n    DownloadComponentResponse,\\n    ListComponentResponseModel,\\n    StoreComponentCreate,\\n    TagResponse,\\n    UsersLikesResponse,\\n)\\n\\nrouter = APIRouter(prefix=\\\"/store\\\", tags=[\\\"Components Store\\\"], include_in_schema=False)\\n\\n\\ndef get_user_store_api_key(user: CurrentActiveUser):\\n    if not user.store_api_key:\\n        raise HTTPException(status_code=400, detail=\\\"You must have a store API key set.\\\")\\n    try:\\n        return auth_utils.decrypt_api_key(user.store_api_key)\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=\\\"Failed to decrypt API key. Please set a new one.\\\") from e\\n\\n\\ndef get_optional_user_store_api_key(user: CurrentActiveUser):\\n    if not user.store_api_key:\\n        return None\\n    try:\\n        return auth_utils.decrypt_api_key(user.store_api_key)\\n    except Exception:  # noqa: BLE001\\n        logger.exception(\\\"Failed to decrypt API key\\\")\\n        return user.store_api_key\\n\\n\\n@router.get(\\\"/check/\\\")\\nasync def check_if_store_is_enabled():\\n    return {\\n        \\\"enabled\\\": get_settings_service().settings.store,\\n    }\\n\\n\\n@router.get(\\\"/check/api_key\\\")\\nasync def check_if_store_has_api_key(\\n    api_key: Annotated[str | None, Depends(get_optional_user_store_api_key)],\\n):\\n    if api_key is None:\\n        return {\\\"has_api_key\\\": False, \\\"is_valid\\\": False}\\n\\n    try:\\n        is_valid = await get_store_service().check_api_key(api_key)\\n    except Exception as e:\\n        raise HTTPException(status_code=400, detail=str(e)) from e\\n\\n    return {\\\"has_api_key\\\": api_key is not None, \\\"is_valid\\\": is_valid}\\n\\n\\n@router.post(\\\"/components/\\\", status_code=201)\\nasync def share_component(\\n    component: StoreComponentCreate,\\n    store_api_key: Annotated[str, Depends(get_user_store_api_key)],\\n) -> CreateComponentResponse:\\n    try:\\n        await check_langflow_version(component)\\n        return await get_store_service().upload(store_api_key, component)\\n    except Exception as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n\\n\\n@router.patch(\\\"/components/{component_id}\\\", status_code=201)\\nasync def update_shared_component(\\n    component_id: UUID,\\n    component: StoreComponentCreate,\\n    store_api_key: Annotated[str, Depends(get_user_store_api_key)],\\n) -> CreateComponentResponse:\\n    try:\\n        await check_langflow_version(component)\\n        return await get_store_service().update(store_api_key, component_id, component)\\n    except Exception as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n\\n\\n@router.get(\\\"/components/\\\")\\nasync def get_components(\\n    *,\\n    component_id: Annotated[str | None, Query()] = None,\\n    search: Annotated[str | None, Query()] = None,\\n    private: Annotated[bool | None, Query()] = None,\\n    is_component: Annotated[bool | None, Query()] = None,\\n    tags: Annotated[list[str] | None, Query()] = None,\\n    sort: Annotated[list[str] | None, Query()] = None,\\n    liked: Annotated[bool, Query()] = False,\\n    filter_by_user: Annotated[bool, Query()] = False,\\n    fields: Annotated[list[str] | None, Query()] = None,\\n    page: int = 1,\\n    limit: int = 10,\\n    store_api_key: Annotated[str | None, Depends(get_optional_user_store_api_key)],\\n) -> ListComponentResponseModel:\\n    try:\\n        return await get_store_service().get_list_component_response_model(\\n            component_id=component_id,\\n            search=search,\\n            private=private,\\n            is_component=is_component,\\n            fields=fields,\\n            tags=tags,\\n            sort=sort,\\n            liked=liked,\\n            filter_by_user=filter_by_user,\\n            page=page,\\n            limit=limit,\\n            store_api_key=store_api_key,\\n        )\\n    except CustomError as exc:\\n        raise HTTPException(status_code=exc.status_code, detail=str(exc)) from exc\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n\\n@router.get(\\\"/components/{component_id}\\\")\\nasync def download_component(\\n    component_id: UUID,\\n    store_api_key: Annotated[str, Depends(get_user_store_api_key)],\\n) -> DownloadComponentResponse:\\n    try:\\n        component = await get_store_service().download(store_api_key, component_id)\\n    except CustomError as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n    if component is None:\\n        raise HTTPException(status_code=400, detail=\\\"Component not found\\\")\\n\\n    return component\\n\\n\\n@router.get(\\\"/tags\\\", response_model=list[TagResponse])\\nasync def get_tags():\\n    try:\\n        return await get_store_service().get_tags()\\n    except CustomError as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n    except httpx.TransportError as exc:\\n        # The store is a third-party service and the visual editor asks for tags on\\n        # every app boot, so an unreachable upstream must not read as a fault of this\\n        # server. Tags only decorate a filter, so degrade to none and keep 500 for\\n        # failures that ARE ours.\\n        await logger.awarning(f\\\"Langflow Store unreachable; serving no tags: {exc}\\\")\\n        return []\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n\\n@router.get(\\\"/users/likes\\\", response_model=list[UsersLikesResponse])\\nasync def get_list_of_components_liked_by_user(\\n    store_api_key: Annotated[str, Depends(get_user_store_api_key)],\\n):\\n    try:\\n        return await get_store_service().get_user_likes(store_api_key)\\n    except CustomError as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n\\n@router.post(\\\"/users/likes/{component_id}\\\")\\nasync def like_component(\\n    component_id: UUID,\\n    store_api_key: Annotated[str, Depends(get_user_store_api_key)],\\n) -> UsersLikesResponse:\\n    try:\\n        store_service = get_store_service()\\n        result = await store_service.like_component(store_api_key, str(component_id))\\n        likes_count = await store_service.get_component_likes_count(str(component_id), store_api_key)\\n\\n        return UsersLikesResponse(likes_count=likes_count, liked_by_user=result)\\n    except CustomError as exc:\\n        raise HTTPException(status_code=exc.status_code, detail=str(exc)) from exc\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/traces.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f4e056cf2f3174bdef687aa91c06985ffbe12771e4e3a93125e3aef017498ed2\",\"content\":\"\\\"\\\"\\\"API endpoints for execution traces.\\n\\nThis module provides HTTP handlers for retrieving and deleting execution trace\\ndata from the native tracer, enabling the Trace View in the frontend.\\n\\nBusiness logic (query/aggregation) lives in:\\n    langflow.services.tracing.repository\\n\\nData transformation logic lives in:\\n    langflow.services.tracing.formatting\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nimport logging\\nfrom datetime import datetime\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nimport sqlalchemy as sa\\nfrom fastapi import APIRouter, Depends, HTTPException, Query\\nfrom sqlalchemy.exc import OperationalError, ProgrammingError\\nfrom sqlmodel import col, select\\n\\nfrom langflow.services.auth.utils import get_current_active_user\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.traces.model import (\\n    SpanStatus,\\n    TraceListResponse,\\n    TraceRead,\\n    TraceTable,\\n)\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import session_scope\\nfrom langflow.services.tracing.repository import fetch_single_trace, fetch_traces\\nfrom langflow.services.tracing.validation import sanitize_query_string\\n\\nlogger = logging.getLogger(__name__)\\n\\n# Keeps the API responsive when the trace table doesn't exist yet or the DB is slow at startup.\\nDB_TIMEOUT = 5.0\\n\\nrouter = APIRouter(prefix=\\\"/monitor/traces\\\", tags=[\\\"Traces\\\"])\\n\\n\\n@router.get(\\\"\\\", response_model_by_alias=True)\\nasync def get_traces(\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n    flow_id: Annotated[UUID | None, Query()] = None,\\n    session_id: Annotated[str | None, Query()] = None,\\n    status: Annotated[SpanStatus | None, Query()] = None,\\n    query: Annotated[str | None, Query()] = None,\\n    start_time: Annotated[datetime | None, Query()] = None,\\n    end_time: Annotated[datetime | None, Query()] = None,\\n    page: Annotated[int, Query(ge=0)] = 1,\\n    size: Annotated[int, Query(ge=1, le=200)] = 50,\\n) -> TraceListResponse:\\n    \\\"\\\"\\\"Get list of traces for a flow.\\n\\n    Args:\\n        current_user: Authenticated user (required for authorization)\\n        flow_id: Filter by flow ID\\n        session_id: Filter by session ID\\n        status: Filter by trace status\\n        query: Search query for trace name/id/session id\\n        start_time: Filter traces starting on/after this time (ISO)\\n        end_time: Filter traces starting on/before this time (ISO)\\n        page: Page number (1-based)\\n        size: Page size\\n\\n    Returns:\\n        List of traces\\n    \\\"\\\"\\\"\\n    try:\\n        sanitized_query = sanitize_query_string(query)\\n        # Frontend uses 0-based pages; repository expects 1-based.\\n        effective_page = max(page, 1)\\n        return await asyncio.wait_for(\\n            fetch_traces(\\n                current_user.id,\\n                flow_id,\\n                session_id,\\n                status,\\n                sanitized_query,\\n                start_time,\\n                end_time,\\n                effective_page,\\n                size,\\n            ),\\n            timeout=DB_TIMEOUT,\\n        )\\n    except asyncio.TimeoutError:\\n        logger.warning(\\\"Traces query timed out after %ss (table may not exist or DB is slow)\\\", DB_TIMEOUT)\\n        return TraceListResponse(traces=[], total=0, pages=0)\\n    except (OperationalError, ProgrammingError) as e:\\n        logger.debug(\\\"Database error getting traces (table may not exist): %s\\\", e)\\n        return TraceListResponse(traces=[], total=0, pages=0)\\n    except Exception:\\n        logger.exception(\\\"Unexpected error getting traces\\\")\\n        raise\\n\\n\\n@router.get(\\\"/{trace_id}\\\", response_model_by_alias=True)\\nasync def get_trace(\\n    trace_id: UUID,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n) -> TraceRead:\\n    \\\"\\\"\\\"Get a single trace with its hierarchical span tree.\\n\\n    Args:\\n        trace_id: The ID of the trace to retrieve.\\n        current_user: The authenticated user (required for authorization).\\n\\n    Returns:\\n        TraceRead containing the trace and its hierarchical span tree.\\n    \\\"\\\"\\\"\\n    try:\\n        result = await asyncio.wait_for(\\n            fetch_single_trace(current_user.id, trace_id),\\n            timeout=DB_TIMEOUT,\\n        )\\n        if result is None:\\n            raise HTTPException(status_code=404, detail=\\\"Trace not found\\\")\\n    except HTTPException:\\n        raise\\n    except asyncio.TimeoutError:\\n        logger.warning(\\\"Single trace query timed out after %ss\\\", DB_TIMEOUT)\\n        raise HTTPException(status_code=504, detail=\\\"Database query timed out\\\") from None\\n    except (OperationalError, ProgrammingError) as e:\\n        logger.debug(\\\"Database error getting trace: %s\\\", e)\\n        raise HTTPException(status_code=500, detail=\\\"Database error\\\") from e\\n    except Exception as e:\\n        logger.exception(\\\"Error getting trace\\\")\\n        raise HTTPException(status_code=500, detail=\\\"Internal server error\\\") from e\\n    else:\\n        return result\\n\\n\\n@router.delete(\\\"/{trace_id}\\\", status_code=204)\\nasync def delete_trace(\\n    trace_id: UUID,\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n) -> None:\\n    \\\"\\\"\\\"Delete a trace and all its spans.\\n\\n    Args:\\n        trace_id: The ID of the trace to delete.\\n        current_user: The authenticated user (required for authorization).\\n    \\\"\\\"\\\"\\n    try:\\n        async with session_scope() as session:\\n            stmt = (\\n                select(TraceTable)\\n                .join(Flow, col(TraceTable.flow_id) == col(Flow.id))\\n                .where(col(TraceTable.id) == trace_id)\\n                .where(col(Flow.user_id) == current_user.id)\\n            )\\n            trace = (await session.exec(stmt)).first()\\n\\n            if not trace:\\n                raise HTTPException(status_code=404, detail=\\\"Trace not found\\\")\\n\\n            await session.delete(trace)\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        logger.exception(\\\"Error deleting trace\\\")\\n        raise HTTPException(status_code=500, detail=\\\"Internal server error\\\") from e\\n\\n\\n@router.delete(\\\"\\\", status_code=204)\\nasync def delete_traces_by_flow(\\n    flow_id: Annotated[UUID, Query()],\\n    current_user: Annotated[User, Depends(get_current_active_user)],\\n) -> None:\\n    \\\"\\\"\\\"Delete all traces for a flow.\\n\\n    Args:\\n        flow_id: The ID of the flow whose traces should be deleted.\\n        current_user: The authenticated user (required for authorization).\\n    \\\"\\\"\\\"\\n    try:\\n        async with session_scope() as session:\\n            flow_stmt = select(Flow).where(col(Flow.id) == flow_id).where(col(Flow.user_id) == current_user.id)\\n            flow = (await session.exec(flow_stmt)).first()\\n\\n            if not flow:\\n                raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n\\n            # Single statement avoids N+1 deletes when a flow has many traces.\\n            delete_stmt = sa.delete(TraceTable).where(col(TraceTable.flow_id) == flow_id)\\n            await session.execute(delete_stmt)\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        logger.exception(\\\"Error deleting traces by flow\\\")\\n        raise HTTPException(status_code=500, detail=\\\"Internal server error\\\") from e\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/users.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"461d87de8558c7eaeb57f80c825dff1553ab3c7c59a2eb132d1913a7a5ea09b7\",\"content\":\"from typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, Depends, HTTPException\\nfrom lfx.services.authorization import (\\n    AuthorizationMutation,\\n    AuthorizationMutationKind,\\n    AuthorizationMutationRejected,\\n    UserAuthorizationSnapshot,\\n)\\nfrom lfx.utils.util_strings import escape_like_pattern\\nfrom sqlalchemy import func\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import select\\nfrom sqlmodel.sql.expression import SelectOfScalar\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.schemas import PasswordResetRequest, UsersResponse\\nfrom langflow.initial_setup.setup import get_or_create_default_folder\\nfrom langflow.services.auth.utils import get_current_active_superuser, get_current_user_optional\\nfrom langflow.services.authorization.audit import (\\n    AUDIT_EVENT_ACCESS,\\n    AUDIT_EVENT_MUTATION,\\n    audit_decision,\\n    stage_audit_decision,\\n)\\nfrom langflow.services.authorization.lifecycle import (\\n    acquire_identity_mutation_lock,\\n    safe_identity_mutation_committed,\\n    stage_identity_mutation,\\n    validate_identity_mutation,\\n)\\nfrom langflow.services.database.models.user.crud import get_user_by_id, update_user\\nfrom langflow.services.database.models.user.model import User, UserCreate, UserRead, UserUpdate\\nfrom langflow.services.deps import get_auth_service, get_authorization_service, get_settings_service\\n\\nrouter = APIRouter(tags=[\\\"Users\\\"], prefix=\\\"/users\\\")\\n\\n\\nasync def _audit_deny(\\n    *,\\n    user_id: UUID | None,\\n    action: str,\\n    obj: str,\\n    status_code: int,\\n    reason: str,\\n) -> None:\\n    await audit_decision(\\n        user_id=user_id,\\n        action=action,\\n        obj=obj,\\n        result=\\\"deny\\\",\\n        details={\\\"event\\\": AUDIT_EVENT_ACCESS, \\\"status_code\\\": status_code, \\\"reason\\\": reason},\\n    )\\n\\n\\n@router.post(\\\"/\\\", response_model=UserRead, status_code=201)\\nasync def add_user(\\n    user: UserCreate,\\n    session: DbSession,\\n    current_user: Annotated[User | None, Depends(get_current_user_optional)],\\n) -> User:\\n    \\\"\\\"\\\"Add a new user to the database.\\n\\n    This endpoint backs two flows that share the same route:\\n\\n    * Public sign up (unauthenticated). Allowed only when public registration is\\n      enabled for the deployment, i.e. AUTO_LOGIN is off (multi-user mode) and\\n      ENABLE_SIGNUP is True.\\n    * Admin \\\"add user\\\" (authenticated active superuser). Always allowed,\\n      regardless of the sign up settings, so disabling public sign up does not\\n      break superuser-driven user creation.\\n\\n    User activation is controlled by the NEW_USER_IS_ACTIVE setting.\\n    \\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    auth_settings = settings_service.auth_settings\\n    # An authenticated active superuser ";
